window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_031"]={"n":"释函可","dyn":"明","poems":[{"t":"春雨","f":"五言古诗","c":["春日无不可，倏忽易晴阴。","春晴送远目，春阴生静深。","垂帘据半榻，群动不得侵。","残卷落枕头，默默横素琴。","檐霤发奇响，欲洗无尘襟。","风铃湿不鸣，禽鸟息高林。","耳目乃森肃，今古同幽寻。","孤吟从中来，古木助清音。","雨止籁俱寂，悠然获我心。","我心岂由物，遇物屡悲欣。","起觅已无端，微云散遥岑。"]},{"t":"夜坐","f":"五言古诗","c":["久病长宜静，山中静有馀。","况当深夜后，积雪在庭除。","风枝寂不鸣，四壁虫晏如。","星斗宿檐际，微月淡空虚。","其时心腑澄，泰然廓吾庐。","云影暂舒卷，荡涤返太初。","天地化为水，何处觅吾躯。"]},{"t":"山境","f":"五言古诗","c":["山境只如此，一一皆可悦。","有石无不松，有松无不雪。","日夕众烟空，微钟上初月。","禽各静其枝，虎亦安其穴。","千峰一皓然，竟与人寰绝。","仁义属荣华，道法徒餔歠。","我舌久已焦，我心久已决。","安得一二人，把臂不须说。"]},{"t":"连雨","f":"七言古诗","c":["顽云重雾裹城郭，旧民新民惨不乐。","田中有黍谁能穫，山中有木谁能斲。","盘翻灶冷守空橐，檐溜虽多不堪嚼。","老僧一钵久庋阁，出门半步泥没脚。","紫蛇有光蜗有角，抱书昼卧肠萧索。","庭边杏树惊摇落，燕巢已破子漂泊。","眼前大地何时廓，辽海浪高势磅礴。","愿浮我尸填大壑，毋使蛟龙终日恶。"]},{"t":"忆江南","f":"古风","c":["江南高座寺，前对雨花台。","台上春风拂面来，参差杨柳花竞开。","黄莺百啭我心哀，忽忆故山村底梅。","今年绝漠冰雪堆，发白面皱骨欲摧。","村底无梅不归去，却忆高座听莺语。"]},{"t":"初释别同难诸子","f":"五言律诗","c":["终岁愁连苦，生离且莫哀。","问人颜尚在，见影意犹猜。","佛道千秋重，汤仁一面开。","明知予未死，好去勿徘徊。"]},{"t":"初至沈阳","f":"五言律诗","c":["开眼见城郭，人言是旧都。","牛车仍杂沓，人屋半荒芜。","幸有千家在，何妨一钵孤。","但令舒杖屦，到此亦良图。"]},{"t":"寒宵二首 其一","f":"五言律诗","c":["岂必缘乡国，啾啾闹肺肠。","天当愁处窄，夜向醒边长。","海水流何极，朋情散未忘。","以兹难得晓，星月共苍茫。"]},{"t":"寒宵二首 其二","f":"五言律诗","c":["只是不能寐，寻思总莫干。","何人甘自溺，于我竟难宽。","照雪一灯白，迎风双眼酸。","强眠仍反侧，非是畏衾寒。"]},{"t":"丙戌元旦顾家楼","f":"七言律诗","c":["多难还馀善病身，栖栖终不怨风尘。","挈瓢戴雪逢遗老，著屐寻诗有故人。","夜雨暂将山色改，年光又逐泪痕新。","遥知乡国东风早，花信凭吹薄海春。"]},{"t":"生日","f":"七言律诗","c":["当年坠地即严冬，怪得边城霜气浓。","孺慕终身思墓草，君恩累代听山钟。","摽鞋独羡陈尊宿，飞锡真惭邓隐峰。","四十已过能几日，一生心事倚孤筇。"]},{"t":"皇天","f":"七言律诗","c":["皇天何苦我犹存，碎却袈裟拭泪痕。","白鹤归来还有观，梅花斫尽不成村。","人间早识空中电，塞上难招岭外魂。","孤雁乍鸣心欲绝，西堂钟鼓又黄昏。"]},{"t":"李公赎陈氏为尼三首 其一","f":"七言律诗","c":["学士行歌绩妇迎，惊回春梦起乡情。","解将腰带文犀重，添得空门水月清。","云鬓已随秋雾散，舞衣应逐雨花轻。","翻怜冢畔青青草，不及红莲碛上生。"]},{"t":"闻钱君至尚阳堡死","f":"七言律诗","c":["相逢不禁泪淋浪，忽讶音来我自伤。","一片心肝还日月，五更风雪裹文章。","黄沙随梦归香阁，白水招魂入宝坊。","莫为中原难侧足，故将残骨掷龙荒。"]},{"t":"赠赤公五首 其一","f":"七言律诗","c":["几年辽海自依依，华表惊添一鹤飞。","瓶钵已非形更瘦，须眉犹在事多违。","长边无地容行脚，尽日徼天幸掩扉。","韎韐未裁磨衲破，梦中还著老莱衣。"]},{"t":"题铁岭燕巢","f":"七言律诗","c":["巷口荒芜旧路迷，移巢将鷇傍山溪。","未能仙峤同高翮，敢向穷檐恨落泥。","似惜衣冠惊避远，难忘恩谊故飞低。","门前便是鹰鹯集，纵有雕梁未可栖。"]},{"t":"寄讯堡中吴子","f":"七言绝句","c":["莫为饥寒瘦不禁，三人惟尔绝来音。","孤僧有梦还应入，辜负寒灯夜夜心。"]},{"t":"重入千山二绝 其一","f":"七言绝句","c":["偶然飞去复飞还，几见云能离得山。","旧路依稀犹可认，石桥流水第三湾。"]},{"t":"重入千山二绝 其二","f":"七言绝句","c":["万壑千峰是旧知，此回相见异前时。","寒鸦亦似曾相识，两两飞来低树枝。"]},{"t":"雨中听打铁子唱吴歌","f":"五言古诗","c":["孤寺沙四围，曲声从中起。","初发雨霏微，须臾忽滂沛。","飘风绕屋梁，遏云云欲坠。","鸾吹与莺啼，化作清商意。","神女朝暮愁，鲛人深下泪。","半夜弹箜篌，河流终瀰瀰。","此地多野干，镇日鸣不已。","愿借清绝音，一为洗烦耳。","乍听疑广陵，又疑秦淮沚。","试问歌者谁，云是打铁子。","少小学阊门，随飙度辽海。","无食涩歌喉，挥锤涕如雨。","再请歌一曲，未歌先掩袂。","宛转更悲凉，增我流离思。"]},{"t":"山谣","f":"古风","c":["一尺土，一寸膏。","膏夜流，土生涛。"]},{"t":"神谣","f":"古风","c":["人肉馨，神眼睁。"]},{"t":"多多谣","f":"古风","c":["灵蛇头，觔竹袖。","皇英韨，多多有。","千年龟，张大口。","燕支税，多多有。","锦牛驼，银狮吼。","死人汁，多多有。"]},{"t":"耿耿二章","f":"古风","c":["耿耿双瞳，游于面间。","瞩人则易，瞩己则难。","勿谓无非，无非非至。","勿谓无知，人将瞩尔。","己非毋匿，人非毋刻。","躬厚薄责，大人之特。","突如其来，突如其已。","念生无根，与物为至。","纷纭不辍，毋用遏绝。","知幻即离，空明如月。"]},{"t":"佛不在木一章章十句","f":"古风","c":["佛不在木，念不在珠。","绵绵不断，无欠无馀。","厥色维紫，厥质维樗。","渠今即我，我不是渠。","永言数之，渠我如如。"]},{"t":"山鬼四章章四句","f":"古风","c":["明月在天，塔影在地。","北风凄凄，惟吾与尔。","塔影在地，明月在天。","汝不我处，人谁汝怜。","汝惟一舌，我惟一脚。","我啸汝歌，汝歌我跃。","天地草草，山河落落。","霜老星残，云胡不乐。"]},{"t":"乐神辞三章 其一","f":"楚辞体","c":["星为马兮云为辔，生为忠兮死为厉。","草有子兮山有麂，腰铁铃兮冠雉尾。","击鼓其镗兮回瞋作喜，琉璃堂兮血食斯地。"]},{"t":"乐神辞三章 其二","f":"楚辞体","c":["儿孙为田兮魂魄为粮，神年丰兮国为良。","银者白兮金者黄，以赎命兮身面光，一人安居兮保边疆。"]},{"t":"乐神辞三章 其三","f":"楚辞体","c":["黑云压兮金乌藏，鼓声死兮剑无芒。","血为碧兮骨为霜，五陵墟兮万井荒。","笔墨精兮职为郎，翠钿委地魂魄芳。","日吉兮时良，陈列兮馨香，马有湩兮豕有肠。","舞窈窕兮歌琳琅，明星烂兮乐未央。","曰既醉兮云路倘佯，毋厄兹土兮福祚长。"]},{"t":"枯鱼过河泣 其一","f":"五言古诗","c":["枯鱼过河泣，劝鱼且莫泣，劝鱼且莫悲。","蛟龙有时斩，何况鲂与鲵。"]},{"t":"枯鱼过河泣 其二","f":"五言古诗","c":["枯鱼过河泣，劝鱼且莫泣，劝鱼且莫悲。","若能一滴水，扬鬣还天池。"]},{"t":"善哉行 其一","f":"古风","c":["日月烛照，民多纰缪。","川岳流峙，民用搆斗。","揖让在前，征诛在后。","世无伯夷，刬薇种豆。","匪知何寇，匪庸何富。","冯道登仙，云中稽首。","白凤就烹，素麟出走。","载沉载浮，以永厥寿。","稼穑既教，生乃弗谷。","百草既尝，疾乃弗救。","星斗在胸，江河在口。","松柏丸丸，斧斤祇候。"]},{"t":"善哉行 其二","f":"古风","c":["南有佳人，颜色静好。","爱而不见，郁我怀抱。","昨日犹壮，今日已老。","何以却之，出门刈稻。","心洞雨晴，目开天扫。","悠哉悠哉，孰知大道。","仰掇玄露，俯拾瑶草。","薄言置之，无求是宝。","树下一宿，日中一饱。","古之圣贤，无他谬巧。","众荣亦荣，众槁亦槁。","瞻彼蚩蚩，惄焉如捣。"]},{"t":"短歌行","f":"古风","c":["前后左右，四面八方。","忧愁骈集，我何可当。","欲寄天上，虑天弗禁。","欲埋地下，恐地将沉。","不如收拾，置我怀抱。","寝之食之，于焉终老。","沧海何阔，蓬莱何高。","世无黄鹄，乘我游翱。","古之侠士，尘视生死。","凡今之人，畏首畏尾。","好谋弗终，时命终穷。","东南失利，西北多凶。","黄沙为棺，白云为椁。","我则如是，千秋寥落。"]},{"t":"长歌行","f":"古风","c":["我歌我歌，旧民犹可，新民奈何。"]},{"t":"薤露歌","f":"古风","c":["薤上露，畏白日，日出露乾无遗迹。","古今杳杳无消息，宝马空嘶垄树直。"]},{"t":"蒿里曲","f":"古风","c":["蒿里谁家地，日夕悲风起。","命尽五更头，不到五更尾。","狐狸招手人不知，脚下黄泉尺有咫。"]},{"t":"秋思","f":"五言古诗","c":["鸿雁逐飞云，青天亦有行。","兄弟本四人，仲季歘云亡。","伯窜东海隅，叔留南海旁。","相隔万馀里，东南永相望。","忆昔在长安，膝下共两双。","朝去候门扉，朝回牵衣裳。","忆昔在南国，齐揖事先王。","教训日以严，道义日以康。","忆昔在家园，气力各自强。","读书穷壶兴，落笔竞沅湘。","神异古人遇，举世无文章。","当春二三月，风吹百草长。","登堂献寿酒，散步陟崇冈。","夏日听黄鹂，阴阴亭馆凉。","折荷绿玉池，剥荔黄金床。","桐叶下金井，四围橘柚黄。","薄暮向空阶，联袂延月光。","忽见梅花发，大开楼上窗。","色映枝枝玉，诗成字字香。","好景必同赏，佳酿必同尝。","夜寒必同被，得句必同商。","先子忽见背，血泪尽汪洋。","三载草土中，不离阿母傍。","伯也忽瞿然，团圞非久长。","拜母别诸弟，薙发栖大匡。","仲弟登贤书，云路步前芳。","叔弟薄青衿，欣然慕老庞。","阿季独俶傥，走马少年场。","抱志虽各殊，骨肉不相忘。","一朝日月坠，大地共仓皇。","紫荆长枝折，飘零天一方。","寄书阻兵革，得罪饱冰霜。","远碛听笳吹，回头盼故乡。","前月片纸来，摧胸裂肝肠。","闾井十无一，举家惨罹殃。","叔弟尚伏枕，一命在微茫。","母死恐未葬，弟死谁盖藏。","登山苦无梯，涉河苦无梁。","山木何翛翛，河水何汤汤。","安得高飞翼，驾我以翱翔。","狂雨日下来，白昼黑淋浪。"]},{"t":"秋思曲","f":"楚辞体","c":["山峨峨兮水盘盘，念佳期兮秋月圆。","揽衣视夜兮风雨迎门，彼美人兮梅一村。"]},{"t":"静夜吟 其一","f":"古风","c":["秋夜如漆我心忧，醒亦忧，寐亦忧。","兼之蟋蟀，苦鸣不休。","揽衣忽坐起，还卧泪横流。","大风吹树何飕飗，床头书鬼声啾啾。","家乡已荡尽，胡为身独留。"]},{"t":"静夜吟 其二","f":"五言绝句","c":["我有一点心，暗风吹已碎。","一半福州山，一半浔江水。"]},{"t":"少年行","f":"五言绝句","c":["红日射高楼，歌声不肯休。","借问北邙山，几人曾白头。"]},{"t":"塞下曲","f":"五言绝句","c":["日落雁声急，萧条人独行。","偶看原上草，偏动黍离情。"]},{"t":"临高台 其一","f":"古风","c":["临高台，望行尘。","多少驱车向西去，曾无一个是新人。"]},{"t":"临高台 其二","f":"古风","c":["临高台，望东海。","海上潮回自有时，流民东来无返期。","愿平高台塞东海，毋使流民心骨碎。"]},{"t":"相逢行 其一","f":"五言绝句","c":["相逢路多岐，君东我自西。","莫问名和姓，回头知是谁。"]},{"t":"相逢行 其二","f":"五言绝句","c":["相逢大路侧，君南我自北。","袖里无黄金，终是不相识。"]},{"t":"相逢行 其三","f":"五言绝句","c":["相逢大路中，君西我自东。","不知为何事，但见马匆匆。"]},{"t":"相逢行 其四","f":"五言绝句","c":["相逢两复三，君北我自南。","明知不是伴，半揖略交谈。"]},{"t":"空城雀","f":"古风","c":["空城雀，腹中饥。","雀虽饥，无是非，莫向上林枝上栖。"]},{"t":"君马黄","f":"古风","c":["君马黄，四足忙，挥鞭意气何扬扬。","我独无马步道旁，我步踯躅君马狂。","下有不测之大堑，上有崎岖百折之崇冈。","万一失足，人马皆亡。","愿君下马为君指，林间有路平且康。"]},{"t":"长相思 其一","f":"古风","c":["长相思，来何迟。","荆山鼎就紫清归，六宫粉黛化作泥。","王母高居在瑶池，无数仙人进玉饴。","千秋万岁以为期，何不驾六龙中天飞。","青鸟衔书到海涯，杲杲出日，浮云蔽之。","长相思，不可知。"]},{"t":"长相思 其二","f":"古风","c":["长相思，暗泪披。","虫吟草根如知之，夜深佛火光希微。","钟鼓不鸣心肝摧，白云一片何处栖，故园紫荆馀枯枝。","长相思，见何时。"]},{"t":"长相思 其三","f":"楚辞体","c":["长相思，在上古。","神农虞夏皆黄土，手把黄土心欲诉。","黄土乌知予心苦，向空一掷散如雾。","天无门兮地无路，龙为鱼兮鼠为虎。","愿还苍生置三五，四海欣欣歌且舞。"]},{"t":"关山月 其一","f":"七言古诗","c":["月向巫闾山上出，不照人间照死骨。","死骨千年更不还，魂随山月度重关。","关山叠叠归魂苦，苍茫不记来时路。","闺中少妇独夜眠，心心嘱梦去寒边。","梦去魂归不得遇，明月如霜草虫语。"]},{"t":"关山月 其二","f":"古风","c":["关山月，何惨悽。","城上吹笛乌复啼，城下秋草白萋萋。","安得长风吹此月，直向石洞青松枝。","关山月，无尽时。"]},{"t":"来日大难","f":"古风","c":["来日大难，风雨在门。","今日有客，且共盘桓。","精卫衔木，东海必填。","匹夫立志，金石匪坚。","葛洪熟识，贻我大丹。","不愿长久，顾世多艰。","白雪充腹，敝絮遮寒。","咄咄罪夫，在天地间。","冥冥何用，栖栖亦戆。","沮溺弗为，何况孔孟。","朝歌亦入，盗泉亦饮。","下士笑之，上士同哂。"]},{"t":"有所思","f":"古风","c":["有所思，乃在村头三五树。","树上啁啾翠羽鸣，树下美人向空语。","此时山月定得闻，似解不解无伦绪。","一撚愁心到夜阑，凭谁寄与长边戍，山月似归天上去。"]},{"t":"树中草","f":"五言律诗","c":["微贱一茎草，寄生枯木中。","客土本无多，安敢望丰茸。","孤根藉纤露，暂此朝夕荣。","不择栋梁材，秪贵空能容。"]},{"t":"少年子","f":"古风","c":["白面少年子，无金空有心。","半夜许人半夜死，肯待东方天日临。","古来独爱荆轲义，易水一去无还志。","中王固佳，中柱亦喜。","舞阳死灰不足言，勾践嗟叹亦非知。","若将成败论，没却一片意。"]},{"t":"久别离","f":"古风","c":["久别离，已见塞鸿三度四度向南飞。","前岁寄书今岁至，开椷一片血淋漓。","读不得尽，卷而怀之，夜半作书报君知。","前有平安两字，后有相思一词。","后头是实前头非，殷勤拜祝泪纷披。","书来已辛苦，书去见何时。"]},{"t":"放歌行","f":"古风","c":["斫却孤桐，凤或来止。","堙却颍川，由或来洗。","古无天地，高下何论。","古无江河，清浊何分。","我有素琴，无弦一曲。","秋风乍来，声出林木。","亦盗亦廉，非夷非惠。","知我则希，我则何贵。","泰山一拳，沧溟一勺。","天日明明，亦胡能烛。"]},{"t":"陇头歌 其一","f":"古风","c":["陇头流水，或西或东。","哀此飞蓬，瞻望旧丛。","旧丛久空，忧心忡忡。"]},{"t":"陇头歌 其二","f":"古风","c":["陇头流水，声惨以悽。","落叶从之，永辞故枝。"]},{"t":"妾薄命","f":"古风","c":["十三嫁先夫，十四先夫死。","十五嫁后夫，十六后夫死。","两度踏君门，依然一童稚。","凤钗两股齐，罗衫色仍紫。","哭新兼哭旧，那复再生理。","吁嗟十七十八嫁何迟，惟恨当年错欢喜。"]},{"t":"雀飞多","f":"古风","c":["雀飞多，触纲罗，可奈何。","回头语飞乌，汝母翼折待汝哺。","饥不及朝，朝不及暮。","风中之烛枝上露，莫取盈仓填汝嗉。"]},{"t":"望夫石","f":"古风","c":["望夫石，江边守。","江易枯，石不朽。","生公说法也难听，直待夫来始回首。"]},{"t":"有所思","f":"古风","c":["有所思，所思亦何益。","我置君心于我心，君置我心于道侧。","君心似我胡可得，北斗在南南斗北。","泰山如砥平，黄河如箭直。","若得君心有转移，与君重复整相思。"]},{"t":"野田黄雀行","f":"五言古诗","c":["自识形躯小，窃愧羽毛黄。","野田随饮啄，短丛足翱翔。","且不羡鸿鹄，何况凤与凰。","笑彼斥鴳俦，徒欲上高冈。","高冈岂不乐，顾影亦惭惶。"]},{"t":"行路难","f":"古风","c":["行路难，不在山间与水间。","水有漩复，山有崎岖。","城门大道，荡荡愁予。","见人必恭敬，避人必欷歔。","欷歔亦何为，恭敬亦须臾。","人情不一，多凶少吉。"]},{"t":"秋思新泪","f":"五言古诗","c":["新泪拭不乾，古泪已及趾。","二仪清浊分，伤心从此起。","裸虫日汹汹，圣人凿其知。","饮食藏兵戈，结绳开祸始。","黄帝学道流，剪灭神农裔。","蚩尤纵无良，榆罔恶未极。","大哉夏禹功，泽流应万祀。","当桀放南巢，扈从何名字。","直待采薇人，兄弟标忠义。","忠义既以明，天下争一死。","荀息殉遗孤，明知是无益。","蒯聩命躯车，其仆乃结辔。","画邑布衣流，悬树续齐祀。","豫让行何苦，漆身乞于市。","所以为此者，将以愧后世。","汉祚当衰微，英雄纷举事。","臧洪据地时，陈容忽扬袂。","当日同座人，胡为空太息。","卓哉巴郡守，断头心罔贰。","晋惠昔蒙尘，百官皆散溃。","独有嵇侍中，衣血足捍卫。","周顗急呼天，卞壶长卧地。","此外亦寥寥，閒居谈名理。","唐有藩镇难，诸公何慷慨。","张兴解其尸，张巡抉其齿。","杲卿更愤激，钩舌詈不已。","阿弟死希烈，自草表与志。","屈强德宗朝，刘乃段秀实。","夺笏直唾面，投床遂不食。","乃有孙节度，受锯无绌志。","宋代光前古，编简难尽纪。","载观靖康初，十人辟和议。","第一欧阳珣，恸哭深州外。","徽言閤室焚，仗剑语将士。","令峸坚执膝，终不拜犬彘。","若水挝破唇，彦先刃左臂。","痛惜岳家军，十年一朝弃。","淮宁向子韶，建康杨邦乂。","不作他邦臣，宁作赵氏鬼。","北兵括地来，屈指数李芾。","取酒饮家人，遍刃无遗类。","幕属及潭民，举族多自缢。","林满井无虚，激厉乃如此。","亦有赵卯发，亦有江万里。","亦有宣抚陈，亦有少保李。","节义或一双，积尸或如垒。","或赴沼自明，或指腹自誓。","广王终崖门，陆张随入海。","于赫文文山，义尽仁乃至。","平日读诗书，庶几可无愧。","乾坤扫荡来，圣神广栽植。","烈烈复轰轰，又非宋代比。","书以白银管，藏以黄金匮。","地上反奄奄，地下多生气。","我欲从头哭，泪尽东海水。","白日且吞声，歌咏聊尔尔。"]},{"t":"采菌二首 其一","f":"五言古诗","c":["木生在高原，岂意烂作泥。","茂草蒙其头，牛羊践踏之。","自顾不敢怨，世事安可知。","每岁五六月，日晒雨复滋。","晔晔长新菌，五色转参差。","黄者金芙蕖，青者碧玉芝。","天地有正气，积郁不得施。","触物吐光艳，腐朽化神奇。","采采必盈筐，踌蹰发深思。","物理固难测，可以疗我饥。"]},{"t":"采菌二首 其二","f":"五言古诗","c":["三五趁晓晴，随云入涧壑。","志与枯槁遇，荣茂非我乐。","顾视深草间，异种纷相错。","恐是蛇虺居，根性乃独恶。","摈弃稍不严，美口成毒药。","气化岂有殊，君子慎所托。"]},{"t":"古意二首 其一","f":"五言律诗","c":["作花莫作菊，东篱成荒丛。","作木莫作松，孤高孰与同。","何如萧与艾，雨露亦丰茸。","节序暗易换，只恐是秋风。"]},{"t":"古意二首 其二","f":"五言律诗","c":["作鸟莫作凤，举世无梧桐。","作兽莫作麟，唐虞不再逢。","何如鸡与鹜，饮啄亦从容。","鼎俎久相候，安能长自雄。"]},{"t":"经言","f":"五言古诗","c":["朝出见歌舞，暮归见黄土。","此事未足奇，所奇在何处。","朝出见歌舞，暮归见歌舞。"]},{"t":"碛中三老咏 其一","f":"五言律诗","c":["龙鳞积深泥，郁吟岂其志。","江海起胡髯，一喷天地沸。","弟死身独留，此中有深意。","不作文文山，徒然歌正气。"]},{"t":"碛中三老咏 其二","f":"五言律诗","c":["读书抱区区，所争吾是人。","博浪偶不中，甘心东海尘。","万死存一卷，遇物吐其真。","手栽桃李花，将欲变荆榛。"]},{"t":"碛中三老咏 其三","f":"五言律诗","c":["割世一何毒，取义一何痴。","嬉笑歌哭间，往往见其微。","此事信莫委，一往遂不疑。","目视今古人，安顾圣贤嗤。"]},{"t":"落叶","f":"五言古诗","c":["空庭肃秋气，一叶最先飞。","众叶皆不顾，孤客暂相依。","曾受日光照，融和露复滋。","鸣禽争上下，繁阴覆阶墀。","谁能当此际，返念树上时。","御苑芳菲尽，何况托根微。","飘零固其分，污泥安敢辞。","寄语树上叶，千年长在枝。"]},{"t":"泪","f":"五言古诗","c":["我有两行泪，十年不得乾。","洒天天户闭，洒地地骨寒。","不如洒东海，随潮到虎门。"]},{"t":"示学人三十首 其一","f":"五言古诗","c":["古人有良规，不可去斯须。","隐微密自烛，非为外貌拘。","束己若不足，束人贵有馀。","苟非大圣心，恶能从勿踰。","岂不闻哲言，水清则无鱼。"]},{"t":"示学人三十首 其二","f":"五言律诗","c":["根实枝乃茂，源深流自长。","方寸苟自正，立世大堂堂。","人誉我胡亲，人毁我胡伤。","浮云一千里，难掩赫日光。"]},{"t":"示学人三十首 其三","f":"五言古诗","c":["大象踏兔径，达人略小节。","大本但勿渝，安能事琐屑。","硁硁然小人，闭口休辨别。"]},{"t":"示学人三十首 其四","f":"五言古诗","c":["大道如平砥，人自向高山。","不知千万程，近在足趾间。","出户复入户，何用苦烦难。"]},{"t":"示学人三十首 其五","f":"五言古诗","c":["粗粝亦充腹，破衲亦遮寒。","身口本无多，知足又何难。","纷纭世上人，至死不得閒。"]},{"t":"示学人三十首 其六","f":"五言古诗","c":["古人身上肉，今人足下尘。","尘为人所贱，昔时曾自珍。","幻躯何足论，所贵得其真。"]},{"t":"示学人三十首 其七","f":"五言古诗","c":["龙亦不在天，龙亦不在渊。","飞潜信有时，神物无一专。","莫为叶公好，头角空自悬。"]},{"t":"示学人三十首 其八","f":"五言律诗","c":["我从物则奴，物从我则主。","物我本无分，茫茫失所据。","反照识独尊，混然在一处。","虽与物去来，不共物来去。"]},{"t":"示学人三十首 其九","f":"五言古诗","c":["人生各有病，深浅惟自知。","百草不能至，扁鹊空攒眉。","佛祖入膏肓，此病最难医。"]},{"t":"示学人三十首 其十","f":"五言古诗","c":["言亦不可甚，行亦不可极。","行极无馀地，言甚无馀旨。","大人处世间，常留不尽意。"]},{"t":"示学人三十首 其十一","f":"五言古诗","c":["处安且毋喜，处危且无患。","得失无定形，祸福掌一反。","三复塞翁言，此心常坦坦。"]},{"t":"示学人三十首 其十二","f":"五言古诗","c":["逆流易自持，顺流多失措。","人世陷其身，不以危险故。","君子慎平康，一步一回顾。"]},{"t":"示学人三十首 其十三","f":"五言古诗","c":["入世毋强同，强同多厚颜。","入世无强异，强异难独全。","平生默自抱，不即不离间。"]},{"t":"示学人三十首 其十四","f":"五言律诗","c":["少年易使气，俗物必遭吐。","忽遇其中人，胸肝急披露。","老大足和平，于世或无忤。","泾渭难自浑，时复露其故。"]},{"t":"示学人三十首 其十五","f":"五言古诗","c":["花不与蝶期，花发蝶自痴。","世不与人期，而人自干之。","遇物苟无心，纷然无是非。"]},{"t":"示学人三十首 其十六","f":"五言古诗","c":["老人莫自伤，白发抵黄金。","请看台下土，尽是少年心。","晓起若有待，晚来何处寻。"]},{"t":"示学人三十首 其十七","f":"五言古诗","c":["为恶祇自残，为善亦有数。","善恶皆幻生，劳劳成今古。","若识非幻者，无欣亦无恶。"]},{"t":"示学人三十首 其十八","f":"五言古诗","c":["有作必有受，须知无受者。","昔日与今时，互换形皆假。","稽首狮子尊，痴人徒嗟呀。"]},{"t":"示学人三十首 其十九","f":"五言古诗","c":["山翠亦有色，溪流亦是声。","居心苟不静，山水是非生。","请看金马门，谁辨浊与清。"]},{"t":"示学人三十首 其二十","f":"五言古诗","c":["形骸暂相托，保护尔何为。","一息苟不来，撇之去如遗。","君看捣药人，谁能白昼飞。"]},{"t":"示学人三十首 其二十一","f":"五言古诗","c":["日用亦有限，世人重光辉。","心计苦不足，倏忽西日颓。","劳我一生力，营他眼前为。"]},{"t":"示学人三十首 其二十二","f":"五言古诗","c":["江海本无波，飙风不停吹。","我心与境接，日夜纷交驰。","若了心境幻，彼此不相知。"]},{"t":"示学人三十首 其二十三","f":"五言古诗","c":["行止镇相随，不识何面口。","自古称上贤，只此无先后。","可怜照镜人，迷头日狂走。"]},{"t":"示学人三十首 其二十四","f":"五言古诗","c":["见人学恭敬，坦率招时嫉。","缛节与閒言，涂饰度朝日。","安得古初民，相与宝真实。"]},{"t":"示学人三十首 其二十五","f":"五言古诗","c":["结交若如初，何必重雷陈。","学道若如初，释尊满界尘。","大法本无多，久长难得人。"]},{"t":"示学人三十首 其二十六","f":"五言古诗","c":["丈夫贵立志，万古只斯须。","举步稍旁顾，寸地阻前趋。","壮哉海岸人，蛟龙还其珠。"]},{"t":"示学人三十首 其二十七","f":"五言古诗","c":["尘生在毫芒，人鬼莫能窥。","勿谓此纤纤，郁勃闭阳辉。","不见沧海流，其初涓滴微。"]},{"t":"示学人三十首 其二十八","f":"五言古诗","c":["巨鱼争洪波，细鳞集蹄涔。","巨细虽各别，共此朝暮心。","我生复何营，空林张素琴。"]},{"t":"示学人三十首 其二十九","f":"五言古诗","c":["片云起前山，飞来复飞去。","日夕众鸟栖，微风息庭树。","我心与之然，淡寂冥群虑。"]},{"t":"示学人三十首 其三十","f":"五言古诗","c":["子规啼不息，中情谅无极。","鲜血流树枝，入地深一尺。","去去复何云，月来山寂寂。"]},{"t":"与藏主夜谈三首 其一","f":"五言古诗","c":["道穷易感恩，况有一片意。","谈深忘夜寒，皎月从中起。","心期正未涯，人世薄于纸。"]},{"t":"与藏主夜谈三首 其二","f":"五言古诗","c":["高林不择鸟，大海不择流。","流多海益深，鸟多林益稠。","达人贵胸襟，毋为细琐求。"]},{"t":"与藏主夜谈三首 其三","f":"楚辞体","c":["善乃恶之对，福兮祸所依。","所以学道人，恬淡贵自持。","只此一瓢水，世世以为期。"]},{"t":"采菊","f":"五言古诗","c":["道傍见残菊，幽幽生意微。","落英沉无多，安能疗我饥。","折来置空鉼，共此秋风吹。"]},{"t":"孤吟","f":"五言古诗","c":["空洞接混濛，其中有日月。","古哲亲至前，万象森以列。","草木共话言，死骨亦得活。","明和春山晖，严凝洒冰雪。","石池起层波，浩浩皆鲜血。","鱼龙各生愁，方寸恣出没。","点画入重玄，十指电光掣。","星斗尽下来，八方不盈撮。","倏忽天地冥，鬼神栖其穴。","残魄静独抱，性光自相悦。","此际吾不知，虽知不能说。"]},{"t":"寒还将行过宿","f":"五言古诗","c":["忆初与子遇，我命如悬丝。","子时顾我泣，岂意共边陲。","三岁相形影，孤雁常双栖。","是夜足风雨，来将与我辞。","人情欲分手，先问后晤期。","子今从此去，心知见无时。","死别在一割，生别长苦思。","子生必思我，我死子安知。","同是笼中翼，一伏一出飞。","人鬼不容发，安能复迟迟。","努力事前路，勿为儿女悲。","孤灯久已灭，起视夜何其。","开户天地黑，鸡声惨以悽。"]},{"t":"闻耀寰仓卒就道","f":"五言古诗","c":["边塞虽云苦，久客亦有情。","况复饮啄多，相与若弟兄。","言别已两月，依依不能行。","昨日顾荒寺，犹云候层冰。","今晨寄声来，急促事长征。","牛车满残帙，牵儿苦伶仃。","岂不惜离别，严驱无暂停。","寸心未一言，遥遥望前尘。"]},{"t":"中秋夜独坐","f":"五言古诗","c":["明月在檐楹，披衣我独行。","如何一步地，偏生万里情。","去去我欲眠，明月不须明。"]},{"t":"中秋同集雪斋","f":"五言古诗","c":["塞外亦团圆，道古情乃至。","宛然一家人，刬却流离意。","薄暮各言归，一一边愁起。"]},{"t":"采蜜","f":"五言古诗","c":["深山有君臣，大义不敢忘。","枯木以为国，百花以为粮。","何以服其众，无毒者为王。","王居必有台，众游必有方。","朝出暮乃归，一心无别肠。","自谓可无患，世事固难量。","烈炬何方来，举国纷仓皇。","兴亡掌一反，倏忽无遗良。","物类虽甚微，性命关上苍。","区区口腹欲，无乃太惨伤。","尔蜂亦何愚，蓄积召祸殃。"]},{"t":"采药","f":"五言古诗","c":["灵根产兹土，辽邈绝人际。","一本三四桠，围叶如张盖。","结实挺中央，颗颗坠红米。","高出众草上，百步望光采。","群生必有长，约略具形体。","无茎曰睡参，坚白味数倍。","天子怜病人，岁中必命采。","枵腹入深林，阴翳日月晦。","旧人去易归，新人迷道里。","抱参不敢嚼，往往饱虎兕。","神农开祸先，遗累终不已。"]},{"t":"赏花","f":"五言古诗","c":["人爱花开好，我畏花开早。","开早落亦先，旭日无常照。","世无魏与姚，各自矜芳号。","富贵岂久长，露晞色随槁。","我每见花哭，人争见花笑。","笑哭亦何关，衰荣本天造。","百物信有时，黄紫递光耀。","为语赏花人，徒然乱怀抱。"]},{"t":"狗奶子","f":"五言古诗","c":["中原所不识，神农所不载。","味酸性微寒，嘴尖腹渐大。","丛生缀短枝，浑疑人血洒。","碎捣蜜罗澄，粉如割成块。","陈列俎豆间，明明格上帝。","此物亦有时，黍稷皆下拜。"]},{"t":"赠两公子","f":"五言古诗","c":["公子年方少，举止皆老成。","阿兄益威重，阿弟神复清。","总角遭乱离，高冈无凤鸣。","从父窜东海，赤脚走层冰。","虽乏金与粟，卷帙犹满籯。","斗室足咿唔，晨夕披不停。","古人有心血，今人有眼睛。","读书只读字，大海无涯津。","性道本饮食，瓦砾通神明。","苟自得网纽，千载任纵横。","天地我注脚，何况是六经。","切磋即手足，菽水见模型。","搦管尔家事，文章出至情。","勖哉两公子，艰虞力弥增。","今古无别路，非关世上名。"]},{"t":"月","f":"五言古诗","c":["人家小儿女，举头见月笑。","山中老洞猿，见月一长叫。","物感固自殊，明月同一照。"]},{"t":"与希焦二道者夜谈漫纪","f":"五言古诗","c":["崔嵬丹凤阙，旁耸大罗宫。","中有两道士，老少颜皆童。","少者王子晋，老者是葛洪。","头戴五岳冠，霞裾佩玲珑。","相将步高坛，琅璈响碧空。","曲终天欲曙，紫雾杂幡幢。","有时草玄文，翩若戏海鸿。","有时看宝剑，光芒斗牛冲。","冰雪贮心腹，秋水湛方瞳。","架上九丹经，云锦百千重。","问以世间典，亦有旧诗筒。","疑尔食字化，又疑白鹤双。","忆我初来时，萧索若飘蓬。","李君下拜揖，遥指昆崙峰。","千尺水晶楼，白云有路通。","竹杖叩丹扄，一见气舂容。","不识人间礼，欣此邂逅逢。","饮我鸭绿江，食我西山松。","赠我白马牙，衣我千针缝。","乞者固无厌，施者意方隆。","共坐论南华，麈柄各横纵。","出门薄云车，金勒玉面骢。","瞬息三千里，往来若游龙。","匪特仙骨轻，兼之侠气雄。","最爱秦三良，三年煮石供。","忽闻胥靡饥，中心已忡忡。","欲将洛多士，尽置碧纱笼。","吁嗟下界苦，药裹安足充。","愿借白羽扇，熄此天地烽。","愿借太乙炉，榾柮燄方红。","全收古今愁，付此鼎中镕。","鍊成五色石，以补西北穹。","再借一指头，著我七尺筇。","一点医巫闾，化作万选铜。","白拂从中分，相峙若泰嵩。","一饱山中狼，一以济裸虫。","然后拾其馀，置之布袋中。","十日买一雨，五日买一风。","更买双凤凰，朝夕鸣梧桐。","一鸣黄河清，再鸣菽麦丰。","二仙笑余言，兹愿何匆匆。","一治复一乱，天运无终穷。","烽火夺炊烟，甲士讵为农。","閒愁亘古今，女娲叹无功。","狼贪不可厌，林林祸方丛。","古佛虽大悲，难挽水火风。","买风复买雨，能令宙合同。","何似买杲日，高挂扶桑东。","光照北邙山，永塞高下舂。","凤凰亦有死，黄鹄一飞翀。","骑之游九州，长笑入崆峒。","予复笑二仙，斯志亦未崇。","不如买鼠须，束笔拟长杠。","高旻展素笺，浩浩写心胸。","心胸亦何有，浮云日夜撞。","倾血三百斛，奔流泻石谼。","化作大海涛，一荡天地蒙。","冥漠前致辞，恍惚觌仪容。","知是前代人，燐光如白虹。","三读不二歌，声声噎寒钟。","二仙寂不言，怪涕亦无从。","暗风吹窗棂，残月若朦胧。","鸡声催天衢，妄谈犹未终。","吁嗟此一时，万年想高踪。","一个寒冰佛，长伴两木公。"]},{"t":"赠王三","f":"五言古诗","c":["仆走马复死，手中缺铜钱。","茆屋临道傍，床壁相新鲜。","长斋礼绣佛，但祝慈母年。","饭僧本性情，匪独于余偏。","瓶粟或不继，大笑断炊烟。","己饥犹可耐，人饥甚忧煎。","眼见陈氏子，欲啮无寸毡。","仓皇走道途，愿为觅数椽。","数椽亦易易，所贵主人贤。","下榻横药室，授经向市廛。","片瓦苟盖头，饱食即神仙。","予亦为陈子，朝夕心乾乾。","好事见他人，题诗后世传。"]},{"t":"雨夜留戴子共榻","f":"五言古诗","c":["尔从北山来，日暮扣荒寺。","开门两面愁，不语泪及趾。","半月绝相闻，岂意俱复在。","我心犹恍惚，是魂或是尔。","衣破露肘臂，所苦不得死。","相与藉草团，夜深僵无寐。","大雨黑飕飕，点滴到肝髓。","忽忆田中农，一听能无喜。","雨喜复雨愁，天心安有二。"]},{"t":"哭吴岸先","f":"五言古诗","c":["我生亦偶然，汝死何草草。","槛车忆初来，面凹露双肘。","既被冰雪侵，况复遭群侮。","有口难告人，束身守空窭。","汝书犹在眼，汝颜不复睹。","吁嗟骨似柴，安能厌豹虎。","四海尽秦坑，诗书同一炬。","二月金鸡飞，恨汝不得偶。","挥泪约同人，携灰反旧土。","兹愿又已乖，总入山鬼簿。","后先理亦齐，不如早还故。","地上莫能容，地下可相许。","苍苍久不闻，休向帝庭语。","吁嗟复吁嗟，万里馀妻女。","春闺梦或逢，肯道寒边苦。"]},{"t":"摘藤菜","f":"五言古诗","c":["清晓鸣辘轳，携杖入芳园。","中有满架藤，稠叠铺绿云。","不雨色常润，无风叶自翻。","圆实间深紫，灿烂吐奇文。","土人不肯顾，瓜茄乃盛盘。","异种生岭南，移裁东海漘。","地瘠饶霜雪，弱质焉久存。","一摘泪盈把，再摘心悲酸。","摘密休摘疏，聊以删芜繁。","轻指莫动摇，恐或伤其根。","虽知冷必死，且护眼前安。","昔日苏长公，题诗谪古循。","诸品独见推，谓可方吴莼。","予今窜远碛，旧国变荒榛。","亲朋无一在，见尔如故人。","柔滑淡相得，破铛煮泉新。","一筐贻北里，甘苦味共分。","尔藤亦不幸，处处逢逐臣。"]},{"t":"戴子卖衣买粟","f":"五言古诗","c":["昔日豪华子，挥金如粪泥。","举箸常千命，山海罗珍奇。","宾客归必醉，僮仆厌甘肥。","一朝窜绝域，无食但解衣。","解衣衣复贱，粒米如玉饴。","身口择所急，未寒先疗饥。","己饥尚可忍，所苦妻与儿。","老僧有破衲，朝夕幸得披。","仰面看皇天，霜雪不能飞。"]},{"t":"佳人","f":"五言古诗","c":["佳人年十八，生长自皇都。","结发嫁远人，谓是终身夫。","鸡狗亦相将，任逐东西徂。","西行过洞庭，东窜寓穹庐。","岂料一朝饿，顾盼及妾躯。","夫饿妾亦死，妾卖夫得苏。","掩袂请速行，东邻有积储。","红颜贱如土，斗粟贵如珠。","但得前夫饱，焉顾后夫痡。","夫痡齿复落，猛虎踞庭除。","十日不相容，苦勒解罗襦。","解襦兼解袒，赤身哭向隅。","不愿新人妾，宁愿旧人奴。","旧人与新人，仓皇走道途。","少小学刺绣，光绫三尺馀。","上有双蝴蝶，下有比目鱼。","只今拭枯眼，一片血模糊。","父母若早知，不如弃沟渠。"]},{"t":"崔氏筵食乾荔枝","f":"五言古诗","c":["岭南四五月，丹实喜垂垂。","贫者亦得饱，鸟雀各痴肥。","一别逾八载，寤寐长相思。","谁谓我此生，复有见尔期。","尔颜宁似旧，臭味已全非。","入手倍见惜，未嚼心伤悲。","想尔当繁茂，岂意落边陲。","见我良独愧，席上共珍奇。","我实谅尔心，人世贵相知。"]},{"t":"雪斋烧沉水香","f":"五言古诗","c":["草木抱真性，植根良独异。","当其枯槁时，众目安能识。","藉此星星火，可以格上帝。","鼻端绝往来，混然在一气。","氤氲托冥会，非关有夙契。","欲索已寂如，肺腑无不至。","彼此本同源，静中得其理。","何亲复何疏，当入枯鱼肆。"]},{"t":"雪中同我存围棋","f":"五言古诗","c":["世事尽如此，黑白安足争。","雪片大如掌，栖身复打枰。","十指化作水，犹闻落子声。"]},{"t":"雪晴见月","f":"五言律诗","c":["月以雪为骨，雪以月为神。","孤僧立其际，相与共一身。","僧老身易槁，雪薄骨成尘。","独留一片月，千年照海滨。"]},{"t":"一叶吟","f":"五言律诗","c":["众叶落地死，一叶枝上留。","虽自保朝夕，其奈无朋俦。","天日远不照，霜雪临其头。","大枝且摧折，尔叶能无忧。"]},{"t":"残菊","f":"五言古诗","c":["菊开人尽赏，菊残人尽弃。","我昔赏无心，今看有深意。","严霜摧其根，寒风吹不已。","岂独恋深秋，不向篱间死。","前芳恨莫留，后芳犹未至。","耐此朝暮心，徘徊冰雪里。"]},{"t":"二高过访","f":"五言古诗","c":["小阮如锋锐，大阮淡如水。","如锋令人歌，如水令人醉。","共割一片毡，南北馀二里。","不约过僧庐，久置人间礼。","趺坐草团中，相视忘我尔。","问禅禅不知，问字祸之始。","不见双足间，斑斑馀十趾。","正当语笑欢，忽然发长忾。","岂为逼饥寒，各有胸中事。"]},{"t":"瓶中芍药花","f":"五言古诗","c":["眷兹瓶中花，疑我梦中身。","我身半泥土，花开如有神。","忆昔少小遇，灿烂京华春。","富贵久凋落，金谷尽荒榛。","胡为留绝域，气色倍鲜新。","红白各异致，相对成芳邻。","白者性颇耐，红者先委尘。","因以悟物理，淡薄保其真。"]},{"t":"读杜诗","f":"五言古诗","c":["所遇不如公，安能读公诗。","所遇既如公，安用读公诗。","古人非今人，今时甚古时。","一读一哽绝，双眼血横披。","公诗化作血，予血化作诗。","不知诗与血，万古湿淋漓。"]},{"t":"古砚","f":"五言古诗","c":["余家端溪旁，持斧斲溪骨。","岁深积成林，真气资蓬勃。","一从板荡来，散作磨刀石。","墨池鼓风波，焚之恨无及。","奇觏乃于斯，转复生叹息。","古绣若苔斑，瑩然马肝色。","沿缺中已凹，定是千年物。","黑松发黯光，滑泽水不竭。","想其在空岩，无心求赏识。","良工苦经营，因以珍几席。","不知前代人，研尽几斗血。","神物固不常，自然遭磨折。","笑彼卞氏璞，欲遇徒三刖。","如何抱坚贞，静默守寒碛。","我见岂偶然，为之重拂拭。","再拜置诸怀，永以伴幽寂。"]},{"t":"从千山携龙牙回约诸子同啖","f":"五言古诗","c":["不是山中人，不识山中味。","采采须及时，盈筐叠山翠。","得以山中日，濯以山中水。","恬淡本性成，微苦亦有致。","楮鸡非其伦，弟薇友石耳。","携之入城郭，犹带山岚气。","一嚼清齿牙，再嚼沁心髓。","愿言啮雪人，共领山中意。"]},{"t":"偶怀","f":"五言古诗","c":["手把山中雪，欲寄城中人。","城中亦有雪，山雪净无尘。","鲜白却易点，愿言慎厥因。"]},{"t":"咏古二首 其一","f":"五言古诗","c":["富春不避世，渭水不匡时。","事会乃适然，隐见无预期。","鹰扬若有意，何异熊与罴。","羊裘若无心，客星光亦微。","营丘与钓台，千载高嵬嵬。"]},{"t":"咏古二首 其二","f":"五言古诗","c":["采莲入深谷，养此眉与须。","一朝事适逢，敢自爱幽隅。","以身为羽翼，岂曰为帝储。","安危在一割，汉道争须臾。","卓哉四老人，山水本空虚。"]},{"t":"清晓","f":"五言古诗","c":["清晓候门立，癯然骨空留。","举步衣尘飘，知是儒者流。","向我一长揖，未言知有求。","曰来自暮春，挟卷逐朋俦。","只言秋有花，谁知雪空稠。","许织既非素，颜瓢亦足羞。","男儿志四方，身口不自谋。","日饥犹可支，夜寒风飕飗。","击石爇□枝，即此是衾裯。","吾道乃终穷，悔不事荒畴。","薙发入空门，未审能见收。","我闻心惨裂，哽咽语不休。","止止勿复道，分钵润枯喉。","斯文天未丧，诗书安可雠。"]},{"t":"即事有寄二首 其一","f":"五言古诗","c":["贵贱本殊伦，祸福无常理。","大宝不发光，常恐逼神忌。","宁作井中泥，毋为江上水。","水清起波澜，泥浊甘同弃。","宁为井中蛙，毋作枝间翠。","枝高弋者慕，井深终有底。","达人置其身，不以众趋地。","卑污胜高明，高明吾深耻。"]},{"t":"即事有寄二首 其二","f":"五言古诗","c":["多难贱骨肉，豺虎同居止。","神驭若无方，爪牙奋其利。","盈盈天地间，出入将焉避。","防维非不同，耻辱皆有以。","所贵我无心，无心以终始。"]},{"t":"腊月九日夜","f":"五言古诗","c":["腊月九日夜，明星犹历历。","须臾布稠云，青天无间隙。","掩户拥敝裘，孤心守岑寂。","狂飙恣凭凌，千峰交剑戟。","魑魅集阶庭，豺虎成羽翼。","乾坤互叫号，百灵齐辟易。","鹊巢委尘泥，乔木无一直。","势压栋欲摧，谁复支半壁。","东南三尺窗，恍惚万矢射。","倾如裂缯声，枕上生霹雳。","河坼长白颓，纵横那可敌。","寒躯几欲死，乃见袈裟力。","终古竟如斯，帝心殊未测。","因思行道人，咫尺将焉适。","安得大布帷，万姓共栖息。"]},{"t":"对菊","f":"五言古诗","c":["河东一老翁，赠我菊一枝。","一枝四五花，众叶亦纷披。","沃以石泉水，培以高冈泥。","当此草木枯，孤生无乃奇。","春露既无分，秋霜安可辞。","负性宁或殊，存心良独希。","城中多嚣尘，对酒亦非宜。","所以避名园，并不羡东篱。","独爱山中人，相向共茆茨。","本无堪俗赏，非自宝幽姿。","日夕幸无营，寂然淡共持。"]},{"t":"采石耳","f":"五言古诗","c":["唐帽万仞崖，下临不见底。","乾叶挂危枝，苔藓烂苍紫。","黄鹄自去来，玄猿或游戏。","一僧年半百，吟啸倏然至。","左手提竹筐，右手悬双履。","陟险若康途，牵藤摘石耳。","石耳连石骨，净洁无纤滓。","不知几千年，巑岏积幽气。","或言冰雪生，或言雾烟寄。","瓦罐就泉烹，舒卷黑云腻。","荔枝非其伦，岕叶差可比。","始信深山中，自然有真味。"]},{"t":"笔管花","f":"五言律诗","c":["宛如青玉管，高卓白云间。","神农有遗方，食此可驻颜。","驻颜亦何益，聊以备朝飧。","或者轻我身，飘然返故山。"]},{"t":"散淡花","f":"五言古诗","c":["青茎发红葩，萧疏间山翠。","厥根众瓣攒，大都菘白类。","性既和且平，微苦亦有致。","其味信足嘉，其名亦足纪。","安得散淡人，相与长甘此。"]},{"t":"豆叶","f":"五言古诗","c":["匡山有豆叶，因以名其坪。","岂知大漠间，豆叶乱纵横。","物遇各有时，感兹双涕零。","中原易见知，芳洁荐神明。","何为弃道途，隐没众草并。","幸未馨群类，庶可遂其生。"]},{"t":"苦瓜","f":"五言律诗","c":["苦瓜生五岭，赖以解炎毒。","塞外亦繁生，不能悦群目。","我来无故人，见之等骨肉。","畏苦乃常情，甘兹信予独。"]},{"t":"网罟菜","f":"五言古诗","c":["菌生何多奇，千百类莫穷。","大抵托枯株，叠云高重重。","兹性迥自殊，卑栖污泥中。","污泥杂黄沙，河岸柳条丛。","土人不知名，曰与网罟同。","其处乃独下，其品乃独崇。","老氏不敢先，允为百代宗。"]},{"t":"冬日偶成十首 其一","f":"五言古诗","c":["一人有二心，何况二人同。","面交且莫论，鲍管亦匆匆。","落日变朝槿，微风丧秋桐。","兰室为枯肆，芳秽味俱浓。","安得一心人，相与耐寒冬。"]},{"t":"冬日偶成十首 其二","f":"五言古诗","c":["古人各有为，何况今之人。","黄金葬神仙，白纸裹儒绅。","最苦狮子皮，束缚老狐身。","为龟苦不灵，为麟苦不仁。","安得无为者，相与率天真。"]},{"t":"冬日偶成十首 其三","f":"五言古诗","c":["人兽不容发，何况信汝意。","汝意不可信，深井洪涛起。","出门见夜叉，入门守乡里。","谁能暮行渴，不饮渠中水。","是名毋幻村，英豪就中死。","安得无苦人，共谈清净理。"]},{"t":"冬日偶成十首 其四","f":"五言古诗","c":["咫尺有千嶂，何况见面希。","相去日以远，相期日以非。","坚白虽自矢，磨涅亦非宜。","苟非金与石，胡能终勿移。","厥初岂不光，厥后难可知。","安得守贞人，万里相因依。"]},{"t":"冬日偶成十首 其五","f":"五言古诗","c":["僮仆各有口，何况是闾里。","馨闻止门屏，恶声远亦至。","李下与瓜田，嫌疑须遥避。","莫言小节拘，踰闲从此始。","安得君子俦，相与慎行履。"]},{"t":"冬日偶成十首 其六","f":"五言古诗","c":["防微犹或疏，何况弛其太。","星星欲燎原，涓涓欲成海。","内心起芒忽，相续必以害。","咄哉野千流，口口矜无碍。","神明虽至耸，顾影恬莫怪。","安得持身者，终始期勿败。"]},{"t":"冬日偶成十首 其七","f":"五言古诗","c":["箪豆亦有争，何况是阿堵。","古圣喻毒蛇，道旁不肯顾。","往往骨肉残，伊维此之故。","苟免寒与饥，毋去人所恶。","外示夷之清，中怀蹠之污。","遂使烟霞间，翻作井市路。","安得乐道人，相与宝淡素。"]},{"t":"冬日偶成十首 其八","f":"五言古诗","c":["知美斯已恶，何况乐群称。","至道本平实，神鬼忌高明。","所以先哲言，为善无近名。","如何薋菉葹，欲播蕙芷馨。","志士宝心骨，浮俗吠虚声。","安得遁世俦，相与效鸿冥。"]},{"t":"冬日偶成十首 其九","f":"五言古诗","c":["大圣有定业，何况兹凡浊。","多福难自求，祸患依前躅。","劳劳亦何为，儿女同笑哭。","颜夭蹠乃寿，顺逆多反覆。","安得达命人，任运保幽独。"]},{"t":"冬日偶成十首 其十","f":"五言古诗","c":["我心殊靡定，何况他肺肠。","己物无二体，君子贵自强。","曾闻二十劫，诸道共相将。","胡为夏与冬，一岁判炎凉。","圣贤在一决，好恶宁有常。","未达法源底，怀忧欲成狂。","安得曼殊剑，破此梦幻场。"]},{"t":"刘老翁","f":"五言律诗","c":["河东止一家，夫妇俱老瘦。","膝下无儿孙，篱外无鸡狗。","我来度木桥，疾走出门候。","麦饭杂菜羹，呼佛不离口。"]},{"t":"黑雪","f":"五言古诗","c":["关东有黑雪，今乃睹其形。","青天无纤云，皎日争光明。","土人指往事，曰此非佳徵。","清白本其性，远近无殊称。","厥色稍不如，遂加以黑名。","雪尔宜自慎，最险是人情。"]},{"t":"阿字行后作七首 其一","f":"五言古诗","c":["少小不相识，缘师起相思。","毅然请独行，随身破衲衣。","崎岖七千里，出塞致书词。","见书兼见汝，见汝如见师。","我来八九年，是日一展眉。"]},{"t":"阿字行后作七首 其二","f":"五言古诗","c":["初至文殊寺，日暮雪绥绥。","冻手解皮囊，短札外无馀。","主人敬爱客，烧泉夜围炉。","遂罄乡国语，一一与泪俱。","或尔强欢笑，或自简残书。","谈道欲抗昔，言诗每起予。","得句必朗咏，时惊山鬼呼。","寒腊亦易过，从予策蹇驴。","遍视新流人，兼履旧边隅。","一闻西岳言，跃跃动衣裾。","爰登千山顶，翘望医巫闾。","分题写怪石，摘食尽野蔬。","冰解梨花落，兴尽春已徂。","扶杖过金塔，寺小足安居。","况复主人贤，善谑礼无拘。","经夏复经秋，凉风满庭除。","忽忆匡山期，掩卷赋归与。","严命难再淹，令我立踌蹰。"]},{"t":"阿字行后作七首 其三","f":"五言古诗","c":["言别多哽咽，况我大漠中。","我身如断梗，尔身亦飘蓬。","相聚虽一岁，恍惚数夕同。","尔留已多恨，尔去更何穷。","秋风振高林，落叶分西东。","雁飞不成队，菊开不成丛。","作书报汝师，兼上老人峰。","平安复平安，把笔心正忡。"]},{"t":"阿字行后作七首 其四","f":"五言古诗","c":["收拾旧布囊，新诗叠重重。","临行不敢泣，各自惨心容。","河冻不能俟，言寄海舶中。","仰看鹤路直，俯视鲸波重。","千里在呼吸，一杯浮虚空。","日星挂眉睫，灏气荡心胸。","禁声莫高吟，恐或惊鼍龙。"]},{"t":"阿字行后作七首 其五","f":"五言古诗","c":["且喜免霜雪，其如多风波。","知尔能自信，风波奈尔何。","因再整麻履，还向蓟门过。","京尘犹漠漠，京阙尚峨峨。","此地惟贵游，孤钵莫蹉跎。"]},{"t":"阿字行后作七首 其六","f":"五言古诗","c":["乞食过东鲁，敛策入白门。","白门我久游，故迹应尚存。","板桥通秦淮，高楼近长干。","虽无钟山松，雨花可盘桓。","旧识如相问，休言雪窖寒。"]},{"t":"阿字行后作七首 其七","f":"五言古诗","c":["稽首栖贤老，百拜华首台。","少病复少恼，步履永康哉。","月缺必复圆，鹤去必复回。","时序有循环，雪消春水来。","愿言各加飧，毋重念不才。"]},{"t":"尸林行后作","f":"五言古诗","c":["忆昔度庾岭，四人惟汝存。","况我被逐后，相访独殷殷。","乡邑久已破，眼中无别亲。","寻尸亦多事，啮雪非前因。","万里风波际，一瓢支远频。","华首重相问，然云果不仁。"]},{"t":"住金塔寺十四首 其一","f":"五言律诗","c":["前年驻跸峰，去年文殊寺。","到处名且过，由来无定止。","渴不过一瓢，饥不过箪食。","为生已有馀，乐哉颜氏子。"]},{"t":"住金塔寺十四首 其二","f":"五言绝句","c":["居山不在高，但自远城市。","城市非江河，日日波涛起。"]},{"t":"住金塔寺十四首 其三","f":"五言古诗","c":["亦是前朝寺，寺毁空浮图。","嵯峨插霄汉，寂寞守山隅。","老僧见再拜，持斧斫枯株。","曲直任天然，自手搆茆庐。","四壁坚且厚，一径不崎岖。","筑灶近古井，支床叠破书。","扫叶烧不尽，拾粟食有馀。","明月造其堂，猛虎伏其闾。","山前清浅流，可以濯我躯。"]},{"t":"住金塔寺十四首 其四","f":"五言古诗","c":["二月三月间，带雪长山蔬。","山蔬有后先，众类同一区。","青紫各异色，甘苦味亦殊。","知名仅八九，不复辨其馀。","山中无毒性，但食心无虞。"]},{"t":"住金塔寺十四首 其五","f":"五言古诗","c":["四月五月间，畦蔬摘有馀。","口腹亦何厌，贪得无贤愚。","言采岸边菌，兼采水中蒲。","菌味既已别，蒲根更复殊。","岭南金竹笋，恍惚可与俱。","十年忆乡土，口嚼心踌躇。"]},{"t":"住金塔寺十四首 其六","f":"五言古诗","c":["六月到七月，田中瓜已熟。","或如团白雪，或如削青玉。","白者既纯酣，青者更芳馥。","盈筐复盈盘，行路亦饱足。","中原莫与京，兹惟塞外独。","摘小莫摘大，大者弃道曲。","尔徒侈外观，人早鉴其腹。"]},{"t":"住金塔寺十四首 其七","f":"五言律诗","c":["八月摘山梨，九月摘山菊。","菊芳可代飧，梨酸可克腹。","软枣紫葡萄，牵蔓亦簇簇。","莫取献王公，聊可缀幽谷。"]},{"t":"住金塔寺十四首 其八","f":"五言古诗","c":["十月草木尽，孤松风萧萧。","托根大壑中，争期干云霄。","罗岳鲜旧干，钟山恣狂烧。","胡为深雪间，苍然自高标。","本非舟楫具，无烦雨露浇。","造物信偶遗，谁能矜后凋。","放情规矩外，寝卧任逍遥。","非图保天年，不材甘寂寥。","宁特顾者希，诟厉乃独饶。","贞介乃其性，敢曰淩寒飙。","珍重匠石流，毋使斧斤劳。"]},{"t":"住金塔寺十四首 其九","f":"五言古诗","c":["掘地得塔铃，摇之音寂然。","细想隆平日，众铃竞高悬。","但借微风力，声响远近传。","铃去声亦尽，销沉在何年。","此虽蒙尘土，乃复睹青天。","静默信可久，舌存安能全。"]},{"t":"住金塔寺十四首 其十","f":"五言古诗","c":["山下多荒土，开垦已三年。","种麦多不收，种稻乃得全。","种豆复种粟，种麻兼种棉。","以此为生活，终岁钁头边。","耕田博饭食，兹语古所传。"]},{"t":"住金塔寺十四首 其十一","f":"五言古诗","c":["一僧腰背曲，见予多笑颜。","少小绝世味，中岁历苦艰。","一从戈甲兴，展转岛屿间。","来此十载馀，不复问人寰。","日日荷锄出，日日负薪还。","自言用力惯，一生不敢閒。","令我闻斯言，惕然愧素餐。"]},{"t":"住金塔寺十四首 其十二","f":"五言古诗","c":["一僧尚年少，胡为耽幽寂。","结屋在高层，萧然徒四壁。","寒至尚开窗，狂飙吹几席。","仰眺远山明，俯视近溪直。","时来共话言，庶可慰朝夕。"]},{"t":"住金塔寺十四首 其十三","f":"五言古诗","c":["人尽称金塔，塔亦有虚名。","以此得实祸，残毁无完形。","吁嗟复吁嗟，三匝涕泪零。"]},{"t":"住金塔寺十四首 其十四","f":"五言古诗","c":["安居金塔寺，高吟金塔篇。","主人情缱绻，老病意留连。","今冬又且过，不敢拟来年。"]},{"t":"老僧","f":"五言古诗","c":["八十已有馀，九十颇不足。","曰生隆庆间，少小薄鱼肉。","其时边境宁，其时边谷熟。","饥馑未曾知，况复知杀戮。","何期过盛年，迁徒无停轴。","奔投海岛中，举眼少亲属。","薙发倚空王，依然被桎梏。","上荷皇天慈，纵之返山谷。","言从故里过，残败几间屋。","不闻旧人声，但闻山鬼哭。","虽复身首遗，凄凄恨孤独。","屈指廿载馀，不识何世俗。","我闻未及终，贮泪已满腹。","止止莫复言，岁序有往复。","今时正太平，努力事饘粥。"]},{"t":"读未央上黄岩诗有感用原韵三首 其一","f":"五言律诗","c":["联袂登飞云，婆娑云顶树。","夜半雨淋漓，倏忽千愁聚。","激发多微言，感君药石句。","黄岩有金仙，相期此生遇。"]},{"t":"读未央上黄岩诗有感用原韵三首 其二","f":"五言律诗","c":["我往匡庐日，君乘江上涛。","金轮雾欲散，巫山云尚帱。","行藏从此异，贡水忽相遭。","学道如积薪，内顾发呼号。"]},{"t":"读未央上黄岩诗有感用原韵三首 其三","f":"五言律诗","c":["良切斯民忧，岂曰邀世福。","调达佛之仇，车匿佛之仆。","见身各自殊，宁必恋空谷。","令我忆斯人，深山长痛哭。"]},{"t":"不寐作","f":"五言古诗","c":["城中有更鼓，一更如夜长。","山中无更鼓，长夜益凄凉。","初更剔灯坐，灯花灿光芒。","但愿得好睡，不复望嘉祥。","伏枕当二更，须臾到旧乡。","梦怯王令严，回首何匆忙。","开眼见窗白，疑是日之光。","披衣步前檐，星斗乱交横。","约略三更候，掩扉强依床。","敝絮轻如纸，病骨冷如霜。","展转多呻吟，百计觅睡方。","四更至五更，揣摩竟难详。","只闻山鬼啸，不闻鸡口张。","盼盼复盼盼，天运岂无常。","同卧皆熟寐，唯予起徬徨。","将恐长如此，万古黑茫茫。"]},{"t":"所闻","f":"五言律诗","c":["所闻未必虚，我心不可存。","所闻未必实，我心安可存。","天道无一至，人事有同还。","我自处其平，得失无悲欢。"]},{"t":"病腹","f":"五言古诗","c":["昔有学道人，语我护生理。","未饥必先食，未饱必先止。","自从乞食来，往往饱欲死。","非惟口腹贪，得饱良不易。","所以两岁前，腹病繇此起。","因循直至今，祸延犹未已。","乃悟人世间，满足神所忌。","一切毋令尽，灾患胡由致。"]},{"t":"黄熟香","f":"五言古诗","c":["黄熟可怜香，厥产在吾里。","土人呼马牙，血结色微紫。","其次即乌云，其次即马尾。","采择名女儿，纤纤勒玉指。","乾白净削除，细碎盈筐篚。","江南竞崇之，曰此胜沉水。","沉水比佳人，此比隐君子。","芳烈虽不如，甜静斯为贵。","豪达徇其名，贾人徇其利。","遂使黄熟香，氤氲满天地。","我来大漠中，永谢芝兰气。","何人遗此香，再拜泪及趾。","感别已经时，天外逢知己。","非惟臭味投，恭敬桑与梓。"]},{"t":"示定原","f":"五言古诗","c":["卓哉子之师，见予心罔二。","一笑割平生，萧然释重累。","命汝从予游，衣履常不匮。","愿汝作乔松，愿汝齐无畏。","汝归必瞋喝，恐汝学业坠。","师死殊铮铮，汝生宁愦愦。","我能亮汝心，见我多含泪。","汝行不自繇，汝志不自遂。","所以咫尺隔，经月复经岁。","我实愧汝师，汝颜不须愧。","饮啄匪自今，兹事况其最。","勿笑修福人，修福良足贵。"]},{"t":"示诸子","f":"五言古诗","c":["我头久已白，我齿久已坠。","我耳近复聋，我目近复瞆。","我腹不耐餐，况复寒伤肺。","馀生过十年，安得长汝俟。","今日复来日，今岁复来岁。","少壮亦已亡，老病谁复在。","好日信无多，良遇安能再。","古圣喻为山，进止存一篑。","勿以将成堕，勿以初心委。","勿以愚自甘，勿以智自废。","人世何足云，死生事乃大。","若不早自决，后来谁汝代。","我生亦平平，我死汝必悔。","汝命金石坚，汝缘胡可恃。","努力复努力，勿更须臾待。","阖眼即他生，他生未必会。"]},{"t":"令言龙翠二子礼辞有感","f":"五言古诗","c":["云生必在山，风吹云不住。","鸟栖必在林，枝摇鸟亦去。","人生云与鸟，安得长相聚。","汝去我尚留，我愧不如汝。","去留匪自繇，感此泪如注。"]},{"t":"寒梦","f":"五言律诗","c":["北风吹不歇，梦中道路寒。","故里逢父老，凛冽多惨颜。","五岭炎蒸地，腊月常衣单。","不信别来久，霜雪亦漫漫。"]},{"t":"偶成二首 其一","f":"五言古诗","c":["乌啼不为人，声声催速老。","雪飞不为人，点点伤怀抱。","总予自心伤，遇物无一好。"]},{"t":"偶成二首 其二","f":"五言古诗","c":["有山岂无石，人自厌嵯峨。","有水能不流，人自厌风波。","所见亦由人，山水本无他。"]},{"t":"木公以闵茶寄山中感赋","f":"五言古诗","c":["真味在淡薄，高韵足幽情。","一啜洗心胃，再啜澄神明。","持瓯倚乔松，忽然生远情。","江南素士宅，一别十三龄。","胡为此山中，对雪漫孤评。","殊品需妙制，以姓为其名。"]},{"t":"山行","f":"五言古诗","c":["山行无远近，信步入幽杳。","老熊拘枯枝，向人立且跳。","因思人世间，此物应不少。"]},{"t":"山中","f":"五言律诗","c":["山中积阴雾，人物逊浑蒙。","日光渐赫然，豁见天地通。","丘陵突兀出，了别杉与松。","因思太古民，胡能久混同。"]},{"t":"野叟","f":"五言古诗","c":["野叟从何来，被褐持短筇。","入门但索饭，竟坐无礼容。","见予手执管，敢问是何虫。","三王与五帝，全不著其胸。","一字未曾识，安知拙与工。","予因悔读书，山居亦匆匆。"]},{"t":"偶述","f":"五言古诗","c":["人世难区区，圣谟安可恃。","收拾万古心，深入尘坌里。","戏谑岂予善，宛转亦非意。","和光豺虎间，缄泪盈腹笥。","屈舒无一可，呼吸逼神忌。","所以恣馀习，狂吟不能已。"]},{"t":"客至","f":"五言古诗","c":["裘轻马复肥，白日自光显。","儿童口啧啧，道傍谁不羡。","岂意到山来，山老如未见。","不是轻富贵，从未厌贫贱。","始悟人汝骄，多因汝眼浅。"]},{"t":"借书四首 其一","f":"五言律诗","c":["云雾难遮眼，言借古人书。","信手展残帙，心颜忽已愉。","人各适其适，积习宁顿除。","平生无所争，所争蠹之馀。"]},{"t":"借书四首 其二","f":"五言古诗","c":["上下几千载，治乱非一途。","或时草木欣，日月光庭除。","或时鬼神哭，阴雾惨不舒。","古笑我亦笑，古吁我亦吁。","哀乐岂有常，掩卷乃寂如。","始知得与失，古今只须臾。","我心本洞然，天地还清虚。"]},{"t":"借书四首 其三","f":"五言古诗","c":["今者古之影，古者今之模。","今人即古人，何必高黄虞。","手招诸圣哲，罗列坐俨如。","片语苟有会，恍惚动眉须。","苦昔抱心死，积久不得舒。","乃知冥漠际，欣然一觌余。"]},{"t":"借书四首 其四","f":"五言古诗","c":["世人爱读书，将以荣其躯。","山人爱读书，亦以乐其躯。","倦卧置枕边，行止常与俱。","人言何苦尔，我亦笑其愚。","不愿天中天，胡为效世儒。"]},{"t":"答戴公","f":"五言古诗","c":["魔佛界非二，罪福性原空。","章江与辽海，色味等皆同。","麋鹿亦可游，何必尽王公。","冰雪亦可餐，胡为羡马湩。","昔日庞居士，家财沉水中。","岂无男与女，相与乐融融。","但悟无生话，浮云任西东。"]},{"t":"过北里读徂东集","f":"七言古诗","c":["余家五岭本炎方，孤身远窜三韩地。","四月五月不知春，六月坚冰结河底。","今年天气稍冲和，秋尽雪飞到山寺。","出门仰天天欲沉，只杖栖栖过北里。","北里先生拥毳吟，诗成煮雪讶予至。","未曾展读泪先倾，拭泪同歌悲风起。","医巫闾高碧嵯峨，千叠万叠岚光积。","大壑一声白昼昏，黑云崩腾吼苍兕。","须臾云净松杉青，野泉泠泠石磊磊。","东海洋洋大国风，茫然万顷中无砥。","海气怒叱蜃气枯，狂涛倒飞星月沸。","三坌流驶鸭江平，寒鹰不鸣蛟龙寐。","有时亟欲掷头颅，蠹鱼悔食神仙字。","有时稼穑自谋生，三尺穹庐团妇子。","有时噀酒骂虚空，雷霆迅走黎丘惴。","有时谈笑和且平，欢狎牛蛇群白豕。","倏喜倏怒岂有常，欲杀欲活亦非意。","有时夜半步空阶，一叩青冥尺有咫。","沉魄千年呼尽来，死者可生生者死。","旧帝宵啼五国荒，闺媛暮哭长城址。","华表山前鹤唳孤，青冢犹闻月下欷。","琵琶凄切胡笳悲，未免有情谁遣此。","不知是血复是魂，化作吴刀切心髓。","心髓如铁刀如冰，片片飞入阴山里。","阴山惨惨泉冥冥，神农虞夏今已矣。","因思太古音尚希，噩噩浑浑难可冀。","尼山栖栖自卫归，苦乐忧伤各有旨。","约略删馀三百篇，发愤曾闻司马氏。","何人继者屈子骚，汨罗万古流瀰瀰。","可怜秦火恨不灰，汉室苏卿唐子美。","苏卿啮雪声韵凄，子美三迁足诗史。","五代波颓宋代儒，眉山山下出苏轼。","苏轼流离儋惠间，珠崖鹤岭供指使。","更有文山第一人，浩浩乾坤留正气。","从此荒芜将百秋，国初高杨追正始。","天下承平四海清，人人含宫家嚼徵。","琳琅金玉庙堂音，王李登坛执牛耳。","文长巨斧劈华山，中郎拍板逢场戏。","景陵一出洗烦浇，顿令搦管趋平易。","风雅茫茫失所宗，不得不推北地李。","李公豪雄步少陵，匪特形似亦神似。","先生才凌北地高，先生遇非少陵比。","阿弟捐躯阿兄流，西山之歌续二士。","不数秦关二百强，不羡蜀江千丈绮。","从来厄极文乃工，所以论文先论世。","丰干饶舌罪如山，滔滔谁易今皆是。","三百年来事莫知，天教斯道存东鄙。","不然今古亦荒凉，大雪纷纷吾与尔。"]},{"t":"大雨","f":"七言古诗","c":["去年秋潦淼茫茫，鱼鳖沙虫登我床。","瑶宫巨室皆漂没，何况流民茆札房。","死者横流生者泣，千口仅留不得食。","努力高山挖草根，至今面带黄泥色。","眼看麦短黍差长，虽未入口心有望。","上帝岂忧沟壑剩，其雨其雨乃复狂。","翻盘沉灶不肯止，庭户无光天重翳。","谁能拔剑斩顽云，捧出日轮头上置。","流民流民奈若何，生世坎壈何其多。","兵革遗馀乡国绝，又见辽海鼓风波。","老僧德薄命更鄙，偃卧若遭毒龙戏。","夜半滚滚浮枕头，不知是泪还是雨。"]},{"t":"辛卯寓普济作八歌 其一","f":"楚辞体","c":["罪夫罪夫胡不死，百千捶楚馀头趾。","乡国遥遥一万里，中有蔓棘及弧矢。","骨肉丧尽不得归，远碛苍茫大风起。","大风起兮沙闭天，谁非人子兮心惄然。","安得手扶白日兮，上照四塞之荒烟，下照万丈之黄泉。"]},{"t":"辛卯寓普济作八歌 其二","f":"楚辞体","c":["乌藤矫矫长七尺，当时与尔初相得。","瞿昙倒退愁弥勒，共誇有眼明如日。","今来绝域支冰雪，狮子昼眠狐跳立。","藤兮藤兮讵终穷，恐随风雨兮化作龙，何日将予兮直上千峰与万峰。"]},{"t":"辛卯寓普济作八歌 其三","f":"楚辞体","c":["有姊有姊夫早撇，手持木槵剪玄发。","诸妹零星俱夭折，最小尚馀安得活。","忆我出门姊幽咽，忽闻姊死心割裂。","吁嗟人生聚散兮若飞蓬，东西虽隔兮望故丛，只今长别兮无时逢。"]},{"t":"辛卯寓普济作八歌 其四","f":"楚辞体","c":["有弟有弟字耳叔，少年多病耽幽谷。","孝廉船覆青衫泥，三人惟尔守孤独。","黄沙杳杳望兄回，日暮走向荒城哭。","哭声到天兮天不闻，摧胸肝兮难久全，休望收吾骨兮葬江边。"]},{"t":"辛卯寓普济作八歌 其五","f":"楚辞体","c":["父母生儿不得守山丘，死者已矣生者流。","松楸日冷风飕飕，石人空立麋鹿游。","昔烦朝使丰碑留，煌煌天语题上头。","今日正清明，谁人更浇一杯水。","团圞荒草多新鬼，安得鹤归华表兮，尽洒千年之血泪。"]},{"t":"辛卯寓普济作八歌 其六","f":"楚辞体","c":["罗浮之山多蒿莱，山上还留说法台。","锦绣凋残玉女哀，村底无人空落梅。","铁桥流水尚潆回，白云一出不复来。","忆昔荷锄辟荒草，只今空向巫闾老。","何时再上罗浮道，辛苦前朝老衲衣。","十年与尔不相离，骨残心碎无完肌，至今襟袖血迹遗。","谁云新者可代故，何忍抛撇冬夏披。","衲兮衲兮汝勿悲，虽然破烂胜牙绯，生御风沙死裹尸。","我歌我歌歌将歇，揽衣忽起增哽咽。","我忧不独在乡国，我罪当诛复何说。","笔尖有鬼石流血，天地无情难永诀。","呜呼木佛木佛能不哀，狞飙苦雨四面来。","狞飙苦雨四面来，土床一尺魂徘徊。"]},{"t":"送鹿","f":"古风","c":["尔宜隐山谷，胡为露厥角。","昔共云中仙，今同笼中鹤。","送尔迢递入长安，尽道长安可行乐。","高车美食即陷阱，讵料尊荣遭割剥。","小鹿无知大鹿忧，悔曾饱啖新民粟。","新民忍饥送尔行，天道往复亦何速。","忽忆钟山陵寝边，祖宗德泽三百年。","歘忽运衰骨肉尽，何况远塞寄荒烟。"]},{"t":"老人行","f":"楚辞体","c":["噫吁戏危哉，老人是百千万劫之馀灰。","问其生时朝代不敢说，但云少壮尚无为。","眼看富贵贫贱流，三番两番肉作堆。","儿孙丧尽亲戚死，剩此零星乾枯骸。","纷纷眇者扶跛者，跛者扶眇者，面凹骨削背复鲐。","离城十里，五日乃至，登阶一尺如天台。","敢希鸠杖与麋粥，但愿脱籍归蒿莱。","堂上赫怒声如雷，叩头出血谁汝哀。","昔日汉家天子威，海宇父老子弟还相聚。","酒酣歌罢帝亲语，丰沛世世无所与。","老人兮老人，尔既赤手今且回。","生守官园喂官马，死作泥土填官街。"]},{"t":"哀王孙","f":"七言古诗","c":["哀草无根疾风吹，王孙不归辱涂泥。","头白老妻无完衣，鸳鸯到死犹双飞。","自言有子长须髭，垂暮泣血生别离。","今我若此子乌知，骨肉冻折命如丝。","左手执瓢右枯枝，此即二人送老儿。"]},{"t":"大僧行","f":"七言古诗","c":["大僧结束何新鲜，锦裁窄袖黑貂缘。","出门三礼释尊前，翻身上马挥金鞭。","玉作刀头绒作鞯，疾如飞鸟轻如烟。","自言五上长安道，目视汉官如虱蚤。","归来依旧守空门，独立皂边添马草。"]},{"t":"偪仄行","f":"古风","c":["偪仄复偪仄，大地不容膝。","乌飞翼折高踰尺，冈上梧桐化作棘，薜荔昼呼何时息。"]},{"t":"赠戴三","f":"古风","c":["孝子大痴人，不随白马随黄尘。","白马有时死，黄尘无日清。","夜寒看鹿栅，朝出采鬼薪。","不识大风与大雪，朝朝暮暮海之滨。","胸怀裂尽面颜笑，但愿爷娘温且饱。"]},{"t":"送梨","f":"古风","c":["不重紫花能消热，不羡张公大谷希。","只爱关东土上长，汁酸肉涩墨作皮。","王公一张口，走杀百群黎。","满筐二百或三百，昼夜担向玉京驰。","天下何处无冻梨，王公何不一念之。"]},{"t":"癸巳冬四日诸公同集普济话别","f":"七言古诗","c":["去年十月辽阳道，芒鞋蘸雪踏枯草。","今年十月将出门，北风吹发冻逾早。","萧条古庙城南隅，钟鼓不鸣鸟惊噪。","何人连袂叩荒扃，各山诗篇斗天巧。","吏部文章足起衰，祁连千仞欣独造。","毛锥如铁面如冰，时复掀髯发长啸。","学士前身金粟是，相逢弹指雾烟扫。","兴来墨汁自淋漓，明月一倾大栲栳。","豫章宿将旧登坛，万金散尽呼苍昊。","唾壶崩碎声载涂，三郎瘦削偏静好。","布衲抛残不耐寒，枯桐一拨凤凰叫。","庐江高士雪满胸，六朝荡涤存真藻。","梦里花深听鹧鸪，冰池独宿鸳鸯老。","浙东公子神复清，屣露双跟顶破帽。","写就黄庭不换鹅，向影閒吟孤自悼。","更有青门种瓜人，五色不生形半槁。","主人为我张素筵，氍毹重叠烧龙脑。","又汲参泉煮木鸡，粤橙漳橘恣一饱。","众音喧豗坐莫伦，虽无旨酒情潦倒。","请翻二十一青编，如斯良会古来少。","冷山寥落逻娑单，夜郎儋耳徒辽邈。","妙喜衡阳电白洪，安得诗人共围绕。","杯冷歌残声黯悽，明看孤杖淩霜晓。","亦知此别春必来，寂寂三冬守空窖。"]},{"t":"寒夜作","f":"七言律诗","c":["日光堕地风烈烈，满眼黄沙吹作雪。","三更雪尽寒更切，泥床如水衾如铁。","骨战唇摇肤寸裂，魂魄茫茫收不得。","谁能直劈天门开，放出月光一点来。"]},{"t":"雪中歌","f":"古风","c":["天倾地沸云嘈嘈，林木摧压风怒号。","雪势欲竞浮图高，恍如钱塘八月潮。","又如百群仙鹤剪羽毛，伫立骨战身飘飖。","竟欲乘之上游遨，足跨银海步玉霄，玉蟾真人手亲招。","直向梅花村底去，千树纷纷落如雨。"]},{"t":"海岸送人歌","f":"楚辞体","c":["水荡荡兮归路长，圣人出兮波不扬。","我送子兮蛟龙肠，安得从子归兮天苍苍。"]},{"t":"朱姑歌","f":"楚辞体","c":["玉叶凋兮芳草枯，恨从君兮君又徂。","君已徂兮妾生胡为乎，噫，妾今日死胡为乎。"]},{"t":"桥上石","f":"古风","c":["桥上石，半是前人坟上碑。","细想当年立碑日，儿孙罗列盛威仪。","重重种树重重护，岂料垫人脚下泥。","车轮直辗题名处，牛蹄马足纷交驰。","传语后来人，刻浅莫刻深。","刻浅模糊刻深在，长感千年行路心。"]},{"t":"筑坟歌","f":"古风","c":["去年西家筑坟好，今年东家筑坟早。","东家筑坟贴纸钱，已见西家犁作田。","田中又见生青草，几处种松能得老。","前人白骨化为尘，重取和泥埋后人。","后人得埋且莫哀，君不见狐狸窟穴沙坡台。"]},{"t":"雪花歌","f":"古风","c":["天上纷纷雪，山中树树花。","尽道梅花胜似雪，我见雪花胜梅花。","梅花开必著梅树，雪花下来随所寓。","不择高低长短枝，有风即去无风住。","纵使风吹树尽空，在地还与在树同。","本来清白谁能污，一任飘飘无定踪。","梅花虽好能几日，开落荣枯情不一。","君不见罗浮山下梅花村，师雄卧处生荆棘。"]},{"t":"花月歌","f":"古风","c":["月出爱良夜，花开聚名园。","几见花开定无雨，几见月出定无云。","便使无云无雨花月天，谁能长艳复长圆。","世间好景实无多，醉月迷花奈尔何。"]},{"t":"山雪歌","f":"古风","c":["山巍巍，雪霏霏。","日夕随风栖涧石，夜寒和月照岩扉。","山杳杳，雪皎皎。","雪在山头雪更高，山头有雪山逾老。","老僧爱雪兼爱山，岁岁山中自掩关。","每到冬来必见雪，每到见雪必开颜。","我心与雪何相似，长欲空山抱雪死。","纵令骨化定为冰，直至魂销应作水。","我常对雪寂无声，雪来见我如有情。","昔日袁安今日子，相看相伴两忘形。","从来不愿销金帐，羔羊美酒斟还唱。","人间行乐只片时，曲残酒醒身凋丧。","亦不愿高楼玉笛吹，梅花落处使人悲。","此中何限江南客，对此安能不泪垂。","但愿深山荒寺里，尽日无人吾与尔。","只恐春来尔不禁，寂寂相思从此始。","是时天地苦冥冥，山僧作歌山雪听。"]},{"t":"初发","f":"五言律诗","c":["马上催行急，欢生复自嗟。","身轻曾似叶，泪落正如麻。","计日边城近，伤心故国赊。","幸馀穿布衲，犹可耐风沙。"]},{"t":"至永平","f":"五言律诗","c":["去国刚三日，明朝欲到关。","故人从此尽，秃鬓自今斑。","马恨如风疾，心拚似石顽。","低头思二士，一望首阳山。"]},{"t":"宿山海关","f":"五言律诗","c":["重关犹未度，破衲早生寒。","大海依然险，危峦空自攒。","乡书万里绝，鼓角五更酸。","敢望能生入，回头仔细看。"]},{"t":"初入慈恩寺","f":"五言律诗","c":["幸无牛马后，仍许见浮屠。","礼佛欢如旧，逢僧笑尽呼。","膏粱恣啖嚼，土榻任跏趺。","半晌低头想，依然得故吾。"]},{"t":"思千山","f":"五言律诗","c":["咫尺白云隔，千山未许游。","前王曾驻跸，幽客几埋头。","洞壑愁中见，烟岚梦里收。","可怜溪上水，万古自空流。"]},{"t":"生日四首 其一","f":"五言律诗","c":["忆当论死际，又过两年期。","白日存吾分，寒风任尔吹。","到边仍说法，有客尚投诗。","且自欢兹会，明冬不可知。"]},{"t":"生日四首 其二","f":"五言律诗","c":["未了黄沙债，偿他止一身。","便从今日死，已是旧朝人。","乞食真惭粟，看书若有神。","无端思故事，数点泪沾巾。"]},{"t":"生日四首 其三","f":"五言律诗","c":["四十未为老，颠危自古稀。","虚生成底事，到死不知非。","弟妹徒相忆，家乡那得归。","从来无片纸，辜负雁南飞。"]},{"t":"生日四首 其四","f":"五言律诗","c":["百岁已将半，为僧十二年。","残躯委冰雪，双眼借人天。","只有心方寸，还馀诗几篇。","时时吾笑我，不改旧时颠。"]},{"t":"赠大通师","f":"五言律诗","c":["北宗夙所仰，开藏见高名。","道德传东海，袈裟搭上京。","开堂龙象踏，卓锡鬼神惊。","多少南来衲，皇途渐荡平。"]},{"t":"秋望","f":"五言律诗","c":["长平无好景，秋至益萧森。","不到边关外，焉知天地心。","风吹连野阔，日落满城阴。","骨肉消俱尽，空馀一念深。"]},{"t":"偶成","f":"五言律诗","c":["禅诵何曾习，幽幽我自亲。","过云如近性，古木愿为邻。","午睡无多事，平生只一真。","客来添礼数，知是世间人。"]},{"t":"晚兴","f":"五言律诗","c":["死去亦閒事，奈兹朝暮寒。","菊残秋色苦，僧老梵声乾。","遇物皆心碎，无天好眼看。","不如长闭户，趺坐夜漫漫。"]},{"t":"思友","f":"五言律诗","c":["知己良非易，何时不可亲。","况当流离际，举目两三人。","杯水必同聚，空谈亦有神。","毋论朝及夕，相与烂天真。"]},{"t":"送雁","f":"五言律诗","c":["举目漫相送，遥空影渐微。","自从来北塞，几度见南飞。","一路新霜下，三山古木稀。","明年望春信，行矣莫迟归。"]},{"t":"送燕","f":"五言律诗","c":["空梁如逆旅，欲别故飞低。","天下皆秋气，何方更好栖。","风流思旧梦，月冷度前溪。","尔念余心在，凄凉见落泥。"]},{"t":"重阳前三日","f":"五言律诗","c":["不能待九日，力尽为登台。","故国知难望，乡心终未灰。","孤烟生绝漠，返景照荒莱。","策杖且还卧，黄花何处开。"]},{"t":"怀友沧师","f":"五言律诗","c":["托迹长干里，能无车马喧。","世人来问法，远戍独怀恩。","定有花侵案，应知月到门。","菊英已堪把，日夕对谁飧。"]},{"t":"偶感","f":"五言律诗","c":["迁客易为感，况兼秋有声。","天风吹木叶，一夜满边城。","是处皆肠断，无时免泪零。","不知何事切，未必尽乡情。"]},{"t":"夜雨","f":"五言律诗","c":["是夜闻秋雨，萧萧更不禁。","崎岖万里梦，缭绕十年心。","处世明知幻，衔恩奈独深。","何曾待摇落，悽怆到于今。"]},{"t":"雨中看菊","f":"五言律诗","c":["风雨暗边关，何人泪勿潸。","我心与秋菊，相向不成颜。","倒卧从泥污，飘摇倚石顽。","眼看佳节近，犹自忆龙山。"]},{"t":"雨中怀诸子","f":"五言律诗","c":["咫尺阻言笑，其如风雨何。","展书当事业，壮志此消磨。","竟日掩门户，千年一咏歌。","寂寥频得句，相见较谁多。"]},{"t":"怀千山诸子","f":"五言律诗","c":["野衲还山去，深居第几重。","遥知岩石侧，犹有汉唐松。","施食下林雀，安禅护洞龙。","寄言诸老宿，春晓待飞筇。"]},{"t":"传子拓新斋","f":"五言律诗","c":["把茆亦已足，拓地更精神。","静坐饱秋色，开书见古人。","童乌时问难，慧远复来频。","何必桃花水，萧然即避秦。"]},{"t":"游谭家庵","f":"五言律诗","c":["诸山时闭阁，当午不闻钟。","此地足云水，往来多远踪。","酌泉有妙理，隐几即孤峰。","缭绕香生雾，应藏听法龙。"]},{"t":"送人","f":"五言律诗","c":["去去莫回头，苍茫塞上秋。","死生从此异，人马尽成愁。","不敢高声别，唯应暗泪流。","他方倘相忆，但索鬼门幽。"]},{"t":"小河","f":"五言律诗","c":["寂寂小河水，波平意自闲。","更无舟楫苦，独有雪冰艰。","众汲何曾损，直行绝往还。","静思源出处，应在万重山。"]},{"t":"送客","f":"五言律诗","c":["单身从此去，乡路尚悠悠。","两点丈夫泪，一天孤鹜秋。","幸无为客死，未了此生愁。","回望迁流处，沙平黑雾稠。"]},{"t":"晚步","f":"五言律诗","c":["钟声随我去，隐隐度前湾。","遥望深松暮，应多野鹤还。","客心在秋水，微月出空山。","任意缓归步，柴门不用关。"]},{"t":"暮归","f":"五言律诗","c":["只向城西去，非关夙有期。","闻歌知我至，抛卷候门时。","终日惟相对，竟归亦不辞。","老僧出户望，偏怪步何迟。"]},{"t":"寻诗","f":"五言律诗","c":["只在秋山里，遍搜黄叶堆。","忽然被我得，却似古人裁。","野月索将去，寒风吹复来。","还家囊已满，生死兴悠哉。"]},{"t":"接薪夷书","f":"五言律诗","c":["忆君良独苦，书到益伤神。","众命终难活，一心不负人。","何天堪问话，无地可容身。","却望边关外，偏多夙所亲。"]},{"t":"对雪","f":"五言律诗","c":["九月尚春衣，高林望已稀。","朔风从地起，大雪近僧飞。","鱼懒寒谁击，麈閒静不挥。","无人相问讯，只合掩荆扉。"]},{"t":"八日雪中怀北里","f":"五言律诗","c":["尔时应独坐，把笔自题诗。","以此为良计，终年足疗饥。","寒新生远思，雪净望幽姿。","明晓来相问，携将菊一枝。"]},{"t":"怀苏筑","f":"五言律诗","c":["煮泉方自酌，怀尔得诗题。","料是开窗看，无人雪一溪。","句从寒处索，物向悟边齐。","但望空林霁，知余来踏泥。"]},{"t":"怀我存","f":"五言律诗","c":["昨夜风吹雪，谁边落更多。","最怜愁与老，安得笑还歌。","范叔寒如此，陶公兴若何。","明朝采残菊，著屐定相过。"]},{"t":"九日偕诸子过北里","f":"五言律诗","c":["扶伴过城北，霜飞逐面来。","为寻扬子宅，不上单于台。","水泛东篱菊，心存故国莱。","从兹寒日甚，那得客颜开。"]},{"t":"冒雪过苏筑","f":"五言律诗","c":["所思何必远，挟卷过西邻。","相见亦无为，自然不厌频。","犬迎遥识面，雪下尽随身。","此日倍萧飒，烧泉意甚真。"]},{"t":"雪中","f":"五言律诗","c":["道心宿何处，风雪裹残僧。","觅我了无有，因人实不能。","磬敲零败叶，佛坐老孤灯。","欲问平生事，颓垣挂古藤。"]},{"t":"喜哥","f":"五言律诗","c":["流离方五岁，隆准异时儿。","所幸生年晚，全无旧国思。","泥深失龙性，霜冷落琼枝。","最是伤心处，逢人自笑嬉。"]},{"t":"得千山诸老信","f":"五言律诗","c":["千山人有信，望我到山中。","昨日满山雪，山风吹又空。","松枝当户入，石径与天通。","何得穿双屐，寻幽处处穷。"]},{"t":"答千山诸老","f":"五言律诗","c":["我本山中客，山翁不用招。","为怜地主意，遂使白云遥。","花雨迟飘落，松风暂寂寥。","石床馀半席，只待雪初消。"]},{"t":"梦游千山","f":"五言律诗","c":["夜半分明到，千山万木中。","霜花亲骨肉，雀语动虚空。","所见无今日，相论尽古风。","可怜非久住，床下叫寒虫。"]},{"t":"招山中诸老","f":"五言律诗","c":["传言入云去，劝汝下云间。","且看主人意，暂抛水石间。","此心无近世，随地足深山。","莫学高峰老，频年坐死关。"]},{"t":"夜雪","f":"五言律诗","c":["一榻浑如水，雪天未肯明。","怜吾愁不寐，到户寂无声。","白满思山谷，寒多念友生。","正当孤绝际，忽听晓钟鸣。"]},{"t":"听北里弹琴","f":"五言律诗","c":["招我入太古，孤琴此际闻。","林塘皆默默，水月共云云。","指外通心事，弦中绝世氛。","民生愠未解，何处觅南薰。"]},{"t":"北里新书屋二首 其一","f":"五言律诗","c":["古圣亦局促，图书雨雪侵。","凭添数尺地，不作百年心。","杏树篱穿老，柴门昼掩深。","歌吟听又满，馀响出寒林。"]},{"t":"北里新书屋二首 其二","f":"五言律诗","c":["卜居宁有意，聊以禦寒冬。","残瓦沿冈拾，低垣带雪舂。","但将书与共，所贵月能容。","从此门前路，时添云水踪。"]},{"t":"秋尽","f":"五言律诗","c":["秋光辞我去，还似惜春心。","野雀翔空响，寒云到地阴。","不能抒远梦，竟欲罢孤吟。","自此山门掩，屐声无近林。"]},{"t":"赠无瑕师","f":"五言律诗","c":["非关学辟谷，少小便忘饥。","终日半瓢水，长年一衲衣。","看人只自老，种树已成围。","来往边城里，常愁白昼飞。"]},{"t":"寄姚氏昆仲","f":"五言律诗","c":["兄弟幽栖处，开门水一方。","寻诗撑野艇，论易集空堂。","白昼听蛙吹，青天数雁行。","岭头三百树，好写寄穷荒。"]},{"t":"寄龚韩二子","f":"五言律诗","c":["平生无半面，祸患每过寻。","乱肆两枯骨，枯桐一片心。","道同顽处合，诗向酒中深。","后夜相思处，开门月满林。"]},{"t":"寿寒还","f":"五言律诗","c":["何物堪延岁，携将数卷书。","到门惟有雪，浮海已无桴。","饥渴三仙字，乾坤一老儒。","蓬莱如可至，或许曳长裾。"]},{"t":"左公往堡中有怀","f":"五言律诗","c":["未必长相见，初离叹索居。","遥知兄及弟，只有泪如珠。","踏雪寻诗句，循田得潦馀。","归时属二子，亟为报僧庐。"]},{"t":"和戴子堡中八咏 其一 北山","f":"五言律诗","c":["未到山中去，山中一片云。","无心偏出岫，何事屡移文。","白鹤犹闻怨，驯麋可与群。","嵯峨千丈壁，不必勒前勋。"]},{"t":"和戴子堡中八咏 其二 夹河","f":"五言律诗","c":["苦雨添新涨，怀人在水央。","双浮天日月，一濯我肝肠。","泡影流将去，閒愁荡更长。","卜居应不远，谁与咏沧浪。"]},{"t":"和戴子堡中八咏 其三 石人","f":"五言律诗","c":["见说衣冠古，投诗寄问频。","我心曾匪石，尔貌可为人。","萝月长相忆，山云乍许亲。","最怜同伴者，一半是顽民。"]},{"t":"和戴子堡中八咏 其四 永兴寺","f":"五言律诗","c":["岂料穷边处，还馀旧宝坊。","定多山下士，同礼法中王。","白豕惊清磬，寒猿到画廊。","他时携竹杖，应许借绳床。"]},{"t":"和戴子堡中八咏 其五 耕烟","f":"五言律诗","c":["啮雪固余分，犁云为汝怜。","何须至寒食，时恐断炊烟。","带雨将苗种，抛锄枕石眠。","只愁痴梦里，又到御炉边。"]},{"t":"和戴子堡中八咏 其六 采蕨","f":"五言律诗","c":["采采山中蕨，无为席上珍。","同甘辽海雪，难比故乡莼。","到壑犹闻禁，盈筐未是贫。","老僧知此味，好寄莫辞频。"]},{"t":"和戴子堡中八咏 其七 莲渚","f":"五言律诗","c":["污泥曾不染，隔浦递幽香。","何用沾新露，犹然怯晓霜。","愿生诸佛国，可集野人裳。","旧社荒芜甚，池塘梦正长。"]},{"t":"和戴子堡中八咏 其八 观鱼","f":"五言律诗","c":["子岂知鱼乐，过河泣欲枯。","未能忘浩荡，暂可免罾罛。","夜静芦花白，天寒野艇孤。","愿随风雨去，清梦到江湖。"]},{"t":"看薪夷病","f":"五言律诗","c":["看看垂死病，悽怆泪沾巾。","原罪吾居长，论贫尔作邻。","天全无可否，药尚有君臣。","莫畏泉台苦，冰河久已亲。"]},{"t":"喜薪夷病起","f":"五言律诗","c":["拚是沙埋骨，欣闻息已苏。","一毡吞未尽，双眼泪将枯。","又得吾良友，仍馀尔罪夫。","从今知死易，镇日好相呼。"]},{"t":"庭前孤雁四首 其一","f":"五言律诗","c":["缯缴满天地，空门亦有忧。","暂依庭草宿，敢望渚芦游。","梦想洲前侣，魂惊塞上秋。","预愁霜雪苦，不得到罗浮。"]},{"t":"庭前孤雁四首 其二","f":"五言律诗","c":["可是笼中物，高飞不自繇。","鼎烹何足恨，纲解转添愁。","独叫黄沙远，频行竹径幽。","主人情意重，岂为稻粱谋。"]},{"t":"庭前孤雁四首 其三","f":"五言律诗","c":["塞草青易白，堂阶日又曛。","自存湖海志，聊共鹜鹅群。","俯首随人语，凄声独我闻。","旧行不可问，肠断万重云。"]},{"t":"庭前孤雁四首 其四","f":"五言律诗","c":["仰天如欲诉，侧首听鸣砧。","影只月常照，力微风易侵。","祸深曾作字，愁绝少知音。","久矣云霄黯，何须寄上林。"]},{"t":"同陈子过新斋感赋","f":"五言律诗","c":["每过必终日，流离几弟兄。","土床横茗椀，笑语杂书声。","佛道尊衣马，天心宠甲兵。","此时况此地，犹见主人情。"]},{"t":"赠邻翁","f":"五言律诗","c":["乞食固予分，频过亦自憎。","如何君父子，偏欲饱孤僧。","饭粳铜匙滑，参泉碧盏澄。","只兹堪我老，况尔坐高朋。"]},{"t":"读顾与治书并见怀诗","f":"五言律诗","c":["一派江涛白，惊生塞上魂。","乍疑惊瘦影，再读见啼痕。","旧橐青衫尽，空庭老树存。","相思频得句，好寄莫辞烦。"]},{"t":"孟贞寄书不至","f":"五言律诗","c":["老友偏思尔，容枯骨岸然。","祇闻寄远字，不见到寒边。","稚子应看长，空囊谁为怜。","明春有归雁，莫惜写新篇。"]},{"t":"洁之有志入山索赠","f":"五言律诗","c":["已知寒塞苦，爱上别峰间。","挂钵青松古，安禅白石顽。","尘何关只杖，乱亦到深山。","未歇狂心在，溪流总不閒。"]},{"t":"立秋后一日孤雁忽飞去四首 其一","f":"五言律诗","c":["荒寺聊藏迹，定知非久留。","庶无鹰隼患，能免雪霜忧。","矫首辞孤衲，高飞觅旧俦。","江南兵未戢，珍重荻花洲。"]},{"t":"立秋后一日孤雁忽飞去四首 其二","f":"五言律诗","c":["秋至尔先觉，空天翅独横。","既同艰险过，亦有别离情。","度塞宜高举，惊人莫浪鸣。","罗浮如可到，愁绝是孤征。"]},{"t":"立秋后一日孤雁忽飞去四首 其三","f":"五言律诗","c":["本是伤弓羽，还愁罗网撄。","虽无好处去，犹自惜馀生。","梦警五更雨，身轻万里程。","似怜相聚久，连叫两三声。"]},{"t":"立秋后一日孤雁忽飞去四首 其四","f":"五言律诗","c":["上林非夙昔，繫帛亦徒劳。","尔去从飘泊，余心转郁陶。","空庭添寂寂，中泽总嗷嗷。","何日清江海，孤云许共翱。"]},{"t":"沈阳杂诗二十首 其一","f":"五言律诗","c":["草草四十载，乾坤一病身。","腊深颜益厚，祸酷意无瞋。","性命岂由我，饥寒常累人。","西邻有二老，谈笑见天真。"]},{"t":"沈阳杂诗二十首 其二","f":"五言律诗","c":["西风吹破寺，泥佛坐何年。","一雁起庭际，数声空唳天。","远书谁可寄，饱食我方眠。","禅律浑忘却，安能效磨砖。"]},{"t":"沈阳杂诗二十首 其三","f":"五言律诗","c":["世事看亦见，边城忽已秋。","尘沙必在面，虮虱又缘头。","欲笑从他笑，多愁总莫愁。","所知居不远，来往尽风流。"]},{"t":"沈阳杂诗二十首 其四","f":"五言律诗","c":["吁嗟复吁嗟，谁是无父母。","守栅供庖厨，入林禦豺虎。","得生亦暂时，尽死安足数。","新眼看旧人，自然成粪土。"]},{"t":"沈阳杂诗二十首 其五","f":"五言律诗","c":["盛衰自今昔，佛岂限中边。","竿木随身戏，针锥任众贤。","到山先数马，入室但分钱。","亦有二三子，休嗟吾道邅。"]},{"t":"沈阳杂诗二十首 其六","f":"五言律诗","c":["辛苦法王子，深慈将奈何。","肉残无足食，骨碎可重磨。","大网嫌鱼漏，高林畏鸟多。","不如魑与魅，犹自喜人过。"]},{"t":"沈阳杂诗二十首 其七","f":"五言律诗","c":["瘦日射枯杨，荒荒欲断肠。","老狐来瞰室，饿虎易过墙。","岂为高明误，空遭纸笔殃。","南中有义士，风雨每同床。"]},{"t":"沈阳杂诗二十首 其八","f":"五言律诗","c":["此地暑易尽，家家闻捣衣。","拽车水牯瘦，击鼓鬼娘肥。","风景连年是，人情半刻非。","老僧惟一钵，每日饱方归。"]},{"t":"沈阳杂诗二十首 其九","f":"五言律诗","c":["白日只斯须，频年乞海隅。","罪多识命贱，书到益身孤。","秉拂寻顽石，题诗答腐儒。","明知乡国没，仍梦到西湖。"]},{"t":"沈阳杂诗二十首 其十","f":"五言律诗","c":["北里有遗老，寻诗尚未还。","定知题落叶，随意到空山。","白昼全无韵，棋枰久已閒。","好携秋爽色，一洒户庭间。"]},{"t":"沈阳杂诗二十首 其十一","f":"五言律诗","c":["白鹤亦有泪，悲凉与世同。","要从今日事，稍见古人风。","笛里声初断，囊中药屡空。","只留天一线，呼吸可能通。"]},{"t":"沈阳杂诗二十首 其十二","f":"五言律诗","c":["侧立向空荒，风吹恨愈长。","文章宜溷厕，牛骥共禅房。","不识梅花白，惟誇麦子黄。","秋来瓜独好，小摘齿牙香。"]},{"t":"沈阳杂诗二十首 其十三","f":"五言律诗","c":["老翁时问讯，不死近何如。","梦里数竿竹，床头一卷书。","为人终直率，对客怪粗疏。","午后睡方足，行行过草庐。"]},{"t":"沈阳杂诗二十首 其十四","f":"五言律诗","c":["可惜团团月，还来绝塞明。","照人幽近死，到地自无声。","孤雁忽然过，远钟何处鸣。","岭南应更苦，夜夜落荒城。"]},{"t":"沈阳杂诗二十首 其十五","f":"五言律诗","c":["卫霍名何减，山头旧札营。","乍闻吹落叶，犹似走残兵。","原草缠幽恨，河流带哭声。","最愁秋雨后，燐火向人明。"]},{"t":"沈阳杂诗二十首 其十六","f":"五言律诗","c":["未到秋风起，先令破衲寒。","但拚身一掷，久与世无干。","日月看倏去，林泉到处残。","如何昨夜梦，颗颗荔枝丹。"]},{"t":"沈阳杂诗二十首 其十七","f":"五言律诗","c":["几载望乡信，音来却畏真。","举家数百口，一弟独为人。","地下反相聚，天涯孰与邻。","晚风连蟋蟀，木佛共含辛。"]},{"t":"沈阳杂诗二十首 其十八","f":"五言律诗","c":["佛命亦如线，西方有剩莲。","贝翻成大贾，笙吹比神仙。","弟子黄金贵，弓裘白日鲜。","雷同吾岂敢，只合抱沙眠。"]},{"t":"沈阳杂诗二十首 其十九","f":"五言律诗","c":["沙坡台下土，春老草难生。","行路践心髓，游魂怯旆旌。","乌贪天养子，狐拜月成精。","当日无贫富，锋刀不世情。"]},{"t":"沈阳杂诗二十首 其二十","f":"五言律诗","c":["天地不可必，春风或度关。","阴山一半揖，遗老共生还。","杖指乌衣巷，船归黄木湾。","亲朋未尽鬼，恸哭后开颜。"]},{"t":"梦安仲叔","f":"五言律诗","c":["昨夜分明见，长须叔不痴。","衣冠非此日，言笑尚前时。","纵死心方寸，平生酒一卮。","只愁关路黑，来往得无疲。"]},{"t":"苦蚊","f":"五言律诗","c":["白日难容汝，群飞欲蔽天。","愁人频得句，终夜不成眠。","饿极筋先露，刑馀血尚鲜。","关东风景异，只此似江边。"]},{"t":"游七岭寺","f":"五言律诗","c":["何必入山去，到来非世间。","巢松孤鹤冷，补衲几僧閒。","钟磬留清范，岚烟护旧关。","一溪冰渐解，流水已潺潺。"]},{"t":"留龙泉静室","f":"五言律诗","c":["入山如数日，又是一春残。","花信何曾到，松风依旧寒。","野禽时缱绻，孤月共盘桓。","始觉边关外，犹然天地宽。"]},{"t":"寄题易修静室","f":"五言律诗","c":["虽在名蓝内，孤栖别一枝。","身贫客自少，地僻病相宜。","定有云分榻，时烦月照眉。","我来应不拒，煮雪共疗饥。"]},{"t":"和李公冬日成茆屋四首用韵 其一","f":"五言律诗","c":["数椽聊自可，欹枕抱书眠。","窗阔堪延月，茆疏好见天。","残毡犹马革，点雪即花砖。","野老频来过，床头起暮烟。"]},{"t":"和李公冬日成茆屋四首用韵 其二","f":"五言律诗","c":["不识长安乐，何如东海隅。","夜寒闻鹤语，榻短学僧趺。","兴至诗涂壁，饥来雪满盂。","西邻迁客在，镇日待招呼。"]},{"t":"和李公冬日成茆屋四首用韵 其三","f":"五言律诗","c":["身閒居自僻，岂必在山阿。","寒灸青藜火，行吟哨遍歌。","诗能穷学士，酒亦病维摩。","向晚西风急，何人著屐过。"]},{"t":"和李公冬日成茆屋四首用韵 其四","f":"五言律诗","c":["举世皆兵革，安居自朔庭。","佛容参米汁，客与论棋经。","衾薄风侵骨，心空月在扃。","屡携孤杖去，带雪步荒坰。"]},{"t":"重和四首 其一","f":"五言律诗","c":["自是客来少，非关地独偏。","残棋抛屋角，饥犬卧炉边。","果赖邻儿送，诗凭野衲传。","情知无喜事，鹊噪矮檐前。"]},{"t":"重和四首 其二","f":"五言律诗","c":["何事长边外，偏多鲁国儒。","谈经偕野兽，卜筑近枯株。","窗破残诗补，肌羸薄酒扶。","不知寒夜梦，还上玉阶无。"]},{"t":"重和四首 其三","f":"五言律诗","c":["敝絮蒙头卧，霜风奈若何。","虚庭迎木客，汲井煮桑鹅。","适性此云足，容躯不在多。","小僮存道意，袖手听长歌。"]},{"t":"重和四首 其四","f":"五言律诗","c":["远碛留天地，无言雪一庭。","正襟坐古哲，开户看沧溟。","虎迹任来去，人情半醉醒。","老僧应不厌，多病怯疏棂。"]},{"t":"赠乐亭秀才","f":"五言律诗","c":["我苦不得去，君胡为独来。","无家投大漠，设帐傍荒台。","客意黄花后，书声白雪堆。","相逢三两语，涕泪点残灰。"]},{"t":"送苗鍊师入燕","f":"五言律诗","c":["白日君将去，黄垆我尚留。","莫言朋友义，能免众生忧。","残雪填沙碛，悲心满壑沟。","何时垂鹤翅，尽驾入云游。"]},{"t":"赠五千道者","f":"五言律诗","c":["只杖凄凄日，论乡独有君。","辞家一万里，学道五千文。","礼斗依丹阙，吹笙坐碧云。","不堪询故老，清泪亦纷纷。"]},{"t":"得耀寰札","f":"五言律诗","c":["相见亦常事，相离费苦思。","翻怜三岁过，未了一生疑。","函泪遥相寄，关心久已知。","长安春梦好，犹自绕冰池。"]},{"t":"同陈子久坐候大翁回","f":"五言律诗","c":["稚子欢留坐，主人出未归。","料应无别适，不过扣僧扉。","时卷携将去，塞炉且共围。","入门知有客，言笑尽馀晖。"]},{"t":"大雨喜育子远访","f":"五言律诗","c":["相逢疑隔世，一别五经年。","莫话乡关事，难禁风雨天。","寻尸来万里，问道入重泉。","拗折枯藤杖，沙寒且共眠。"]},{"t":"别诸公往辽阳","f":"五言律诗","c":["一秋良可过，镇日共盘桓。","谈寂霜犹堕，诗成月每残。","开怀偏有限，握别恨无端。","不出郑图外，关河各自寒。"]},{"t":"同大来吉津赴启如斋","f":"五言律诗","c":["出门何所往，定是野僧家。","踏破三门雪，惊残一树鸦。","登床无别礼，堆案尽天花。","得饱不辞去，边城日又斜。"]},{"t":"和丽大师送弼臣见讯韵","f":"五言律诗","c":["不作金门赋，胡为匹马行。","亲朋愁远道，生死见交情。","望处关云黑，卧来江月清。","早归余尚在，海角待升平。"]},{"t":"同陈公叙昔有感","f":"五言律诗","c":["不过廿年事，还如隔数生。","逢君寒碛话，动我渭阳情。","乡国馀残梦，乾坤未解酲。","独怜孤杖外，气骨自相撑。"]},{"t":"同木斋坐苏筑斋竟日","f":"五言律诗","c":["所谈亦何异，相共到黄昏。","閒或翻残帙，饥惟索瓦盘。","危微千古事，断续几人存。","此日真堪录，寻思无一言。"]},{"t":"读李氏遗书二首 其一","f":"五言律诗","c":["何期万死后，得见一生人。","久识灰销骨，欣看字有神。","每凭心口力，尽洗古今尘。","莫恨余生晚，当时无此亲。"]},{"t":"读李氏遗书二首 其二","f":"五言律诗","c":["举世令人闷，斯人以死争。","开眸沧海窄，点笔老天惊。","佛祖无酸气，英雄有至情。","遗书今尚在，再拜李先生。"]},{"t":"慰戴三病","f":"五言律诗","c":["三日不相见，惊闻伏枕忧。","尪羸力已竭，号泣意无尤。","未识趋庭乐，弥深陟屺愁。","春残风尚劲，珍重夜添裯。"]},{"t":"喜李鍊师禁足","f":"五言律诗","c":["人间亦何极，隐几即仙源。","尽扫青牛迹，深藏金马门。","閒应探药笈，静可叩天根。","咫尺三山近，行看一鹤鶱。"]},{"t":"重送大茎","f":"五言律诗","c":["艰辛吾与汝，耐尽几秋霜。","佛了无奇特，人难是久长。","云山欣有伴，风雨忆同床。","莫恋故乡好，相期塞菊黄。"]},{"t":"重送尸林","f":"五言律诗","c":["欲嘱浑无语，徒将泪几行。","乾坤双草履，来去一空囊。","故国何从觅，寒冰已共尝。","老人相见处，休话汝师狂。"]},{"t":"送义虫省亲","f":"五言律诗","c":["相见复何日，相期安可忘。","好携沙际雪，聊慰发如霜。","不孝原非佛，寻诗颇似狂。","濡毫题去袖，春雨正茫茫。"]},{"t":"寄心公二首 其一","f":"五言律诗","c":["念子何偏切，为人念独艰。","相期一种意，不在百年间。","古圣了无异，高名岂是閒。","遥知吟倦处，徙倚望他山。"]},{"t":"寄心公二首 其二","f":"五言律诗","c":["别来频雨雪，心绪近如何。","子道承欢隔，君恩出塞多。","高山方咫尺，白日已蹉跎。","自有无穷事，时将访薜萝。"]},{"t":"答客问","f":"五言律诗","c":["似此已踰分，平生我自知。","一从得罪后，总是感恩时。","有病还长啸，无家亦赋诗。","尚犹愁未足，旦晚欲何为。"]},{"t":"雪下有感","f":"五言律诗","c":["大雪真吾事，天心本至公。","翻书甘手冷，乞食望年丰。","旧岭花方发，平沙雁已空。","几多未归客，对此意何穷。"]},{"t":"入山寄友","f":"五言律诗","c":["到来方觉好，山亦厌名闻。","世事凭萝隔，幽情与佛分。","猿啼几树月，鹿过一溪云。","此处真惟我，相寻未许君。"]},{"t":"山中思友二首 其一","f":"五言律诗","c":["知己从来少，况当塞雪深。","每同开口笑，遂觉缓愁心。","长聚亦无事，初离便不禁。","如何此寒夜，独自卧孤岑。"]},{"t":"山中思友二首 其二","f":"五言律诗","c":["相见已恨晚，更添离别心。","几多乡国思，翻向友朋深。","山古云常寂，天寒日易沉。","独吟浑莫柰，钟磬自成音。"]},{"t":"同诸公夜集希焦二师室","f":"五言律诗","c":["弟兄能爱客，老衲每来寻。","况有同心侣，相偕彻夜吟。","异乡消积恨，明月助清音。","何必求仙去，花源此地深。"]},{"t":"又过希焦二师","f":"五言律诗","c":["好我真无为，感君此念深。","一从初识后，数载到于今。","狂极偏增重，离多奈独吟。","春风留洞口，扶病更来寻。"]},{"t":"题金塔寺二首 其一","f":"五言律诗","c":["人皆崇藻饰，此独尚清幽。","共佛三间屋，连云一个牛。","耕田供客食，开户任麋游。","最爱前溪水，横腰一带流。"]},{"t":"题金塔寺二首 其二","f":"五言律诗","c":["人贫方彻骨，塔尚以金名。","采蕨扶云出，寻诗蹋月行。","断碑看字影，驯虎听经声。","我到家常饭，因留太古情。"]},{"t":"赤公书来赋答二首 其一","f":"五言律诗","c":["书来惟说苦，问我苦如何。","得食粗蔬足，逢人好笑多。","拚他今便死，不尔且长歌。","只此朝还夕，残冬亦易过。"]},{"t":"赤公书来赋答二首 其二","f":"五言律诗","c":["我有消愁法，从来肯易传。","不归吾本尔，但饱即欣然。","拾得丝丝命，由他泯泯天。","为公通一线，同病故相怜。"]},{"t":"自寿","f":"五言律诗","c":["投荒三十八，又已八年过。","罪过随年长，閒情近日多。","怀人添雪梦，得句上山歌。","且自加飧好，愁颜意柰何。"]},{"t":"忆昔","f":"五言律诗","c":["忆昔君初至，难分喜与悲。","天边亲杖屦，雪底见须眉。","屡读三都赋，相为一字师。","自今酬唱隔，布袋有遗诗。"]},{"t":"儒释","f":"五言律诗","c":["儒释虽云异，天涯放逐同。","五车开道路，一棒击虚空。","梅州惭妙喜，蜀国失文翁。","敢谓天将丧，应知吾道穷。"]},{"t":"悼骡三首 其一","f":"五言律诗","c":["淡泊幸相守，残躯赖尔扶。","忽然辞我去，愈觉一僧孤。","牛骥嫌同皂，风沙怯远途。","自今能解脱，含泪奠生刍。"]},{"t":"悼骡三首 其二","f":"五言律诗","c":["一钵同行乞，三年不厌贫。","崎岖劳曲折，雨雪共酸辛。","何忍抛愁骨，翻如失故人。","言寻旧竹杖，彳亍更谁亲。"]},{"t":"悼骡三首 其三","f":"五言律诗","c":["所苦不能待，春深老渐长。","殊形宁受畜，驯性最难忘。","沟壑尔先俟，冰霜我独尝。","伤心惟闭户，咫尺即羊肠。"]},{"t":"布帷","f":"五言律诗","c":["世事凭兹隔，高眠梦亦空。","青编落枕上，白日在山中。","此外无宁处，何人可与同。","有时开放入，溪月并松风。"]},{"t":"哭李给谏","f":"五言律诗","c":["山中愁未了，走马哭孤臣。","白发随江水，青云逐塞尘。","史留忠愤疏，天丧老成人。","幸有绨袍在，年年渍泪新。"]},{"t":"和赤公寄韵","f":"五言律诗","c":["相见一平淡，相离偏忆君。","每当此月夜，遥望在城云。","大雪毋长视，狂歌恐或闻。","岁穷宜倍慎，三嘱泪殷勤。"]},{"t":"遥送我存还巢二首 其一","f":"五言律诗","c":["未得临岐别，何堪话别频。","同为黑水戍，况送白头人。","长路悲空橐，还家失老亲。","几多儿女泪，应为洗边尘。"]},{"t":"遥送我存还巢二首 其二","f":"五言律诗","c":["艰难知尔最，大患在吾身。","莫忆来时恨，偏添去路辛。","未堪逢至戚，犹恐讶诸邻。","巢父真无罪，牵牛饮颍滨。"]},{"t":"得我存长安寄来书用前韵","f":"五言律诗","c":["行后予方觉，书来泪又频。","到天还忆友，一路但依人。","并罪归何碍，携霜散所亲。","不须回白首，去住总皇仁。"]},{"t":"得石云居诗文","f":"五言律诗","c":["尚论贵只眼，平生于此深。","共传迁史笔，谁谅许衡心。","后死亦无恨，斯文未丧今。","遥怜孤子意，山水有知音。"]},{"t":"问雪公","f":"五言律诗","c":["山寒予可耐，衣薄尔何禁。","学道身方重，论文念独深。","长贫分鹤粒，多病到僧心。","珍重过残腊，春来共笑吟。"]},{"t":"闻天公病","f":"五言律诗","c":["下堂犹有虑，出塞念偏深。","不是子臣泪，全然父母心。","或者风方劲，安能别有侵。","加飧凭努力，春至候佳音。"]},{"t":"得木公手字","f":"五言律诗","c":["爱我知偏重，知予乃独深。","时时施药石，事事入肝心。","死骨必思肉，顽皮尚受针。","明知此不可，又作感恩吟。"]},{"t":"和栖贤山居韵 其一","f":"五言律诗","c":["山水无中外，飘云何必归。","最嫌沙上雁，一一向南飞。","罪大心方死，病多力渐微。","谁持匡岳泪，来洒破僧衣。"]},{"t":"和栖贤山居韵 其二","f":"五言律诗","c":["何妨卧出日，长欲语三更。","篱外无人到，窗前有虎行。","风微飘梵咒，云密透书声。","只此閒同过，毋令别感生。"]},{"t":"和栖贤山居韵 其三","f":"五言律诗","c":["无事不携筇，多因访远松。","独行深雪路，忽听隔溪钟。","得句鸣寒谷，持云赠别峰。","自来无定止，到处幸能容。"]},{"t":"和栖贤山居韵 其四","f":"五言律诗","c":["有言惟独语，更莫问青霄。","衣就田塍补，柴分品字烧。","止寻栖壑侣，不赴在城招。","峰顶香岩寺，钟声下半腰。"]},{"t":"和栖贤山居韵 其五","f":"五言律诗","c":["出郭无多路，心空觉地偏。","一从抱病后，不敢向人前。","鸲鹆留残石，素馨忆旧田。","止应吾与汝，朗咏了残年。"]},{"t":"和栖贤山居韵 其六","f":"五言律诗","c":["高谈山顶月，低揖世间人。","判就孤寒命，仍馀老病身。","我心不可转，佛道未容真。","何处玉渊水，惟应独问津。"]},{"t":"和栖贤山居韵 其七","f":"五言律诗","c":["閒知茅宇阔，静觉野云忙。","僻径人难觅，深山日自长。","鹿携麋入室，雪共雨登堂。","自起拨炉火，因烹芦菔尝。"]},{"t":"和栖贤山居韵 其八","f":"五言律诗","c":["大抵长边外，三冬半是阴。","风吹旧屋角，雪补破衣襟。","树压枝枝重，灯寒夜夜深。","梅前初梦醒，不柰此时心。"]},{"t":"和栖贤山居韵 其九","f":"五言律诗","c":["每日一餐足，无人白昼眠。","寒多宁有法，懒极不须禅。","时上岩头石，遥看林外田。","西南日尽处，一直上孤烟。"]},{"t":"和栖贤山居韵 其十","f":"五言律诗","c":["生来山野性，万死不离山。","随水偶然出，因风急复还。","吟多长倚树，客到未开关。","自笑顽成癖，人传老更顽。"]},{"t":"和栖贤山居韵 其十一","f":"五言律诗","c":["夜半一抬首，星光尽在山。","不能同雪化，只合揽云还。","猿至常无候，门开且莫关。","可怜犹有尔，识我是真顽。"]},{"t":"和栖贤山居韵 其十二","f":"五言律诗","c":["率尔行将去，倦来树底眠。","泉流时问话，鸟宿似安禅。","霜不凋金粟，海难变砚田。","每看敲石火，一点自生烟。"]},{"t":"和栖贤山居韵 其十三","f":"五言律诗","c":["如何有好日，不出又成阴。","一任霜催鬓，毋令泪渍襟。","林泉宁有异，天地此中深。","竟夕寒如水，空馀一寸心。"]},{"t":"和栖贤山居韵 其十四","f":"五言律诗","c":["不能效古昔，镇日为人忙。","树影当窗直，峰岚入梦长。","晓风轻布衲，暮雪静茆堂。","更想峡桥畔，平分一盌汤。"]},{"t":"和栖贤山居韵 其十五","f":"五言律诗","c":["展卷旧相识，全非此日人。","明明千古意，寂寂一孤身。","到死终无二，平生只是真。","最怜初睡熟，又度大榕津。"]},{"t":"和栖贤山居韵 其十六","f":"五言律诗","c":["本无才足恃，不是性多偏。","沙石甘居后，冰霜独在前。","难销檀越水，不种祖翁田。","所以一瓢外，风吹自岁年。"]},{"t":"和栖贤山居韵 其十七","f":"五言律诗","c":["五老何年见，人间隔九霄。","黄精金井洗，苍术玉门烧。","未遂玄沙志，翻将白纸招。","龙津终有合，携手步山腰。"]},{"t":"和栖贤山居韵 其十八","f":"五言律诗","c":["拗折此孤筇，随心步步松。","投林仍乞食，到午但闻钟。","十年持一钵，双眼寄千峰。","且莫临溪照，恐惊憔悴容。"]},{"t":"和栖贤山居韵 其十九","f":"五言律诗","c":["怀人几千里，每夜过三更。","拥毳时同坐，沿阶又独行。","不堪鸭绿色，常作虎溪声。","更有关心处，飞云枕上生。"]},{"t":"和栖贤山居韵 其二十","f":"五言律诗","c":["旧山毕竟好，垂老未言归。","遥想鹤峰上，终期华表飞。","歌残山月白，声咽夜钟微。","何日金轮顶，相将一振衣。"]},{"t":"张弥茂赠红褐禅衣","f":"五言律诗","c":["空囊不羞涩，犹自念僧寒。","顿使贫儿富，能令白骨丹。","雪埋深易见，血洒湿难乾。","且得残冬过，何如破衲安。"]},{"t":"岁暮同阿字得寒字四首 其一","f":"五言律诗","c":["经岁无人趣，惊看腊又残。","霜添窗纸厚，风使衲衣单。","彻骨寒无路，扪心泪有端。","一从汝到后，更益我辛酸。"]},{"t":"岁暮同阿字得寒字四首 其二","f":"五言律诗","c":["总是冰霜地，非关我独寒。","一身蹲雪底，双眼向云端。","索句从朝起，烧泉到夜阑。","此时兼此地，犹得共团圞。"]},{"t":"岁暮同阿字得寒字四首 其三","f":"五言律诗","c":["细看生何用，平生厌素餐。","泪将一岁尽，事向五更攒。","海静三山稳，云高五老寒。","情知强言笑，图使我心欢。"]},{"t":"岁暮同阿字得寒字四首 其四","f":"五言律诗","c":["抖搜十年恨，全倾大海宽。","看人忙不了，于我竟无干。","爆竹何曾响，蠹鱼依旧寒。","春风迟亦到，且莫发长叹。"]},{"t":"祀灶","f":"五言律诗","c":["灶无嫌我乞，我自厌残身。","十载犹存舌，一瓢长傍人。","空飧劳施主，勺水赖明神。","此夜无须嘱，深知愧是真。"]},{"t":"担水者","f":"五言律诗","c":["往来馀五里，风雪到更深。","欲趁蛟龙卧，宁愁魍魉侵。","丝丝尽彼力，滴滴感余心。","因忆旧山上，飞泉到釜鬵。"]},{"t":"天公以其尊人所书扇见赠","f":"五言律诗","c":["艰危珍匣笥，持赠慰荒榛。","乍展疑先晋，徐看识故人。","老来书自圣，别久意逾真。","前日传家信，犹然寄问频。"]},{"t":"天公赠棉衣留南塔先有此谢","f":"五言律诗","c":["念我寒如此，腊终犹解衣。","数年惟破衲，一半逐云飞。","但使存孤骨，毋令嚇翠微。","故人恋恋意，春气透柴扉。"]},{"t":"闻爆竹和阿字韵","f":"五言律诗","c":["衰残不可耐，强逐小儿情。","山泽了无气，虚空忽有声。","一连三夜梦，亲到五羊城。","听此翻添思，髫年正太平。"]},{"t":"和天然兄初住栖贤韵","f":"五言律诗","c":["鹿洞曾经过，难寻三峡桥。","老兄今又至，浩气可全消。","石立潭边静，泉飞谷口遥。","黄云难极目，夜夜梦魂摇。"]},{"t":"赠王大哥","f":"五言律诗","c":["不关裘马事，公子自翩翩。","戏彩春风里，寻僧野雪边。","论文怜远戍，饮酒泻飞泉。","伫看凌烟上，功名本少年。"]},{"t":"读梁未央赠陈全人诗有感用原韵","f":"五言律诗","c":["我昔见君日，知君慕远林。","方肩斯世重，不作世间心。","古佛机难扣，孝廉船已沉。","未曾沧海变，怀恨到于今。"]},{"t":"读梁未央赠霍阶生诗有感用原韵","f":"五言律诗","c":["太仆捐躯日，相随雁一行。","莲池心骨净，金匮姓名藏。","五岭明臣节，千秋重义方。","馀生愧我在，风雪思难忘。"]},{"t":"乌食菽为沙弥所缚余见而释之","f":"五言律诗","c":["口腹有深阱，颠危实可怜。","为贪半粒饱，遂惹百丝牵。","人世殊多患，空门亦自缠。","殷勤为解释，好去莫留连。"]},{"t":"金塔主人遣诸沙弥","f":"五言律诗","c":["长者亦多事，初惟树下居。","但留孤钵在，何必恋耕锄。","鸟散林偏静，云飘月有馀。","自今吾与子，茆屋本空虚。"]},{"t":"题一粟斋","f":"五言律诗","c":["一粟大如许，其中世界藏。","卧听宫漏水，行拂御炉香。","天近神仙赫，恩多日月长。","野人频到此，破衲亦辉光。"]},{"t":"岁暮有怀","f":"五言律诗","c":["亦是寻常过，忧来每觉频。","为当今岁暮，无复旧乡人。","烟火投山店，风霜冷水滨。","最怜江尽处，上下岭梅新。"]},{"t":"仲冬末忽大暖数日冰雪尽化","f":"五言律诗","c":["三冬刚踰半，春气变寒林。","但觉人禽悦，谁知天地心。","崖悬疑泻瀑，檐溜似长霖。","自入深山里，应沾帝泽深。"]},{"t":"题俗龛","f":"五言律诗","c":["亦自堆残卷，何曾一室空。","文殊或过问，弥勒也难同。","畏客长疑病，教儿未觉穷。","只愁深夜后，冻杀蠹书虫。"]},{"t":"天公新搆茆舍观音堂侧","f":"五言律诗","c":["草草数间屋，言依古佛居。","仅能遮雨雪，大半是图书。","梵唱连歌板，棋声杂粥鱼。","何须青琐闼，即此乐如如。"]},{"t":"戴三移居铁岭","f":"五言律诗","c":["既在大荒外，何须近郭居。","避人宁信虎，奉母并携书。","药厌韩康卖，田随桀溺锄。","料当雪霁后，曝背一思余。"]},{"t":"自八月初病耳至十一月不愈","f":"五言律诗","c":["病耳四经月，耳根转自清。","鸦啼久绝响，云过似闻声。","箫鼓从来厌，是非何处生。","老年诸籁息，毋复畏天倾。"]},{"t":"怀城中诸公","f":"五言律诗","c":["只在边尘里，年年老别离。","冰霜原共苦，山水岂余私。","有命荷皇泽，无家感佛慈。","愿言各努力，庶足慰相思。"]},{"t":"与孤松","f":"五言律诗","c":["仰瞻皆欲拜，即我亦难亲。","鹤语犹妨闹，雪来不厌频。","枝危如接世，根拙似嫌人。","转厌冰将解，群芳共一春。"]},{"t":"偶成二首 其一","f":"五言律诗","c":["岂是爱山水，从来任我真。","嫚松宁有罪，叱石不生嗔。","歌发随长短，倦时任屈伸。","回思尘世内，束缚可怜人。"]},{"t":"偶成二首 其二","f":"五言律诗","c":["好恶非他事，寻思可奈何。","地低停雪厚，树密惹风多。","来日谁堪虑，今宵我且过。","莫为长久策，仰面尽高歌。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其一","f":"五言律诗","c":["何处投新句，松关日已曛。","倾来千斛雪，惊起一山云。","萝影枯逾瘦，泉声冻尚闻。","相期春渐暖，一榻可平分。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其二","f":"五言律诗","c":["著雪心难冷，摊书道未穷。","茆檐宜向日，布帽且禁风。","味淡君无厌，吟寒孰与同。","时应招野叟，兴发一枰中。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其三","f":"五言律诗","c":["拚是掷穷边，心休莫问天。","小窗容昼景，薄粥喜朝烟。","汲古终无罪，买山不用钱。","倦来拳作枕，身在古皇前。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其四","f":"古风","c":["担泉知不远，久息丈人机。","地僻谁堪觅，庭閒鸟亦稀。","但能藏海畔，何必羡渔矶。","秪合长相问，?毵几衲衣。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其五","f":"五言律诗","c":["酒旆隔疏篱，无人水半卮。","望云时有泪，闻鸟不胜悲。","饱食閒何虑，孤眠冷莫辞。","惟应与松柏，寂寞保霜姿。"]},{"t":"木公以新斋成述怀诗六首寄山中依韵奉和 其六","f":"五言律诗","c":["只在铁桥畔，寒梅绕屋花。","可怜清晓梦，唤醒隔窗鸦。","岁暮日逾促，乡遥愁更赊。","那堪几相识，咫尺即天涯。"]},{"t":"闻左九哥病寄慰","f":"五言律诗","c":["君今年正少，早撇少年情。","灭性非人子，传家赖阿兄。","雁归春渐近，碛远雪初晴。","努力加餐饭，无令百感生。"]},{"t":"赠高涵寰居士","f":"五言律诗","c":["所重惟良友，兼之患难同。","长斋亲衲子，独宿傍仙翁。","交道真逾淡，文情老益工。","只愁风雪后，孤迹任飘蓬。"]},{"t":"赠高辛裔居士","f":"五言律诗","c":["出塞有诸子，惟君气独雄。","见金曾似土，饮酒每如虹。","生死重然诺，文章到困穷。","庄周何日了，相对共谈空。"]},{"t":"喜无为三子至二首 其一","f":"五言律诗","c":["见说南中士，东来道阻长。","何须问姓字，自可共冰霜。","碛大堪埋骨，天空欲断肠。","相看强相笑，不敢问家乡。"]},{"t":"喜无为三子至二首 其二","f":"五言律诗","c":["盼盼似人喜，跫然慰我心。","暂停新泪下，一见故情深。","梦里秦淮鼓，山前虎豹林。","从今风雪际，又听操南音。"]},{"t":"赠普愿师","f":"五言律诗","c":["咫尺幽居近，晨昏独扣门。","閒谈惊鬼胆，静对见天根。","礼法岂为我，畦蔬尽可飧。","焉知寒塞外，古道至今存。"]},{"t":"闻戴三将入长安","f":"五言律诗","c":["春风得意初，策马莫踌蹰。","未献金门赋，先怀梁狱书。","君恩从此阔，子道乃无馀。","伫看章江上，青衫伴素车。"]},{"t":"人日有感","f":"五言律诗","c":["此地无人日，蒙头且自过。","惊心非虎兕，刺眼是山河。","风度衣逾薄，霜侵镜已皤。","更添愁寂处，钟磬晚堂多。"]},{"t":"留题首山丈室","f":"五言律诗","c":["出郭刚十里，到来隔世哗。","不知谁是主，即此便为家。","半榻悬清梦，疏棂见晚霞。","几年沦落意，尽付海东涯。"]},{"t":"宿向阳寺","f":"五言律诗","c":["但使忘人世，居山何必深。","断云栖破衲，积雪老禅心。","客去门仍掩，窗空月每侵。","病夫怯登陟，只此易相寻。"]},{"t":"游大安寺","f":"五言律诗","c":["石磴如天上，钟声下界闻。","已扪千丈雪，犹隔几重云。","山冷僧俱瘦，堂閒虎与群。","古碑苔藓合，洗剔见虫文。"]},{"t":"游龙泉寺","f":"五言律诗","c":["洞口凭猿引，逶迤石路迢。","到门惟虎迹，望寺在山腰。","龙去泉仍溜，春残雪不消。","老僧忘岁月，恍惚话前朝。"]},{"t":"游祖越寺","f":"五言律诗","c":["殿閟疑天辟，凄凄几个僧。","板桥通野豕，木佛坐孤灯。","说法呼顽石，烧泉拾古藤。","禅居高绝处，欲上病安能。"]},{"t":"雪斋落成","f":"五言古诗","c":["四海少邻并，况兹东复东。","登阶惟鹤迹，挂壁有诗筒。","岂为儿孙计，聊安君子穷。","委怀存宋拓，论事据枯桐。","千卷万卷在，两人三人同。","快谈当圣代，高咏寄玄穹。","云过一床影，月来诸境空。","难容金络马，共老竹编虫。","世界半窗隔，神明寸管通。","囊开馀积雪，帘捲渡飞鸿。","稠叠深秋色，浑含太古风。","人情轻故旧，天意勘英雄。","览镜添髭白，烧泉扫叶红。","浮生只若此，大业在其中。","前往后犹待，隐然抱厥躬。"]},{"t":"宿西寺","f":"五言古诗","c":["破寺背城郭，开门对巑岏。","流云时入席，看斗独凭栏。","松落子堪拾，菊荒英可餐。","偶行出篱外，閒眺入林端。","意静鸟俱息，身微叶共残。","更无人问讯，自与月相干。","池瘦荷衣碎，径斜鹤影单。","疏髭先雪白，贱骨抵风寒。","扶杖返虚阁，吹灯卧草团。","人生苦不足，得此良已难。"]},{"t":"老叟","f":"五言古诗","c":["何来孤独叟，自道腹中饥。","入户眉先皱，登阶力已衰。","生年曾不记，近事幸无知。","须鬓留前代，乡邻失旧时。","延龄凭布袋，移步仗松枝。","但忆身方壮，世途甚坦夷。"]},{"t":"寿苗鍊师","f":"五言古诗","c":["人间初换岁，天上亦添龄。","未老耿南极，能飞滞北溟。","时艰惊蝶梦，神王鄙熊经。","寒雪尚凝砌，和风已拂扃。","吹笙鸾凤集，念咒鬼神听。","度世心尤切，弥年手不停。","侣沙虫猿鹤，召雨电雷霆。","采药重薇蕨，汲泉带参苓。","肝肠关众命，呼吸通群灵。","展卷辨蝌蚪，退身号蟭螟。","虽知守其黑，无计得以宁。","残魄予将朽，方瞳尔独青。","金茎润菜色，丹室吐兰馨。","谈笑具别旨，往来各忘形。","他山足玉石，一水合渭泾。","高志存鸿鹄，大光眩爝萤。","胡为悬万石，徒自击寸莛。","兔颖空盈匣，鱼肠待发铏。","波流岂复返，膏燄可长荧。","不见大椿树，八千终飘零。"]},{"t":"同社中诸子赋百韵","f":"楚辞体","c":["猗与洛多士，共此海一涯。","惨日无舒景，狞飙不断吹。","昼闻苍兕吼，夜见乱星垂。","春尽花未发，秋来草先萎。","况当严凝际，复遇荒歉时。","雪大颇充啮，沙多曷任炊。","已看薪似桂，安得稼如茨。","食字字欲尽，问神神不知。","求方希辟谷，绕树叹无枝。","世路肠千折，人情水半卮。","曳裾向何处，弹铗更依谁。","却忆公孙度，难寻钟子期。","马公思设帐，董氏久虚帏。","罪积甘缧绁，泪纷比绠縻。","出门徒彳亍，矢志各参差。","家远地难缩，愁宽天可弥。","寄书凭塞雁，解佩欠金龟。","秪觉丝生鬓，惟馀肉在髀。","囊空存兔颖，貂敝羡羊皮。","心腹告山鬼，须眉照碧池。","矮檐常抱膝，永夕独支颐。","纵尔贫兼病，幸无磷与淄。","投林藏雾豹，入市怯人螭。","鲁国衣冠族，秦中豪杰儿。","岚烟五岭远，文藻六朝摛。","鹿走看獒逐，鹤飞并雉罹。","赤髭经火劫，铁嘴试刚椎。","君父恩冈极，死生苦不辞。","求仁又何怨，质圣而无疑。","智为繁忧长，力因多难羸。","形容虽已槁，精理肯教隳。","文偃剩跛脚，香严无卓锥。","但存乞食相，那用买山赀。","托钵望城郭，谈经闹边陲。","运颓知莫振，衲破尚堪支。","濯足乌龙窟，洗肠白石湄。","长江还淼淼，归鸟正提提。","梅坞怀方切，春塘梦独稀。","终朝劳短策，暗室拭长鉟。","虹气供吞吐，鲸波静指挥。","四维阴羃羃，两袖冷飔飔。","荒冢卧封豕，欹台游瘦狸。","抬眸瞰广漠，纵步陟厜㕒。","涕吐牛蛇走，叫呼霹雳驰。","东溟观出日，北镇读残碑。","西岫哭义士，南邻舞阏氏。","乾坤仍自阔，陵谷倏然移。","倾血倒三峡，招魂到九嶷。","揭开王蠋面，唤起卞壶尸。","胆但当空沥，肝惟对佛披。","怪思屠魍魉，险欲狎穷奇。","幽意通岩瀑，閒情侣涧麋。","崩崖搜朽骨，古庙索遗词。","仙客遇清笑，玄风布和熙。","函关去莫返，华表来何迟。","承露浇麻饭，烧檀煮玉饴。","解将新布袋，剖却旧藩篱。","尸许从沙暴，车宁荷锸随。","洪涛咒可竭，顽性法难治。","屡过扬雄室，每逢安石棋。","冰心互映彻，兰味播芳蕤。","交谊久已弃，遗文良在兹。","艰虞深阅历，遒劲共扳追。","矻矻千寻石，汪汪万顷陂。","土床容偃仰，缃帙任唔咿。","古柏信孤挺，狂猿本不羁。","雄谈裂帧幅，妙句出炉锤。","骤雨催吟兴，寒霜沁诗脾。","分题多吊古，造意欲淩巇。","残墨堪同赏，新篇足自怡。","桐枯未作爨，松实暂疗饥。","二子喜听论，一锜尽成麋。","且抛千载憾，相与片时嬉。","小人应学圃，遗老亦敷菑。","岂怼蜮能射，宜安命所施。","管宁曾戴帽，尼父欲居夷。","吾道信东矣，先生将何之。","只闻囚羑里，畴为献鸡斯。","左氏三都贵，苏卿五字师。","傅岩筑以版，渭水钓非罴。","野蕨欣犹采，社莲恨已衰。","山东得李白，江左来桓伊。","执耳尔胡让，登坛众所推。","吹笙约子晋，击筑邀渐离。","异域留商哻，石人见汉仪。","空城招旧帝，青草惜娥眉。","骚续屈平怨，赋添宋玉悲。","唱酬浑不厌，来往各忘疲。","酒奈无赀畜，节应到秃持。","杂心勿与人，拙目尽教嗤。","此日亦常事，万年定渴思。","好将藏洞壑，何必勒钟彝。","取义戒伤激，怀刑嫌近痴。","果能了性命，更莫问安危。","凤鸟徒鸣舜，龙图只授羲。","滔滔者皆是，蹙蹙若奚为。","世事讵难识，帝心可微窥。","浮云无终蔽，皎月岂长亏。","盈则覆之兆，祸兮福所基。","举头语诸子，毋自苦嗟咨。"]},{"t":"赠辽阳陈令公十韵","f":"五言古诗","c":["圣朝恩旧里，孤客宦边庭。","官冷兼冰冷，身形似鹤形。","升堂除积雪，编户补疏星。","衣剪残荷碎，厨炊野蕨馨。","寻僧分钵饭，对吏读棋经。","新市凭鸦集，重关畏虎扃。","草荒连砌白，山近到床青。","采木探幽谷，弓田步远坰。","人贫惟有爱，讼少不须听。","立德存华表，书名在御屏。","伫看寒碛上，丹凤下天廷。"]},{"t":"偶述二十韵","f":"五言古诗","c":["忆昔岁戊子，投荒自我初。","举头多局促，那步独踌蹰。","所苦非冰雪，相期在壑渠。","主人法渐弛，贱子罪方纡。","身首幸无虑，心神尚未舒。","逢人强笑谑，暗地足欷歔。","耆旧常分粒，高朋许借书。","便将好日过，不觉数年馀。","双屐穷梵宇，盈瓢饱野蔬。","飘飘无定止，处处得安居。","衰病因无禁，孤贫益自如。","偶然值老叟，招我入茆庐。","塔外无诸响，瓶中有夙储。","残编堆几满，寒月映窗虚。","云密尘难入，山空梦亦除。","以兹知足矣，何必叹归与。","信口歌吟富，关门礼法疏。","长林藏倦鸟，幽涧纵潜鱼。","寄问同流者，为欢信有诸。","皇仁应普及，天意岂私予。"]},{"t":"甲申岁除寓南安","f":"七言律诗","c":["梅花岭下小溪边，寒尽孤僧泪独涟。","衲底尚存慈母线，担头时展美人篇。","先皇岁月馀今夕，故国风光忆去年。","香冷夜深松火息，万方从此静烽烟。"]},{"t":"乙酉元旦","f":"七言律诗","c":["万年新历自今朝，兵气都随残腊销。","龙虎山河开旧域，凤凰宫阙集群僚。","波停海外来重译，干舞阶前格有苗。","野老瓣香无别祝，箪瓢处处听歌尧。"]},{"t":"秋呓八首 其一","f":"七言律诗","c":["铁骑飞传海上音，彤云霭霭幕秋阴。","元戎已作槛中虎，黄阁空留井底金。","半壁久添亡国恨，翠华难系老臣心。","独怜白首商人妇，重拨琵琶泪满襟。"]},{"t":"秋呓八首 其二","f":"七言律诗","c":["日光暗淡鸊鹈寒，独上牛车泪已湍。","魏绛读来成画虎，文山到死愿黄冠。","乡心未尽鼍声急，陵树先凋鹤梦残。","正拟招魂秋草里，疏钟微月夜漫漫。"]},{"t":"秋呓八首 其三","f":"七言律诗","c":["露下霜残冷碧霄，乡心处处长天骄。","云横淮海三千筏，风定钱塘六月潮。","石虎岂能消杀伐，卢敖无计慰飘摇。","何时重问峰头侣，夜半吹箫过铁桥。"]},{"t":"秋呓八首 其四","f":"七言律诗","c":["倚杖逢人麈偶挥，风流还说旧王畿。","赭衣少妇能骑马，白面书生学打围。","是处烽烟迷笠屐，年来药碗失芳菲。","芰荷叶老虫声切，惆怅家山未可归。"]},{"t":"秋呓八首 其五","f":"七言律诗","c":["美人家住白云乡，独上高楼枉断肠。","丹荔剥馀蕉正熟，素馨开遍柚初香。","人间何处寻黄鹄，梦里分明见石羊。","莫向凤凰台上望，秋风秋雨正茫茫。"]},{"t":"秋呓八首 其六","f":"七言律诗","c":["翘首长空动晚飔，苍梧一去失归期。","啼魂欲拟三更月，续命先传五色丝。","天寿山前云漠漠，石头城上草离离。","伤心玉叶凋零后，犹剩天南第一枝。"]},{"t":"秋呓八首 其七","f":"古风","c":["凉月团团照远空，荻花如醉蓼花红。","江湖无复藏鸥迹，天地何曾享马?。","已见旄头沉赣水，又闻大旆出秦中。","只今五岭无消息，望断长干数落鸿。"]},{"t":"秋呓八首 其八","f":"七言律诗","c":["长松千尺野烟迷，别馆萧条日已西。","廿载功名归梦蝶，五更风雨听潮鸡。","曲池凉浸桐花影，复道尘封御墨题。","燕子重来王谢改，庭前芳草马空嘶。"]},{"t":"乙酉除夕二首 其一","f":"七言律诗","c":["穷年于役笑狂夫，掩却閒窗一事无。","对佛不殊栖影鸽，怀人欲折渡江芦。","浮山梦里梅难寄，鼙鼓声中日易徂。","今夕剧怜灯火冷，夜深空照几僧孤。"]},{"t":"乙酉除夕二首 其二","f":"七言律诗","c":["小雨空濛罩远天，愁心只在水云边。","半生事业鬓间雪，万里音书岭上烟。","爆竹不烦惊旅梦，残花留得伴枯禅。","鱼声梵呗浑成泪，破衲蒙头又一年。"]},{"t":"丙戌岁除卮亭同衣白双白方鲁诸子","f":"七言律诗","c":["到处看山岁已徂，梅花点点怨江湖。","南阳事业归何地，东鲁旌旗仰大儒。","拜月尽瞻新面目，窥池不改旧头颅。","世间亦有閒于我，共向方亭伴结趺。"]},{"t":"丁亥元旦昧庵试笔","f":"七言律诗","c":["每逢遗老即留连，病骨支离不记年。","但有心胸还宇宙，更无眼目借人天。","石头几度分乡思，春色何曾到客边。","扶杖登楼閒一望，南山如旧涕空涟。"]},{"t":"闻本师空和尚移锡闽中","f":"七言律诗","c":["华台咐嘱久相违，杖履何因别翠微。","五岭人天遮眼目，八闽风雨落珠玑。","执巾若个还随步，挥麈伊谁忽扣机。","惭愧一枝寒塞外，黄沙白雪亦霏霏。"]},{"t":"闻本师将来石头","f":"七言律诗","c":["孤锡何天不可飞，遥知到处足归依。","愿携半面新神鉴，来照三山旧帝畿。","风火大千生佛泪，水云百匝雨花霏。","瓣香拈起人皆仰，白月长边一色辉。"]},{"t":"寄阿谁","f":"七言律诗","c":["敝履曾将寄阿谁，平生端许阿谁知。","破斋风雨三更话，乱世心肝万古期。","笔墨有神烈火劫，发肤无恙大江湄。","巫闾白雪卮亭柳，遗老孤僧夜夜思。"]},{"t":"再寄阿谁","f":"七言律诗","c":["三百年来一老臣，蹁跹双袖白纶巾。","数茎霜雪留前代，半幅江山付后人。","诸祖传灯能共證，满庭流水未全贫。","遥知桥畔梅花发，极目寒边欲寄春。"]},{"t":"得友沧江南信","f":"七言律诗","c":["灯前忽接江南信，未拆先惊喜复疑。","大漠到来三易岁，白门死却几相知。","两人心事六千里，片纸书题九月时。","捧读从头亲切语，一天冰雪见须眉。"]},{"t":"寒夜偶成","f":"古风","c":["日短无妨独夜愁，?毵布衲自蒙头。","白杨梦绕尚书冢，大石云封仙客楼。","霜气正浓心匪席，钟声不远月如钩。","更长任尔终须晓，能使沉沉万古不。"]},{"t":"岁暮雪中","f":"七言律诗","c":["四十风光一抹收，故乡望断岁如流。","料因诃佛填冰狱，岂为修文上玉楼。","雪尽埋时偏得句，天当崩后更无忧。","当年六载行难满，殃及儿孙冷不休。"]},{"t":"同诸子宿雪斋","f":"七言律诗","c":["冰天尽日麈纵横，秉烛还教续笑声。","今岁眼看片影过，几人身在一宵情。","枕边各自家乡近，笔下何妨星斗惊。","到晓定知饶别泪，土床如水听鸡鸣。"]},{"t":"偶感","f":"七言律诗","c":["天地为圜山水囚，无弦一操亦拘幽。","罽宾尚自容狮子，石虎真同狎海鸥。","饱食更无思作佛，生还端不愿封侯。","请翻青史兼灯录，亦有痴顽似我不。"]},{"t":"闻浪大师主法伞岭","f":"七言律诗","c":["马耳峰头食蜜甜，长干花瓣又重拈。","共经劫火三禅乐，分取曹源两地沾。","伞岭杖头风日朗，天山衲底雪霜严。","不禁钟尽怀方切，寒雁无声月一帘。"]},{"t":"闻遁庵伞岭监院","f":"七言律诗","c":["何人寒夜苦相思，犹忆临岐赠一枝。","百丈再参惟马祖，慈明总院属杨岐。","出笼孤鹤抟风疾，穿市泥牛蹴月奇。","鸭绿江头频斫额，好将消息寄边陲。"]},{"t":"寄茂之二首 其一","f":"七言律诗","c":["髫年见尔蚤登坛，瓦钵藜羹每共飧。","两世交游情更切，七朝耆旧泪难乾。","孤山未得林逋适，后学谁知范叔寒。","料得岁残吟倦后，铁函偷启避人看。"]},{"t":"寄茂之二首 其二","f":"七言律诗","c":["破屋残书虎豹邻，萧萧风雨独相亲。","一时群士推前辈，半世相交属古人。","几食神仙终不饱，屡看儿女始知贫。","冰天欲寄新诗卷，老眼应知泪又频。"]},{"t":"寄与治二首 其一","f":"七言律诗","c":["乱后投交白板门，梅花香饭每同论。","平生最苦人皆好，古道全凋尔尚存。","客到定留徒四壁，诗成不厌倒千樽。","世间那见清贫士，猿鹤沙虫尽感恩。"]},{"t":"寄与治二首 其二","f":"七言律诗","c":["一卷诗书动甲兵，鸟飞鱼逝海天惊。","许多人士欣同死，费尽精神荷再生。","书寄极边看雁度，影留孤壁共鸡鸣。","想当花发高朋集，独少残僧笑语声。"]},{"t":"寄与然师","f":"七言律诗","c":["半世风流薄倖名，蛮烟琴韵苦冰清。","后门开处如花散，大厦倾时集杖横。","一幅云山通性命，四围弓剑见交情。","年来何地堪行脚，绝塞思君草履轻。"]},{"t":"寄孟贞","f":"七言律诗","c":["石子冈头共苦吟，交情老向水云深。","孤僧罪案横诗卷，伯氏遗词发道心。","婚嫁若完休卖赋，须眉白尽好投针。","连年何限悲酸句，曾否招魂到海浔。"]},{"t":"寄于皇","f":"七言律诗","c":["大风吹梦渺无垠，白鹭洲前彩袖贫。","今古更教谁搦管，乾坤似未可容身。","钟声屡听寒僧饭，诗句时生山鬼瞋。","好拟招魂东海畔，沅湘不独没灵均。"]},{"t":"寄澹心","f":"七言律诗","c":["木佛寒边尚未烧，黔王宅畔梦相招。","抬眸直可烁千界，挥藻真堪贱六朝。","碎却青衫天地裂，收回残魄日星昭。","铁函珍重休沉井，那见黄尘彻底飘。"]},{"t":"寄州来","f":"七言律诗","c":["频年剥啄识相过，古寺寒泉笑语多。","剑影千寻依佛火，书声一半落江波。","每当静夜闻花雨，秪恐雄心裂芰荷。","远碛有怀诗定苦，数篇莫遣雪儿歌。"]},{"t":"寄今度","f":"七言律诗","c":["石头旧社羡耆英，数载周旋世外情。","绣佛放参贪米汁，素王遗训足藜羹。","中山华胄尊明道，五岳灵祇笑向平。","为语诸郎抛纸笔，无灾更不用公卿。"]},{"t":"寄一门介直二法王","f":"七言律诗","c":["几年白拂各横纵，垂死相看道味浓。","人在石头江月冷，诗从天半岫云封。","座前花雨三春梦，谷里松风午夜钟。","二老有心原不系，医巫闾下想飞筇。"]},{"t":"寄秭经","f":"七言律诗","c":["是知不可奈民艰，吴楚声名苦未閒。","须达布金为续命，东坡解带欲留顽。","交情只在死生际，立德偏于云水间。","惭愧报恩惟一杖，好寻猿鹤步青山。"]},{"t":"寄尔止兼讯元白彝仲","f":"七言律诗","c":["孤踪如鹤笔如泉，抖擞奚囊淡淡仙。","卖赋不酬兼卖卜，忧贫无计独忧天。","马融名下玄为首，荀淑筵中实最贤。","想得团圞风雪里，共斟白水奠寒边。"]},{"t":"寄文寺昆仲兼讯令侄","f":"七言律诗","c":["安世威名海屿传，龙泉虽失笔如椽。","二难拮据寻灰烬，一代风流入品铨。","枝上鹊巢惊虎豹，枕边蠹简剩神仙。","东山屐齿须珍重，未了还须望阿玄。"]},{"t":"寄徐氏昆仲","f":"七言律诗","c":["钟山王气散残霞，犹向乌衣识旧家。","义士肝肠才子韵，人间富贵梦中花。","已知麟阁三秋草，何处青门五色瓜。","珍重玉函天藻在，伫看溟渤又飞沙。"]},{"t":"寄无伤","f":"七言律诗","c":["瘴海南浮去杳然，相期犹在白云巅。","乡情翻为友朋动，古谊宁因岁月迁。","箕子里中魂欲断，越王台畔屐将穿。","罗浮村月应无恙，未必梅花似昔年。"]},{"t":"除日大翁同薪夷过集","f":"七言律诗","c":["如此年光去不辞，匝天阴雾约同支。","因君父子团圞话，添我家山割绝悲。","一树梅花成异想，半壶冰水共交知。","春风到底还来日，薄暮相看鬓已丝。"]},{"t":"除夕别皈藏","f":"七言律诗","c":["明晓相逢隔岁期，秪争一宿惜分离。","论交死地情加重，定罪寒边老不疑。","愁到尽头宁再换，顽深彻骨更难移。","眼看归路消残晷，眄眄春来未可知。"]},{"t":"除夜","f":"七言律诗","c":["又到边庭岁尽时，孤灯空照两茎眉。","三年尚未喂豺虎，一息还将报我师。","绕座诸山皆老宿，才言大法已支离。","归堂稳卧不须守，榾柮烧残冷自知。"]},{"t":"辛卯元旦","f":"七言律诗","c":["鸡声云集礼金仙，一搭袈裟泪独涟。","六载雪山馀业在，五家灯火极边传。","疏星落落天将曙，宿雾重重日渐圆。","自有瓣香人不识，万年逢祝海东偏。"]},{"t":"元旦有感二首 其一","f":"七言律诗","c":["老眼未曾看历日，如何岁岁在龙蛇。","相逢知友休相问，不是贤人亦自嗟。","旧腊坚冰仍匝地，枯枝残雪尚开花。","新愁又是从头起，安得春风到海涯。"]},{"t":"元旦有感二首 其二","f":"七言律诗","c":["寥落家家惜晓春，朔风仍自觅孤身。","恒河流水还生灭，冷碛飞沙无故新。","西极龙颜心咫尺，南天马鬣梦悲辛。","眼看鲸海波涛细，犹可残生见世人。"]},{"t":"遥哭秋涛","f":"七言律诗","c":["云淙一出人皆望，天宇频倾势莫收。","若水挝唇无二日，文龙指腹定千秋。","忍将礼乐随身去，尽把心肝报主休。","自有容台遗稿在，长偕正气世间留。"]},{"t":"遥哭玄子","f":"七言律诗","c":["龙髯一坠恨身存，万里崎岖哭主恩。","邓禹未能追邺下，秀夫终合殉崖门。","词林尚吐文章气，沙碛频招忠义魂。","从此千秋沧海上，风涛怒捲血犹浑。"]},{"t":"遥哭美周","f":"七言律诗","c":["一身许国气无前，贡水波漫热血溅。","菩萨道穷皈马革，孝廉船覆失龙泉。","家馀老母西方泪，梦绕孤僧北塞烟。","节义文章浑泡影，莲须重结后生缘。"]},{"t":"遥哭未央","f":"七言律诗","c":["飞云顶上忆同游，风雨相期苦不休。","自向虚空明节义，何妨平等别恩仇。","宰官忽现睢阳齿，祖道唯悬狮子头。","未了团圞他世事，白山黑水日悠悠。"]},{"t":"遥哭巨源","f":"七言律诗","c":["方筇把赠大江滨，垂涕相看各怆神。","我窜异方生亦死，君从前代鬼成人。","西山雨过画堂寂，南浦云横古道堙。","叹惜旧游谁复在，独留双眼哭高旻。"]},{"t":"遥哭千里","f":"七言律诗","c":["甘露曾闻饮郑平，肯教弱水隔蓬瀛。","云烟淡淡眉间见，佛祖明明指上生。","看尽桑田松阁冷，抛残丹灶笔床横。","三彭未绝身先死，点泪黄沙哭紫清。"]},{"t":"薪夷暮过","f":"七言律诗","c":["日暮抛书叩我门，土床呼坐礼无烦。","士当缧绁非其罪，顽到袈裟不可言。","已讶新篇凌屈宋，更参妙义指风幡。","钵中抖擞馀残粒，带雪连声且共吞。"]},{"t":"与薪夷同榻不寐","f":"七言律诗","c":["薄被难将笑语温，枕头如水覆仍翻。","坚冰到骨两条铁，冷月来床一片魂。","梦趣屡从邻衲乞，夜深好共老天言。","鸡声忽听休惊舞，只恐轻狂动佛尊。"]},{"t":"北里过访","f":"七言律诗","c":["出门大雪欲何之，僮仆无言瘦卫知。","只在南郊三里外，定因昨日老僧期。","带围那得留荒寺，诗句还能慰我饥。","乘兴不妨明又到，肯因无酒便攒眉。"]},{"t":"招高一戴三同过北里喜剌翁春侯至兼订后会","f":"七言律诗","c":["出门定向北郊行，半路招呼冷弟兄。","群雁嗷嗷添鹤唳，幽兰馥馥共藜羹。","嗟予岭海梅花梦，羡汝池塘春草生。","薄暮曰归重订约，无过隔日足离情。"]},{"t":"再集雪斋竟日","f":"七言律诗","c":["如何先遣朔风迎，未到惊闻斗室轰。","三百年来剩一笑，几千里外共馀生。","弟兄冰雪交情热，天地龙蛇老气横。","此日不须半点泪，且留佳话付边城。"]},{"t":"寒日偶成","f":"七言律诗","c":["懒残獦獠一身兼，不合时宜我自嫌。","荷叶飘零衣又碎，菜根啮尽雪方甜。","道心岂为饥寒长，诗料偏于沙碛添。","满面灰尘双涕冻，展开书卷向风檐。"]},{"t":"同诸子集雪斋","f":"七言律诗","c":["此是边城第一日，卢胡大笑即神仙。","半收閒论归灯录，全采寒冰当绮筵。","善谑支公偏堕落，能飞丁令忽飘翩。","茆齐西去无多路，明晓同过话冷毡。"]},{"t":"再集高寒还舍","f":"七言律诗","c":["一日已离又一日，萧然斗室忽喧天。","笑开绝塞三年口，吞尽寒儒半块毡。","冷冷牧牛诸衲子，纷纷跨鹤几神仙。","何人补衮诗篇富，携得寒冰照骨鲜。"]},{"t":"闻北堡三子为僦主所逐","f":"七言律诗","c":["六朝遗藻属三贤，才得相逢又各天。","及到极边重被逐，纵贫彻骨不禁怜。","溪头漂母归春梦，岩下刑人望晓烟。","但愿速来吾钵在，一匙分取湿寒毡。"]},{"t":"诸子过集","f":"七言律诗","c":["几人清晓问幽栖，唤起孤僧意自迷。","到处宫墙皆牧马，极边瓶钵尚闻鸡。","空谈亦可閒消日，大笑何能数过溪。","正好团圞愁别去，土床依旧冷凄凄。"]},{"t":"大翁再过","f":"七言律诗","c":["入门先索袖中诗，未出还疑句过奇。","几日梦思惊铁磬，两人心胆告毛锥。","斲空祇恐伤天骨，霏屑时堪解佛颐。","白水一卮忘久坐，童饥任怨得归迟。"]},{"t":"有怀","f":"七言律诗","c":["兽炭成灰冷铁猊，孤灯木佛各凄凄。","已闻岭海传烽火，翻怪边城静鼓鼙。","沙为雪铺寒更远，天因云幕晓尤低。","松枝岁岁皆东指，弟子于今却望西。"]},{"t":"过昌黎故里","f":"七言律诗","c":["曾贬潮阳路八千，潮阳山水仗公传。","谁知一片蓝关雪，又伴孤踪辽海边。","佛骨偏能留世道，鳄鱼今已遍桑田。","当时空自三书重，此际应知识大癫。"]},{"t":"踏冰过雪斋","f":"七言律诗","c":["寻风寻雪欲寻谁，北里先生睡起迟。","千片冻云沉地骨，一方清鉴照僧眉。","草鞋易滑肌羸后，拄杖忽停诗到时。","便使不禁死亦得，枯骸千古浸冰池。"]},{"t":"读雪斋新诗","f":"七言律诗","c":["到门白尽两边篱，独拥半裘一见疑。","半个孤僧连雪倒，数篇新句忍寒披。","鬼当哭处予偏妒，血到漓时佛更悲。","三日下来应冻死，早成一首哭冰诗。"]},{"t":"久坐雪斋","f":"七言律诗","c":["蚤过疏雪挂双眉，坐到斜阳两不知。","撒尽风颠宁作我，留将气骨自教儿。","一匙每节僧方饿，半晌无言句又奇。","从此板扉无剥啄，便知托钵到来时。"]},{"t":"从雪斋归","f":"七言律诗","c":["出门一步即相思，依旧崎岖冷独支。","只雁负霜沙上至，野僧将月杖头随。","总来雪窖堪长往，那见龙津更不离。","归到柴扃閒未掩，啾嘈寒雀共论诗。"]},{"t":"怀苏筑","f":"七言律诗","c":["相思只在海之涯，共是飘流垫雪沙。","到处谈经吾有钵，对天弹铗尔无家。","树寒夜绕徒三匝，腹饿空扪剩五车。","但愿上苍长雨粟，从今更不用天花。"]},{"t":"得苏筑堡中信却寄","f":"七言律诗","c":["一纸新传趁晓风，又添寒泪洒虚空。","雪中一衲朋难共，饭后无钟我亦穷。","胥靡忍饥存海岸，武丁曾梦到关东。","他年纵有图形至，只恐愁多貌不同。"]},{"t":"寄陈吴二子二首 其一","f":"七言律诗","c":["天心边色总冥濛，三子同来尔一翁。","白眼欲枯重著雪，青衫已破又吹风。","但将胸腹长留饿，未必文章好送穷。","惭愧老僧馀舌在，广长终不救囊空。"]},{"t":"寄陈吴二子二首 其二","f":"七言律诗","c":["形容憔悴气犹雄，携得江涛过海东。","天网既能罗野鹤，边霜偏欲冷书虫。","已知笔竞湘沅富，见说针兼秦越工。","此地参苓原有禁，可怜文士术终穷。"]},{"t":"再得苏筑堡中信","f":"七言律诗","c":["不见音书已浃旬，却疑孤骨付荒榛。","黄垆暂放文章鬼，白社还留饥饿民。","岂有信陵能醉客，只馀甘贽未嫌贫。","菜根共咬消残岁，竹杖柴门候早春。"]},{"t":"再寄北堡三子","f":"七言律诗","c":["相看白昼拥寒衾，饿极方知天意深。","但使常垂地主眼，安能更入野僧心。","老猿或可招新社，黑月应当罢苦吟。","此处尚留诸子在，何时煮雪一同斟。"]},{"t":"闻何怀山延三子度岁","f":"七言律诗","c":["本是莲花国里人，黄沙此日暂羁身。","维摩有室能容傲，须达无钱为给贫。","地下三良魂可赎，山头二士骨犹邻。","何时雪底拈花话，方信穹庐别有春。"]},{"t":"赠李鋉师","f":"七言律诗","c":["偶尔相逢似旧知，匡床共坐啜山薇。","只应蝴蝶忘愁恨，莫向人民问是非。","多病自怜馀鹤骨，爱閒无计掩云扉。","何时得遂芒鞋愿，白日从君踏翠微。"]},{"t":"赠苗鍊师","f":"七言律诗","c":["年少如君早息机，冰霜为骨羽为衣。","虎溪何可无修静，辽海依然见令威。","几看桑田添野梦，频炊白石疗僧饥。","他时许共骑黄鹄，好向浮山顶上飞。"]},{"t":"怀丁善甫","f":"七言律诗","c":["苦留短发近如何，无地堪容挂绿蓑。","山月楼台愁梦断，江花儿女悔情多。","幸存料自修文冢，愤死凭谁弃草坡。","天外故人心未改，西风斜雨念残荷。"]},{"t":"怀梁渐子","f":"七言律诗","c":["岭海于今信有渠，寂寥扬子病相如。","国人已恐歌黄鸟，诗卷曾无寄白鱼。","马革纵能饶瘦骨，鹿门何处隐柴车。","他年得返皈龙洞，惟索穷愁旧著书。"]},{"t":"怀梁非馨","f":"七言律诗","c":["廿年作客白门秋，辛苦还家短发留。","半壁又虚惟裂眦，匝天何处可埋头。","文章自合随身老，贫贱除非到死休。","绝塞忽思酬唱地，西湖有月大如瓯。"]},{"t":"李耀寰移家入关","f":"七言律诗","c":["除却妻儿书一束，黄沙长揖去飘然。","赀粮只在云山里，肝胆全倾水月边。","回首几人成白骨，入关半步即青天。","愁心岂独伤离别，不得从君鸡犬仙。"]},{"t":"佛欢喜日","f":"七言律诗","c":["恸哭慈悲古佛前，虫沙猿鹤总生怜。","繇来欢喜无多日，别有閒愁已十年。","绝漠尚教留白昼，幽魂不独滞黄泉。","自除须发伤心极，只恐西方泪更涟。"]},{"t":"怀关起皋","f":"七言律诗","c":["十亩池塘百尺松，长桥曲曲度疏钟。","庵前月少孤僧影，堤畔苔侵野鹤踪。","佛手香残凋木笔，马牙烟冷坠荷蜂。","只愁第宅皆新主，燕子归来亦不容。"]},{"t":"闻华首都寺真乘父子无恙","f":"七言律诗","c":["五百何年去不还，独留父子守青山。","洞云灶冷飞黄蝶，砌草碑横卧白鹇。","牛鬼已全倾世界，龙天依旧拥禅关。","团圞莫说无生话，纵解无生泪更潺。"]},{"t":"闻近庐守黄华寺寄示","f":"古风","c":["三把枯茆必不堪，林间安得未烧庵。","日斜尚自敲残磬，叶烂何人启旧函。","松桧劫馀云冷淡，芰荷秋老衲?毵。","城边白骨溪边月，一一从今好细参。"]},{"t":"怀陈燮","f":"七言律诗","c":["长缨欲请恋荷衣，踯躅长途剑屡挥。","亲老有身难许国，天倾无地可扃扉。","乘槎瘴海空相吊，谪戍寒边苦未归。","朋好已稀须已白，不知何处奉慈帏。"]},{"t":"贺大翁添丁","f":"七言律诗","c":["残经犹在伴空籯，艰苦还添舐犊情。","岂为膻乡留字种，又从戍籍注婴名。","数枝照雪阶前玉，一曲将雏塞上声。","堕地便随离乱过，长成应得见升平。"]},{"t":"游南塔寺","f":"七言律诗","c":["满堂龙象肃威仪，绝漠仍存百丈规。","金铎自天开佛口，绿杨近水拂僧眉。","儒门淡泊留迁客，梵宇淋漓读旧碑。","瓦钵绳床吾欲老，他年应见出横枝。"]},{"t":"雨中赠老翁","f":"七言律诗","c":["不知老翁有何好，大雨还令我到门。","匪独黄沙亲佛子，每因青草念王孙。","世人空自金银死，似尔偏生藜藿尊。","从此土床留一尺，频来礼数莫须烦。"]},{"t":"怀梁弼臣","f":"七言律诗","c":["曾寻弥勒许同龛，分手人间便不堪。","一木自难支半壁，三徵终不受华簪。","云山已破家何在，心胆还馀面莫惭。","数亩荒塘天悔祸，尚期携竹共双柑。"]},{"t":"九日","f":"七言律诗","c":["阴云低压殿西头，僧老黄花对面愁。","九日尽抛前代泪，十年深负旧山秋。","系囊岂解消群厄，吹帽谁堪忆胜游。","幸有罪夫三两辈，浑天冰雪定相求。"]},{"t":"重阳集北里大雪","f":"七言律诗","c":["何须佳节亦招寻，此日团圞雪费吟。","天外乡关谁更远，篱边菊泪我弥深。","一床新句添秋色，数枕寒泉浸道心。","趁此晚晴归路白，栖乌未定响疏林。"]},{"t":"喜藏主燕回","f":"七言律诗","c":["龙象天门蹴踏回，惊看屐齿遍莓苔。","陌尘抖向关山尽，秋水携将云水堆。","犬亦因人生气色，尘缘对客共喧豗。","长安半字休须论，满汲清泉且一杯。"]},{"t":"与苏筑同卧叙昔","f":"七言律诗","c":["吹灯忽叙当年话，一卧长边苦不辞。","儒释道同应共逐，君亲恩重又谁知。","楼头钟鼓胸中事，梦里河山觉后疑。","抵背夜寒频坐起，探囊犹有旧毛锥。"]},{"t":"闻诏不果","f":"七言律诗","c":["一面还留三面开，金鸡空度蓟门来。","遗黎未死终怀土，多士虽穷幸不才。","绝域半瓢仍雨雪，旧山万里长蒿莱。","无拘独有深春梦，夜夜离群自往回。"]},{"t":"接与治书","f":"七言律诗","c":["平生相识满天地，此日何人片纸来。","数点泪弹浸墨迹，几年梦去绕梅开。","土田儿女终浮沫，文字心肝总祸胎。","世事一番君已见，莫将白发殉黄埃。"]},{"t":"苏筑新斋成二首 其一","f":"七言律诗","c":["天边仍旧一经传，南郭新看结数椽。","剩有白云来席上，随他绿草到窗前。","诗篇不数开元后，茶椀还书嘉靖年。","但使主人能爱客，何妨竟日共留连。"]},{"t":"苏筑新斋成二首 其二","f":"七言律诗","c":["不离城郭亦孤村，白板青袍道自尊。","半扫泥床延水月，别从竹简得朝昏。","初心未遂天何问，孤骨惟怜我共存。","策杖相过刚咫尺，对君岂直为盘飧。"]},{"t":"赠陈子","f":"七言律诗","c":["长斋无复酒为名，累月相依老弟兄。","每以笑谈当佛事，又从水月见交情。","朋当死地如山重，儒到寒边似叶轻。","南塔主人能爱客，暂将白日付棋枰。"]},{"t":"五月十八日接本师和尚示札","f":"七言律诗","c":["五月天山鸿雁回，披衣三拜寸椷开。","一条楖栗欣犹健，万里乡关嗟已灰。","座下半成忠义鬼，峰头空剩雨花台。","人间自是浮云过，檐雀风铃亦助哀。"]},{"t":"忆丽中法兄","f":"古风","c":["阔别何年思杳茫，一声孤雁泪淋?。","想当乱极悲亲在，共爱恩深见国亡。","书信竟无通远塞，烽烟曾否到禅房。","旧时相识多新鬼，只恐身存已断肠。"]},{"t":"即事","f":"七言律诗","c":["吴楚东南舞白题，庾关安得一丸泥。","三岔河畔羝难乳，五石城中马又嘶。","血浸花田新鬼闹，书传沙碛老猿啼。","何时重踏曹溪路，祇恐禅宫草亦萋。"]},{"t":"得博罗信三首 其一","f":"七言律诗","c":["八年不见罗浮信，阖邑惊闻一聚尘。","共向故君辞世上，独留病弟哭江滨。","白山黑水愁孤衲，国破家亡老逐臣。","纵使生还心更苦，皇天何处问原因。"]},{"t":"得博罗信三首 其二","f":"七言律诗","c":["莫怨穹苍太不仁，万方此日总成尘。","恩深累代心何憾，命尽全家泪又新。","残日沉山犹望旦，落花辞榭永无春。","寻思最苦身仍在，黯黯风沙愁杀人。"]},{"t":"得博罗信三首 其三","f":"七言律诗","c":["长边独立泪潸然，点点田衣溅血鲜。","半壁山河愁处尽，一家骨肉梦中圆。","古榕堤上生秋草，浮碇冈头断晓烟。","见说华台云片片，残枝犹有夜啼鹃。"]},{"t":"忆耳叔弟二首 其一","f":"七言律诗","c":["抱病多年苦未瘳，那堪茕独一身留。","黄沙万里休余念，白骨全家赖尔收。","旧阁遗编鱼腹饱，空天落月雁声愁。","相逢恐是他生事，极目鸰原泪自流。"]},{"t":"忆耳叔弟二首 其二","f":"七言律诗","c":["黑雨屯风折紫荆，生离死别不胜情。","尚书冢上凭谁扫，逐客天边恨未烹。","先代箕裘应弃置，故园狐鼠任纵横。","从今好把袈裟搭，长礼无忧古佛名。"]},{"t":"遣愁","f":"七言律诗","c":["叹息人间劫尽灰，惠州天上亦荒莱。","只拚如此家声在，无可奈何笑口开。","是处总堪埋骨地，从今不上望乡台。","漫言出世除烦恼，悟到无生觉转哀。"]},{"t":"赠洁之","f":"七言律诗","c":["我亦头陀繫远边，羡君来去自飘然。","众生投虎婆心切，只杖如龙侠骨坚。","鸭绿波横杯再泛，燕支雪尽履将穿。","故人白首诗篇足，趺坐还同啮旧毡。"]},{"t":"接元白书物却寄","f":"七言律诗","c":["天涯珍重数行馀，问道何因到瞎驴。","得罪以来全丧我，一飧之外总由渠。","弓刀市上收残影，风雨楼头简旧书。","见说江南无所有，一枝犹得寄巫闾。"]},{"t":"与治书来言为徐氏田累寄慰","f":"七言律诗","c":["今时谁复免忧虞，几度书来叹力痡。","画阁已空搜白屋，小民欲尽索穷儒。","多情自合为身累，彻骨惟应与道俱。","无食无儿非汝恨，残毡犹可学双趺。"]},{"t":"怅望","f":"七言律诗","c":["苍狗白衣瞬息中，况闻五岭满刀弓。","亲朋敢望今谁在，城郭应知到处空。","苏子堤边尸藉草，越王台上鸟呼风。","纵令万里馀残魄，那得音书到海东。"]},{"t":"寄雪肠","f":"七言律诗","c":["曾向江头见苦吟，隋堤风雨独相寻。","生来鹿豕山中性，死却鸳鸯水上心。","白发庭闱留彩袖，黄沙天地裂青衿。","如何问道长边戍，血满袈裟月满岑。"]},{"t":"怀薪夷","f":"七言律诗","c":["长剑萧萧短后衣，平生一诺去如飞。","千人性命天何惜，壮士心肝泪亦挥。","狂态岂宜依辇毂，孤身无复访庭闱。","边风寂历添愁思，秋月圆时望尔归。"]},{"t":"再题苏筑斋","f":"七言律诗","c":["案有乾萤筴有鱼，风来恰受半窗虚。","一时差胜苏卿窖，千古应传扬子居。","禾黍已深妨远目，儿童屡进授新书。","生涯只此聊终岁，更有何门好曳裾。"]},{"t":"偶成","f":"七言律诗","c":["中原无地可容身，塞外还生有道瞋。","世惟欲杀称知己，我亦自嫌真罪人。","半榻日光还是睡，一瓢诗句未全贫。","邻翁颇怪痴呆甚，饭熟时招喜过频。"]},{"t":"咏蝇","f":"七言律诗","c":["白拂频挥去复回，炎蒸无计避凉台。","赦文不见青衣报，病骨先烦吊客来。","苦抱兔尖酣墨汁，愿随骥尾绝尘埃。","眼看七月秋声急，满塞霜飞为尔哀。"]},{"t":"赠杨济明","f":"七言律诗","c":["共是孤身海上山，燕支一去不知还。","鸭江已作鸳鸯渚，翠幕仍同虎豹关。","桃李种成花更烂，诗书典尽粒方艰。","不禁更听琵琶怨，碎却青衫泪点班。"]},{"t":"遥哭笔山","f":"七言律诗","c":["记得梅花各一篇，暗风吹骨泪如泉。","几年白下予同宿，万丈黄垆尔独先。","总为江山能短气，曾因病难学逃禅。","相逢一笑无难事，只恐阎罗亦有边。"]},{"t":"遥哭群玉","f":"七言律诗","c":["客舍无人促膝时，传灯勒鼎总相期。","早知一世心归梦，恨不当年革裹尸。","残墨尚多留白下，孤魂应去到峨嵋。","还思患难君偏切，夜夜天山带雪悲。"]},{"t":"头","f":"七言律诗","c":["一个头颅我自题，硬如岩石贱如泥。","藁街亦可悬皆见，漆器何妨饮便迷。","磕破人间佛祖小，伸将天外日星低。","秪今暂把枯茆盖，休怨黄沙践马蹄。"]},{"t":"答","f":"七言律诗","c":["积劫逢人莫肯低，最宜强项白犹栖。","几乎为尔成仁别，幸不同伊认影迷。","狮子已将偿宿债，严颜何惜掷淤泥。","从来羞比毗卢顶，除却朱衣任品题。"]},{"t":"眼","f":"七言律诗","c":["湛如秋水大如箕，何事年来血乱披。","烁破三千尘数点，阅穷万卷电交驰。","几人世上休教白，片石山头尚可垂。","此日风沙吹满面，幸留冰鉴照双眉。"]},{"t":"答","f":"七言律诗","c":["千个何曾羡大悲，通身皆是顶门奇。","勘残佛祖难留髓，看到人民便皱眉。","百劫春光宁转瞬，两行寒泪每交颐。","嵯峨石壁几穿破，笑杀西来碧眼儿。"]},{"t":"鼻","f":"七言律诗","c":["端然岳立在中央，当面逢人绝覆藏。","世上共推能作祖，梦中元不羡为郎。","聪明久让安无事，定静唯闻戒有香。","莫为此时难尽掩，故教寒塞嗅清霜。"]},{"t":"答","f":"七言律诗","c":["上天无臭却相忘，穿拽从人也不妨。","舌拄梵宫甘自下，眼澄巨海列于旁。","居亭最爱芝兰室，空洞终为蝼蚁乡。","一息不来天下事，任他蜗角逞豪强。"]},{"t":"耳","f":"七言律诗","c":["此方惟汝选圆通，顺逆都忘信朔风。","不遇神尧休用洗，再参马祖却教聋。","繁声若逐同流转，本寂才趋又堕空。","谩说返闻闻自性，琵琶哀怨佩玲珑。"]},{"t":"答","f":"七言律诗","c":["曾闻大吕与黄钟，莫厌巴歌调不同。","雪后木人深话月，墓前石马乱嘶风。","声从隔壁钗环坠，听到无弦山水空。","音响不来吾不往，十方击鼓自蓬蓬。"]},{"t":"口","f":"七言律诗","c":["多言多败尔惟辜，舌在徒然吻欲枯。","吸尽西江波正淼，说穷大藏字元无。","三缄不受金人戒，午夜时同望帝呼。","晴雪吞毡知味后，肯将钟鼎易秋荼。"]},{"t":"答","f":"七言律诗","c":["千家一钵亦良图，王膳虽逢味不殊。","只把笑言当大斧，虚传咳唾落明珠。","睢阳抉齿万年白，若水挝唇两片朱。","舌上纵饶莲十丈，于今用得半毫无。"]},{"t":"手","f":"七言律诗","c":["万里空拳出塞时，一枝竹杖不相携。","翻云覆雨看人世，运水搬柴学祖师。","龙藏搜穷没可把，凤楼修就亦奚为。","只今两肘捉襟见，黄叶拈来诳小儿。"]},{"t":"答","f":"七言律诗","c":["灵山会上撚花枝，金色头陀也不知。","指月几人能举首，捧天乏力自支颐。","空谈尽日犹扪虱，狂梦无端欲截螭。","岂有神方悬肘后，却思到处起疮痍。"]},{"t":"腹","f":"七言律诗","c":["空洞曾无一物遗，君亲两字尚撑支。","陈公但指知难改，苏子时扪不合宜。","二酉装来宁剩滓，八弦收入只馀悲。","年来渐觉肝肠冷，浇尽长边雪几卮。"]},{"t":"答","f":"七言律诗","c":["销尽精神独裹痴，只今犹自累人支。","松生久绝三公梦，薇采还留二士饥。","书卷抛残曾用曝，山云遇著便堪披。","最嫌一点惟明白，饮泪吞声只自知。"]},{"t":"足","f":"七言律诗","c":["萧然两只草鞋轻，肯向如来行处行。","踏碎神州无剩土，踢翻灵鹫敢容情。","卞和不泣原非玉，孙子虽膑莫论兵。","多少名山存未得，又随风雪到边城。"]},{"t":"答","f":"七言律诗","c":["与我周旋一世情，无烦剑履梦中荣。","刚锤乱下骨孤抵，好月能来屣倒迎。","列子御风嫌局蹐，云门跛脚发铿轰。","年来暂把冰霜践，岐路何时可荡平。"]},{"t":"身","f":"七言律诗","c":["白云只合住青山，一出青山便不閒。","梦幻了知无大患，苦甘尝尽信多艰。","陋形岂羡麒麟阁，短策真轻虎豹关。","世上沧桑原瞬息，更因何事泪潸潸。"]},{"t":"答","f":"七言律诗","c":["明知旅泊在人间，刀锯从他只有顽。","直到极边方彻骨，得逢好友便开颜。","百年怪事空中电，一片孤情海上山。","但使五灯能续燄，玉门何必愿生还。"]},{"t":"心","f":"七言律诗","c":["吟到先生不可名，一钩新月挂三星。","破颜自此成多事，断臂徒然卒未宁。","魔佛拣开知梦幻，贤奸混合亦顽冥。","只今面目归何处，大雪绥绥下朔庭。"]},{"t":"答","f":"七言律诗","c":["无可酬君君漫听，全超寂寂与惺惺。","黄头碧眼浑难见，白牯狸奴赖独醒。","代代宗传灯上焰，重重华藏水中萍。","未来过现何从得，云满峰头月满瓶。"]},{"t":"自挽二首 其一","f":"七言律诗","c":["肠付饥乌肉付泥，勿为厉鬼闹东鞮。","寒冰热铁家常饭，马腹驴胎尔稳栖。","心大不须皈净土，骨残倖免梦中闺。","纤毫锐气销难尽，祇恐长天化作霓。"]},{"t":"自挽二首 其二","f":"七言律诗","c":["世界三千任所之，林林何处不生悲。","一枝竹杖知难带，万顷愁云依旧随。","定上鼎湖新鬼泣，旋归庾岭小儿嬉。","多年已是冰霜惯，莫畏寒边苦欲离。"]},{"t":"读宗尉寄戴子书有感","f":"七言律诗","c":["只字翻令百感增，看君直欲上云层。","世间乃复见朋友，塞外只今馀病僧。","孤骨抵穷千丈雪，北风吹老一枝藤。","不须重问长安日，收拾残魂卧佛灯。"]},{"t":"寄赠宗尉","f":"七言律诗","c":["此道于今竟莫论，当年鲍叔幸犹存。","气倾渤海潮头水，手挽阴山雪底魂。","白草尚多缠野恨，黄沙无计借馀暄。","人间岂必奇男子，肯惜春风散五原。"]},{"t":"至前一日同诸子过雪斋因闻再举子","f":"七言律诗","c":["相携莫怯晓风吹，盼盼天回一线期。","田到荒年偏种玉，松于雪际更生枝。","因多男子嫌多累，不愿公卿但愿痴。","团坐竟忘寒彻骨，敲冰共和洗儿诗。"]},{"t":"同诸子过寿大翁","f":"七言律诗","c":["逻娑残魄又重圆，霜散冰丸贮瓦盘。","春草有诗康乐老，白莲无酒远公寒。","世间应厌长生苦，坑底还馀尽日欢。","却忆去年歌笑续，漫漫何处泪孤弹。"]},{"t":"辛卯生日","f":"七言律诗","c":["冷山流递几经年，此日看身益惘然。","瓶钵无心随积雪，松楸有恨抱终天。","裂裾欲续西征记，破帽长歌正气篇。","自笑出家馀习在，人间斯道只如线。"]},{"t":"寿苏筑","f":"七言律诗","c":["不厌人间水半卮，独将枯杖问须眉。","鸡窗冷淡存馀雪，鹿野荒沉出别枝。","歌满关河聊当哭，食残铁石好支饥。","旧时閒梦应频见，却恨残年叹未衰。"]},{"t":"贺弘甫三首 其一","f":"七言律诗","c":["燕支千丈赤云生，寒谷珊珊响佩琼。","彩笔翻将琴瑟谱，金笳吹作凤凰声。","香笼宝马星方烂，雪映长蛾山更明。","郑监图中添五色，春风连夜入边城。"]},{"t":"贺弘甫三首 其二","f":"七言律诗","c":["玉面珠缨金作鞿，桃花如阵锦城围。","堂前已见垂垂老，枕上休歌缓缓归。","钗钏全沾边雪冷，羹汤应进塞酥肥。","龙庭亦是神仙窟，烛影双双舞彩衣。"]},{"t":"贺弘甫三首 其三","f":"七言律诗","c":["寒冰四面照芙蓉，貂氅新沾香雾浓。","黑水竟通星宿海，白山化作丈人峰。","鸾飞未觉三边险，莺语何妨九译重。","之子之来谁最望，解将杂佩禦残冬。"]},{"t":"怀区启图","f":"七言律诗","c":["三代论交有几人，十年不见转成尘。","肯将白眼看他世，无复青山置此身。","只字俱堪存梵箧，五灯终恨误儒绅。","诃林旧社知荒草，雪满关河泪满巾。"]},{"t":"怀邝湛若","f":"七言律诗","c":["雨雪弥天却忆公，乡关无路问冥鸿。","行藏半在梅花里，事业空归楮叶中。","已恐须眉能作祟，只疑笔墨化为虹。","此身不共沧波去，更对何人理旧桐。"]},{"t":"喜我存病间","f":"七言律诗","c":["病来方觉一身孤，未死翻令转郁纡。","被薄每劳风缱绻，道穷争怪鬼揶揄。","枕边残卷供馋鼠，壁上幽灯照腐儒。","但使昨宵馀喘尽，游魂应到旧山隅。"]},{"t":"得姚雪庵书","f":"七言律诗","c":["暮钟破寺逢君处，瓦钵浮桥乞食归。","别久不知生与死，书来三读是耶非。","鹅城细雨怀孤衲，雁碛残魂忆下帏。","见说弟昆齐向道，何年同掩旧山扉。"]},{"t":"得光半雪盛二公书","f":"七言律诗","c":["曾随花雨即分裾，共效杨岐力有馀。","一夜几深塞下雪，十年才接岭南书。","菩提坛下心难了，苛子林中月久疏。","闻道琼崖鞋踏破，不将沉水寄荒居。"]},{"t":"读左公徂东集","f":"七言律诗","c":["秋风一见泪纷披，可柰重歌出塞词。","百济河山愁到处，三韩文献幸今兹。","屈平既放天何问，杜甫无家别有诗。","方信当年身不死，千秋斯道已如丝。"]},{"t":"步左公赠韵二首 其一","f":"七言律诗","c":["万里相逢水一杯，须眉霜积面生埃。","草鞋已破赵州老，布帽新成管子来。","漠漠寒云沉大野，纷纷荒雪落空台。","幸馀古道照颜色，狼藉床头书作堆。"]},{"t":"步左公赠韵二首 其二","f":"七言律诗","c":["坚冰堪嚼佛堪烧，久矣无心问市朝。","骨冷自应投大漠，月明犹故照今宵。","苏卿杖节宁终海，韩子留衣尚在潮。","沟洫未填吾与若，空荒天地可寥寥。"]},{"t":"赠马居士","f":"七言律诗","c":["曾向山阴道上行，逢君兹夕泪俱盈。","吞毡应独怜苏子，涤器何人识长卿。","半局阅穷田海事，一壶消尽古今情。","还期禹穴同探去，乱石寒云拚此生。"]},{"t":"赠李居士","f":"七言律诗","c":["余家东越子西秦，沙碛论交亦旧因。","白雪啮穷方有味，黑貂敝尽不知贫。","虎溪屡过成三笑，麈柄频挥碎万人。","一卷南华堪卒岁，任他沧海几扬尘。"]},{"t":"余与大来苏筑俱生残冬感而赋此","f":"七言律诗","c":["肯从斯世问穷通，千载应知吾道东。","延龄共向蠹鱼窟，立命全归磨蝎宫。","不堪死地论生日，何意今人见古风。","异姓篪埙原匪偶，胚胎冰雪本来同。"]},{"t":"大雪宿白塔寺静公禅室","f":"七言律诗","c":["浮屠残铎旧朝遗，扶杖何须夙有期。","雪里敲门僧定后，松间振锡鹤归时。","一炉芋火三更话，七个蒲团百丈规。","壁上灯微钟鼓寂，寒襟如水自应知。"]},{"t":"再宿静公禅室","f":"七言律诗","c":["城边犹见未烧庵，重扣柴扃梦正酣。","畏客不除当路雪，采薇常带远山岚。","漫拈黄叶为清供，再剔残灯续夜谈。","半榻飕飕寒共被，枕头惟有旧经函。"]},{"t":"三宿静公禅室","f":"七言律诗","c":["一度相逢一度新，踏冰扪雪不嫌频。","暮烹野菌忘僧律，远插疏篱隔世尘。","白麈挥残寒塞月，黄鸡叫彻法堂春。","从今半席长虚待，到此应知无别人。"]},{"t":"得寒还札","f":"七言律诗","c":["敢向寒边叹索居，衰残难执化人裾。","曾同一窖终怜雪，已到中天却寄书。","生死既分情倍切，去留虽异罪仍俱。","竹林未便成荒棘，珍重逢人莫谩歔。"]},{"t":"同诸老夜话","f":"七言律诗","c":["枯藤到处拨荒莱，谁遣刑馀老殍来。","却怪少林空面壁，漫传北海亦浮杯。","谈深毡帐三声角，坐老寒炉一寸灰。","窗外雪花飞片片，莫将消息问村梅。"]},{"t":"辛卯岁除","f":"七言律诗","c":["辽东何以送残年，自汲寒泉奠昔贤。","子庆挂冠甘永遁，幼安坐榻久将穿。","幸馀坑烬分僧钵，不少山癯问法筵。","谁道西来真有意，漫拈白拂竖空烟。"]},{"t":"除夕怀诸子","f":"七言律诗","c":["亦是寻常朝复夕，何当兹夕倍愁予。","莫将爆竹惊穷鬼，只合烧桐煮白鱼。","朔雪自能填客梦，春风无望到吾庐。","可怜年尽寒难尽，土榻斜眠枕破书。"]},{"t":"壬辰元旦","f":"七言律诗","c":["起起今年恰在辰，罪夫幸不是贤人。","堂前钟鼓龙天会，被底冰霜骨肉亲。","两点尚馀隔岁泪，五更曾梦度江春。","龙庭色色还依旧，独有閒愁一片新。"]},{"t":"元旦大雪同苏筑赋","f":"七言律诗","c":["昨暮行过已隔年，相将长揖谢高天。","似怜穷佛添花雨，肯为寒儒铺白毡。","权作江梅当折赠，漫敲石火任烹煎。","饥肠宛转浇应遍，又是赓酬第一篇。"]},{"t":"南塔结制","f":"七言律诗","c":["坚冰渐解柳初黄，钝斧谁将劈巨荒。","但任疏狂留本色，不妨粗粝是家常。","千群龙象归华表，万里风沙建宝坊。","几向棒头明正眼，混同依旧浩茫茫。"]},{"t":"闻大来为假仆所劫","f":"七言律诗","c":["残编犹可度朝昏，四顾应知天意存。","窖底未容留点雪，枕边依旧剩空樽。","寒当彻骨诗方富，穷到尽头道愈尊。","独有老僧愁更剧，从今托钵向何门。"]},{"t":"闻同难民为虎所食","f":"七言律诗","c":["何须今日方怜若，一度边关即鬼门。","身死不烦蝇作吊，年凶惟见虎加飧。","只愁老瘦重遭斥，但免饥寒亦感恩。","白雪一杯魂未远，料应笑我骨犹存。"]},{"t":"闻耳叔弟尽节","f":"七言律诗","c":["大旗吹折海风寒，未了孤心骨已残。","遗训在兹宁有憾，浮沤于汝久无干。","原鸰血尽生逾苦，池草根锄梦亦乾。","见说覆巢馀卵在，呱呱何处夜漫漫。"]},{"t":"答顺天师","f":"七言律诗","c":["梦里冠裳付劫灰，衲衣趺坐冷云堆。","悬崖有鸟衔花下，隔水何人问字来。","断碣远搜箕子墓，破鞋羞蹋李陵台。","相寻不为乡情重，白拂交横笑口开。"]},{"t":"白蜡梅花","f":"七言律诗","c":["十年负却旧山期，绝塞谁拈此一枝。","有骨莫愁冰雪沁，无香休惹蝶蜂疑。","魂飘万里村俱幻，梦到三更月共知。","最好不关开落事，楼头玉笛漫孤吹。"]},{"t":"千山偶成","f":"七言律诗","c":["枕石欹眠覆短松，到来时有鹿麋踪。","边愁浣尽山山雪，乡梦敲残夜夜钟。","一钵野蔬消不了，半龛寒月幸能容。","故人相忆如相问，只恐携云过别峰。"]},{"t":"李公初度集洪福庵为陈氏披薙时重阳后一日","f":"七言律诗","c":["昨日登临笑语亲，今来又恰趁芳辰。","采将菊蕊犹堪献，赎得蛾眉始是贫。","满院钟催新佛子，一天霜罩旧词臣。","老僧不及笼中鸽，仍带寒云系海滨。"]},{"t":"步韵和李公自寿诗","f":"七言律诗","c":["偶然一现宰官身，勋业从今问野人。","半局乾坤能共老，一樽贤圣欲偕春。","木天残梦风吹尽，白板深秋杖过频。","谑语狂歌俱可纪，世间除此即非真。"]},{"t":"大翁招同觞李公","f":"七言律诗","c":["行过竹杖自忘疲，霜满袈裟酒满卮。","篱下又多一日乐，炉边何必十年期。","谈深不及人间世，禅喜时添袖里诗。","二老孤僧成底事，夜寒灯火漫敲棋。"]},{"t":"李公赎陈氏为尼三首 其二","f":"七言律诗","c":["净洗铅华迥不群，袈裟新换石榴裙。","几回卖镜凌寒雪，何意开笼见白云。","拨尽琵琶鸣晓磬，翻残贝叶惜回文。","十年抱志今方遂，多少须眉得似君。"]},{"t":"李公赎陈氏为尼三首 其三","f":"七言律诗","c":["不是流人泪亦横，夕阳荒草诉中情。","自抛家国甘心死，窃比冰霜彻底清。","玉麈柄边红粉净，孤鸾镜里白毫生。","从今唤醒梨花梦，收拾残魂礼佛名。"]},{"t":"过李公寓同锡侯夜话","f":"七言律诗","c":["半间茅屋古皇前，石火烧泉话旧缘。","冷月高悬居士榻，暗风斜吹孝廉船。","挑残灯碗钟来寺，敲罢棋枰雪满天。","共卧片毡拳作枕，布衾如铁夜如年。"]},{"t":"雪夜怀李公","f":"七言律诗","c":["钟尽灯微拥破衾，长宵独雪伴枯吟。","泥床白满予方卧，疏壁寒飘尔莫禁。","都尉已明三老意，邺侯未了十年心。","何时日出消残窖，洒作人间遍地霖。"]},{"t":"和谦受始见塞雪诗","f":"七言律诗","c":["寒天难曙角声催，被薄风停雪又来。","窖卧六年僧已老，窗飞数点客方猜。","乍如浪溅钱塘月，安得香飘庾岭梅。","赋罢不妨乘兴过，拨开粪火倒残杯。"]},{"t":"播船坚辞大法招相随乞戒喜示","f":"七言律诗","c":["不向天龙会里寻，空堂丈草漫沉吟。","田衣独耐长边冷，铁篴横吹太古音。","金色何妨三度舞，神光又见一腰深。","了知处处笙歌满，休悔从前错用心。"]},{"t":"义虫作么二子归海州有怀","f":"七言律诗","c":["橐笔经年意未穷，芒鞋紧峭任西东。","星文已见龙津合，电影终怜冀北空。","瓶贮天山山畔雪，锡飞辽海海门风。","何时拥毳团圞话，坐数寒更榾柮红。"]},{"t":"病归承李公以诗见讯用韵奉答","f":"七言律诗","c":["一从出塞骨先残，扶病归来怯路难。","寒雪有心依破衲，枯肠无力进朝飧。","呻吟亦可参清梵，诗句真同续命丹。","自是故人情独切，此间谁复问袁安。"]},{"t":"步韵和丽大师寄怀诗","f":"七言律诗","c":["艰难百折两人同，旧话峰头愿不空。","佛似一家传世业，天教五国大门风。","此心肯共沧波去，片纸长留朔雪中。","万里遥遥情脉脉，岭云边月望何穷。"]},{"t":"弼臣病阻白门两次寄书并诗因成二章兼次其韵 其一","f":"七言律诗","c":["惊传一纸到辽阳，旧国楼台种白杨。","我友尽亡惟汝在，而师更苦复余伤。","孤舟卧老长干月，破衲披残大漠霜。","共是异乡生死隔，西风吹泪不成行。"]},{"t":"弼臣病阻白门两次寄书并诗因成二章兼次其韵 其二","f":"七言律诗","c":["两度书来僧正眠，石头仍系孝廉船。","交情尚拟还乡曲，病骨先残出塞前。","旧阁遗经难可问，覆巢馀卵复谁怜。","幸留花雨沾新冢，始信雷峰别有天。"]},{"t":"高含章出塞访友","f":"七言律诗","c":["拂袖离家出玉门，故人何处骨应存。","长边自尔无艰险，异姓于今有弟昆。","觅窖已扪千岭雪，招辞兼得一僧魂。","残毡欲尽难分供，春老荷锄掘草根。"]},{"t":"游香岩寺","f":"七言律诗","c":["千峰顶上香岩寺，积雪何年古道堙。","航海尚传元学士，登台空揖石仙人。","宝幢雨洗灯方续，禅榻云封草渐新。","伫望双飞天外锡，寒边早布十分春。"]},{"t":"送明藏主同大茎尸林二子南行","f":"七言律诗","c":["南询万里雪风乾，拄杖如龙路不难。","欲向曹溪掬香水，好从长庆礼蒲团。","刺桐花底分麋影，荔子枝头乞鸟残。","想得别峰相见处，定应先问塞儿寒。"]},{"t":"因事似我存","f":"七言律诗","c":["金石繇来未易论，多情翻怪别疏亲。","伤心此日弃如土，绝漠相看剩几人。","幸以艰难存道味，何妨怒骂烂天真。","胸怀但使同空水，始信天涯必有邻。"]},{"t":"赠陈令公二首 其一","f":"七言律诗","c":["凫飞出塞及春晴，望见前驱老鹤惊。","学道定知君子爱，受廛俱愿圣人氓。","锦囊尚带花香气，竹马还添水月情。","草昧经纶文事重，行看大窖起歌声。"]},{"t":"赠陈令公二首 其二","f":"七言律诗","c":["本是双林大士家，来寻丁令问桑麻。","琴声冷递沙边月，雪瓣閒飘县里花。","虎豹挈儿初度水，人民连雨尽随车。","大荒到处应犁遍，一钵从今莫浪嗟。"]},{"t":"同苏筑谦受夜坐","f":"七言律诗","c":["似我安能不极边，何堪二子亦如然。","路遥自爱亲邻尽，世难同伤祖父贤。","只恐冥冥僵雪底，故应数数话灯前。","乾坤刀斧予无恨，生死文章各勉旃。"]},{"t":"寒食偕诸子访苗李二鍊师归见木斋留诗同赋","f":"七言律诗","c":["杖头安得纸为钱，漠漠风吹寒食天。","野哭又添沙上鬼，暮归因问洞中天。","骑驴人去空留句，坐客床馀未啮毡。","三辅遥传榆柳尽，何须待禁久无烟。"]},{"t":"风雨怀我存","f":"七言律诗","c":["肯教一日不相闻，风雨萧萧咫尺分。","乡梦久残思转剧，砚田渐熟恨方殷。","抛书乍可寻黄鹄，陟屺无劳望白云。","桃李成蹊春已老，为君何事泪纷纭。"]},{"t":"送高含章","f":"七言律诗","c":["故人一见即回程，万里风沙两屐轻。","袖里新诗惟独咏，匣中长剑莫教鸣。","翻怜野鹤无高举，谁信冥鸿有至情。","归去不须重记忆，天山积雪梦犹惊。"]},{"t":"喜贵庵托钵回","f":"七言律诗","c":["镇日相寻屐齿频，经年始见意逾新。","一瓢尚带书生气，两袖新携上国春。","看尽空花曾可摘，探穷宝藏总成尘。","故乡田地从来稳，不到无锥未是贫。"]},{"t":"浴佛日寿陈令君二首 其一","f":"七言律诗","c":["萧萧匹马度龙荒，翘首真同白象王。","冰雪尚酬文佛债，梅檀新浴令公香。","尽销兵气为农具，好借僧瓢进鹤觞。","却笑河阳空满县，昙花一朵现辽阳。"]},{"t":"浴佛日寿陈令君二首 其二","f":"七言律诗","c":["现身仍是旧王宫，荒草颓垣不厌穷。","户口疑从兜率下，威仪尚与汉官同。","量晴较雨推新政，翻贝寻僧本素风。","云水满堂春满野，乐郊今在大关东。"]},{"t":"唁","f":"七言律诗","c":["灯前雪底亦空言，寒泪无端湿五原。","大道翻嫌诸圣浅，奇情难与老僧论。","平生最苦肝肠热，今日方知裘马尊。","不是唁君惟自唁，悠悠终恐骨孤存。"]},{"t":"即事似大翁木斋谦公诸同志二首 其一","f":"七言律诗","c":["心比苍松化石坚，迷卢却被一丝牵。","蝇头尽是英雄冢，牛后须防牧竖鞭。","只此须眉何可卖，任他沟壑尽堪传。","几人绝塞身还在，忍使残僧泪独溅。"]},{"t":"即事似大翁木斋谦公诸同志二首 其二","f":"七言律诗","c":["今古繇来梦幻中，书生端合置鹅笼。","已闻越女兴勾践，难把铜山铸邓通。","虫死断编终不恶，门馀积雪岂真穷。","人间何贵有朋友，到此怜予道未工。"]},{"t":"同谦公谈","f":"七言律诗","c":["我亦流民尔似僧，半床明月半床□。","□□□难聊相共，常恐肝肠未可凭。","天外幸能留破衲，世间岂尽丧良朋。","谈深舌冷书为枕，肯负中宵一椀灯。"]},{"t":"偶成","f":"七言律诗","c":["寒灯一点暂相亲，除梦都应不是真。","开口后来皆作圣，盖棺前此莫论人。","鬼神未到须防独，涓滴虽微便溺身。","纵死定令天亦见，肯教风雨暗青燐。"]},{"t":"冒雨访木斋不遇","f":"七言律诗","c":["草团风送雁归声，孤负春深雨未晴。","戴笠独行韩大伯，到门不见李先生。","若非策蹇寻花笑，定是携诗倩鹤评。","为语小童多汲水，明朝清晓待余烹。"]},{"t":"赠赤公五首 其二","f":"七言律诗","c":["愿遍三千麈任挥，到来况是旧王畿。","亦知冰雪皆恩泽，谁道云烟省是非。","阙下已闻钟鼓遍，海东犹待雨花飞。","天龙翘首余多病，从此焚香老翠微。"]},{"t":"赠赤公五首 其三","f":"七言律诗","c":["满碛寒风柰若何，逢人强自笑还歌。","杖挑百斛燕支雪，瓶注千寻鸭绿波。","高座不妨群部拥，穷途真恨一身多。","近来分卫逢时稔，敝绪泥床亦好过。"]},{"t":"赠赤公五首 其四","f":"七言律诗","c":["狮子曾闻住罽宾，如空何必问前因。","霜连白草开荒后，日射黄金布地新。","旧疏未焚藏衲角，长歌应悔杂京尘。","当时妙喜交游广，书到衡阳有几人。"]},{"t":"赠赤公五首 其五","f":"七言律诗","c":["而师亦是岭南人，共棹曹溪意自亲。","罪过弥天予作俑，饥寒到死汝为邻。","生成枯骨非关病，剩有空瓢不道贫。","何日玉门通一线，愿随高步抖边尘。"]},{"t":"喜文玄参方因请藏回","f":"七言律诗","c":["江北江南是旧游，狰狞如虎静如秋。","去携只杖同黄鹄，归拥三车尽白牛。","五位诸方俱已厌，千家一钵更何忧。","从今收拾西来意，屋里青山好白头。"]},{"t":"寄大翁","f":"七言律诗","c":["几年何日不相见，相见应知各有诗。","公到苦吟予独赏，余当狂叫汝深悲。","寻常只道穷边事，隔别应生静夜思。","始觉寒冰良匪偶，千秋万古有人知。"]},{"t":"寄昭公","f":"七言律诗","c":["莫怪崎岖出塞行，犹将贝叶伴馀生。","茆堂独喜留山野，枫陛能无忆老成。","浮世谩论千古重，苍生甚切一身轻。","关门不日牵雏去，会见联翩彩袖迎。"]},{"t":"寄乾公","f":"七言律诗","c":["挈杖寻君君未归，君归余又掩山扉。","身閒未许长看剑，露冷何须短后衣。","叹息三良身莫赎，经营半亩事仍非。","低头且就衡门下，静卧西风待晓晖。"]},{"t":"寄龙公","f":"七言律诗","c":["未曾相识即相思，咫尺寒云阻晤期。","青琐梦回霜正满，苍生感极泪俱垂。","敢言又见同人至，此念终当圣主知。","见说长安书一纸，浮沉莫使恐山麋。"]},{"t":"寄雪公","f":"七言律诗","c":["惊骑羸马度荒峦，风冽衣残獬豸寒。","面带天山悬洞雪，气分巫峡泻秋湍。","四愁赋就教儿读，五叶参来把剑看。","直待丹青高阁后，好携孤衲笑飞鸾。"]},{"t":"寄苏公","f":"七言律诗","c":["春风一别年将尽，相忆空传半截诗。","想尔独吟逢客到，及余来访又他之。","门前老仆担新雪，灶上寒灰覆旧磁。","见说我行君便返，人生离恨是今兹。"]},{"t":"寄我公","f":"七言律诗","c":["布帽疏棂雪积须，砚田半熟谩长吁。","看君此意存三代，念我当年共一盂。","壁倒不妨麋鹿入，道穷终怯马牛呼。","残冬暂耐寒将尽，自有春风动破襦。"]},{"t":"寄孝公","f":"七言律诗","c":["君到荒山云已出，我寻破壁砚仍馀。","三更共卧吹残骨，几日重离恨索居。","采药已惊林有豹，弹琴何患食无鱼。","为君仔细谋生事，毕竟无过读父书。"]},{"t":"寄谦公","f":"七言律诗","c":["岁岁年年愁雪下，年年岁岁望云飞。","风吹寸草心俱碎，手把残编腹又饥。","朋好几人予最老，乡关万里日还晖。","梦中频见应频问，果是人归是梦归。"]},{"t":"赠冯公","f":"七言律诗","c":["静如秋月气如潮，未老惊看鬓渐凋。","挟策长歌来远碛，辞家短剑自前朝。","巫闾烟雨题千尺，沧海风沙见一毛。","但使旧乡看昼锦，急将双袖伴僧瓢。"]}]};